   7: // ============ Store management · Banners & Slider ============
   8: 
   9: export interface BannerItem {
  10:   id: string;
  11:   title: string;
  12:   placement: 'slider' | 'middle' | 'popup';
  13:   image?: string | null;
  14:   linkType: 'none' | 'product' | 'category' | 'brand' | 'external';
