  17:   sort: number;
  18:   start: string;
  19:   end: string;
  20:   active: boolean;
  21:   linkLabel?: string | null;
  22:   status?: 'live' | 'scheduled' | 'expired' | 'disabled';
  23:   kicker?: string;
  24:   headline?: string;
  25:   headlineBold?: string;
  26:   description?: string;
  27:   ctaLabel?: string;
  28:   bgColor?: string;
  29:   imageFile?: File | null;
  30: }
  31: 
  32: export const BN_PLACEMENTS: Record<string, { label: string; icon: string; ratio: string; hint: string }> = {
  33:   slider: { label: 'السلايدر الرئيسي', icon: 'slides', ratio: '16 / 6', hint: 'صور تتقلّب في أعلى واجهة المتجر — كل صورة بانر مستقل' },
  34:   middle: { label: 'بانرات وسط الصفحة', icon: 'mid', ratio: '16 / 5', hint: 'صور إعلانية بين أقسام الصفحة الرئيسية' },
  35:   popup: { label: 'النوافذ المنبثقة', icon: 'popup', ratio: '4 / 5', hint: 'تظهر للزائر فوق محتوى المتجر' },
  36: };
  37: 
  38: export const BN_LINK_TYPES: Record<string, { label: string; icon: string }> = {
  39:   none: { label: 'بدون رابط', icon: 'slash' },
  40:   product: { label: 'منتج', icon: 'box' },
  41:   category: { label: 'قسم', icon: 'grid' },
  42:   brand: { label: 'براند', icon: 'tag' },
  43:   external: { label: 'رابط خارجي', icon: 'external' },
  44: };
  45: 
  46: export function bnStatus(b: BannerItem): 'disabled' | 'scheduled' | 'expired' | 'live' {
  47:   if (b.status) return b.status;
  48:   const now = new Date();
  49:   if (!b.active) return 'disabled';
  50:   if (b.start && new Date(b.start) > now) return 'scheduled';
  51:   if (b.end && new Date(b.end) < now) return 'expired';
  52:   return 'live';
  53: }
  54: 
  55: export const BN_STATUS: Record<string, { label: string; cls: string }> = {
  56:   live: { label: 'ساري', cls: 'b-green' },
  57:   scheduled: { label: 'مجدول', cls: 'b-blue' },
  58:   expired: { label: 'منتهي', cls: 'b-amber' },
  59:   disabled: { label: 'معطّل', cls: 'b-gray' },
  60: };
  61: 
  62: export const bnDate = (s?: string) => {
  63:   if (!s) return null;
  64:   const d = new Date(s);
  65:   return {
  66:     d: d.toLocaleDateString('en-GB', { day: '2-digit', month: '2-digit', year: 'numeric' }),
  67:     t: d.toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit' }),
  68:   };
  69: };
  70: 
  71: export function bnTarget(b: BannerItem): string | null | undefined {
  72:   if (b.linkLabel) return b.linkLabel;
  73:   switch (b.linkType) {
  74:     case 'external': return b.url;
  75:     default: return null;
  76:   }
  77: }
