  79: // ---------- Thumbnail / Art ----------
  80: export function BannerArt({ b, ratio, big }: { b: Partial<BannerItem>; ratio?: string; big?: boolean }) {
  81:   const [failedImage, setFailedImage] = useState<string | null>(null);
  82:   if (b.image && failedImage !== b.image) {
  83:     return <img src={b.image} alt={b.title || ''} onError={() => setFailedImage(b.image ?? null)} className="w-full h-full object-cover" />;
  84:   }
  85:   return (
  86:     <div
  87:       className="w-full h-full relative overflow-hidden flex flex-col justify-center select-none"
  88:       style={{
  89:         background: b.bgColor || 'var(--bg-subcard)',
  90:         color: 'var(--text-primary)',
  91:         padding: big ? '6% 7%' : '0 9%',
  92:         aspectRatio: ratio,
  93:       }}
  94:     >
  95:       <div className="relative font-display font-bold leading-tight" style={{ fontSize: big ? 26 : 12 }}>{b.title || 'معاينة البانر'}</div>
  96:     </div>
  97:   );
  98: }
