 100: // ---------- Store Preview Device Mockup ----------
 101: export function StorePreview({ tab, live }: { tab: 'slider' | 'middle' | 'popup'; live: BannerItem[] }) {
 102:   const [i, setI] = useState(0);
 103: 
 104:   useEffect(() => { setI(0); }, [tab, live.length]);
 105: 
 106:   useEffect(() => {
 107:     if (tab !== 'slider' || live.length < 2) return;
 108:     const t = setInterval(() => setI(x => (x + 1) % live.length), 2600);
 109:     return () => clearInterval(t);
 110:   }, [tab, live.length]);
 111: 
 112:   const cur = live[i];
 113:   const frame = (children: React.ReactNode) => (
 114:     <div className="v-subcard p-2.5" style={{ borderRadius: 18 }}>
 115:       <div className="rounded-[12px] overflow-hidden" style={{ background: 'var(--bg-card)', boxShadow: '0 0 0 1px var(--border-subtle)' }}>
 116:         <div className="flex items-center gap-1.5 px-3 py-2 v-border-b">
 117:           <span className="w-2 h-2 rounded-full" style={{ background: 'var(--badge-gray-bg)' }} />
 118:           <span className="w-2 h-2 rounded-full" style={{ background: 'var(--badge-gray-bg)' }} />
 119:           <span className="w-2 h-2 rounded-full" style={{ background: 'var(--badge-gray-bg)' }} />
 120:           <span className="flex-1 mx-2 h-3.5 rounded-full" style={{ background: 'var(--bg-subcard)' }} />
 121:         </div>
 122:         {children}
 123:       </div>
 124:     </div>
 125:   );
 126: 
 127:   const none = (
 128:     <div className="rounded-lg flex items-center justify-center text-[11px] c-muted hatched" style={{ aspectRatio: '16 / 6' }}>
 129:       لا يوجد بانر ساري
 130:     </div>
 131:   );
 132: 
 133:   const blocks = (n: number) => (
 134:     <div className="grid grid-cols-4 gap-1.5 p-2.5">
 135:       {Array.from({ length: n }).map((_, k) => (
 136:         <div key={k} className="aspect-square rounded-md" style={{ background: 'var(--bg-subcard)' }} />
 137:       ))}
 138:     </div>
 139:   );
 140: 
 141:   if (tab === 'slider') {
 142:     return frame(
 143:       <>
 144:         <div className="p-2.5 pb-0">
 145:           {cur ? (
 146:             <div className="rounded-lg overflow-hidden relative" style={{ aspectRatio: '16 / 6' }}>
 147:               <div key={cur.id} className="absolute inset-0 fade-in">
 148:                 <BannerArt b={cur} />
 149:               </div>
 150:             </div>
 151:           ) : none}
 152:           <div className="flex items-center justify-center gap-1 py-2">
 153:             {live.map((b, k) => (
 154:               <button
 155:                 key={b.id}
 156:                 type="button"
 157:                 onClick={() => setI(k)}
 158:                 className="h-1.5 rounded-full transition-all"
 159:                 style={{ width: k === i ? 16 : 6, background: k === i ? 'var(--accent-orange)' : 'var(--badge-gray-bg)' }}
 160:               />
 161:             ))}
 162:           </div>
 163:         </div>
 164:         {blocks(4)}
 165:       </>
 166:     );
 167:   }
 168: 
 169:   if (tab === 'middle') {
 170:     return frame(
 171:       <>
 172:         {blocks(4)}
 173:         <div className="px-2.5 space-y-1.5">
 174:           {live.length ? live.map(b => (
 175:             <div key={b.id} className="rounded-lg overflow-hidden" style={{ aspectRatio: '16 / 5' }}>
 176:               <BannerArt b={b} />
 177:             </div>
 178:           )) : none}
 179:         </div>
 180:         {blocks(4)}
 181:       </>
 182:     );
 183:   }
 184: 
 185:   return frame(
 186:     <div className="relative">
 187:       {blocks(8)}
 188:       <div className="absolute inset-0 flex items-center justify-center" style={{ background: 'rgba(0,0,0,.45)' }}>
 189:         {live[0] ? (
 190:           <div className="w-[48%] rounded-lg overflow-hidden relative shadow-2xl" style={{ aspectRatio: '4 / 5' }}>
 191:             <BannerArt b={live[0]} />
 192:             <span className="absolute top-1.5 left-1.5 w-4 h-4 rounded-full bg-white/90 text-black flex items-center justify-center text-[10px]">✕</span>
 193:           </div>
 194:         ) : (
 195:           <span className="text-[11px] text-white/80">لا توجد نافذة سارية</span>
 196:         )}
 197:       </div>
 198:     </div>
 199:   );
 200: }
