 222: // ---------- Banner Form Modal ----------
 223: interface BannerFormProps {
 224:   open: boolean;
 225:   initial: BannerItem | null;
 226:   defaultPlacement: 'slider' | 'middle' | 'popup';
 227:   onClose: () => void;
