 231: function BannerForm({ open, initial, defaultPlacement, onClose, onSave }: BannerFormProps) {
 232:   const blank: Omit<BannerItem, 'id'> = {
 233:     title: '',
 234:     image: null,
 235:     placement: defaultPlacement,
 236:     linkType: 'none',
 237:     linkId: null,
 238:     url: '',
 239:     sort: 1,
 240:     start: '',
 241:     end: '',
 242:     active: true,
 243:   };
 244: 
 245:   const [f, setF] = useState<any>(blank);
 246:   const [sortStr, setSortStr] = useState('1');
 247:   const [err, setErr] = useState<Record<string, string | null>>({});
 248:   const [upl, setUpl] = useState({ state: 'idle', pct: 0, name: '', msg: '' });
 249:   const [busy, setBusy] = useState(false);
 250:   const fileRef = useRef<HTMLInputElement>(null);
 251:   const objectUrlRef = useRef<string | null>(null);
 252:   const [catOpts, setCatOpts] = useState<Array<{ value: string; label: string }>>([]);
 253:   const [prodOpts, setProdOpts] = useState<Array<{ value: string; label: string }>>([]);
 254:   const [prodQuery, setProdQuery] = useState('');
 255: 
 256:   const revokePreview = () => {
 257:     if (objectUrlRef.current) { URL.revokeObjectURL(objectUrlRef.current); objectUrlRef.current = null; }
 258:   };
 259:   const closeForm = () => { revokePreview(); onClose(); };
 260: 
 261:   useEffect(() => () => revokePreview(), []);
 262:   useEffect(() => { if (!open) revokePreview(); }, [open]);
 263: 
 264:   useEffect(() => {
 265:     if (!open) return;
 266:     let alive = true;
 267:     adminApi.listBannerCategories().then((cats) => {
 268:       if (!alive) return;
 269:       const flat: Array<{ value: string; label: string }> = [];
 270:       const walk = (list: Array<{ id: number; name_ar: string; name_en: string | null; children?: unknown[] }>, depth: number) => {
 271:         list.forEach((c) => {
 272:           flat.push({ value: String(c.id), label: `${depth ? '— ' : ''}${c.name_en || c.name_ar}` });
 273:           if (Array.isArray(c.children)) walk(c.children as typeof list, depth + 1);
 274:         });
 275:       };
 276:       walk(cats as never, 0);
 277:       setCatOpts(flat);
 278:     }).catch(() => {});
 279:     return () => { alive = false; };
 280:   }, [open ]);
 281: 
 282:   useEffect(() => {
 283:     if (!open || f.linkType !== 'product') return;
 284:     const controller = new AbortController();
 285:     const t = setTimeout(() => {
 286:       adminApi.searchBannerProducts(prodQuery, controller.signal).then((ps) => {
 287:         if (controller.signal.aborted) return;
 288:         const opts = ps.map((p) => ({ value: String(p.id), label: p.name_en || p.name_ar }));
 289:         if (f.linkId && f.linkLabel && !opts.some((o) => o.value === f.linkId)) {
 290:           opts.unshift({ value: f.linkId, label: f.linkLabel });
 291:         }
 292:         setProdOpts(opts);
 293:       }).catch(() => {});
 294:     }, 300);
 295:     return () => { clearTimeout(t); controller.abort(); };
 296:   }, [open, f.linkType, f.linkId, f.linkLabel, prodQuery]);
 297: 
 298:   useEffect(() => {
 299:     if (!open) return;
 300:     if (initial) {
 301:       setF({ ...initial, status: undefined });
 302:       setSortStr(String(initial.sort));
 303:     } else {
 304:       setF({ ...blank, placement: defaultPlacement });
 305:       setSortStr('1');
 306:     }
 307:     setErr({});
 308:     setUpl({ state: 'idle', pct: 0, name: '', msg: '' });
 309:     setBusy(false);
 310:     setProdQuery('');
 311:   }, [open, initial, defaultPlacement]);
 312: 
 313:   const set = (k: string, v: any) => {
 314:     setF((p: any) => ({ ...p, [k]: v, status: undefined }));
 315:     if (err[k]) setErr(e => ({ ...e, [k]: null }));
 316:   };
 317: 
 318:   const startUpload = (file?: File) => {
 319:     if (!file) return;
 320:     if (!/^image\/(png|jpe?g|webp)$/.test(file.type)) {
 321:       setUpl({ state: 'error', pct: 0, name: file.name, msg: 'صيغة غير مدعومة. استخدم PNG أو JPG أو WEBP.' });
 322:       return;
 323:     }
 324:     if (file.size > 5 * 1024 * 1024) {
 325:       setUpl({ state: 'error', pct: 0, name: file.name, msg: 'حجم الصورة أكبر من 5 ميجابايت.' });
 326:       return;
 327:     }
 328:     revokePreview();
 329:     const url = URL.createObjectURL(file);
 330:     objectUrlRef.current = url;
 331:     setUpl({ state: 'done', pct: 100, name: file.name, msg: '' });
 332:     setF((p: any) => ({ ...p, image: url, imageFile: file }));
 333:   };
 334: 
 335:   const hasImage = Boolean(f.image);
 336: 
 337:   const validate = () => {
 338:     const e: Record<string, string> = {};
 339:     if (!f.title?.trim()) e.title = 'العنوان مطلوب';
 340:     if (!hasImage) e.image = 'ارفع صورة للبانر';
 341:     if (f.linkType === 'product' && !f.linkId) e.linkId = 'اختر المنتج';
 342:     if (f.linkType === 'category' && !f.linkId) e.linkId = 'اختر القسم';
 343:     if (f.linkType === 'brand' && !f.linkId) e.linkId = 'اختر البراند';
 344:     if (f.linkType === 'external') {
 345:       if (!f.url?.trim()) e.url = 'أدخل الرابط';
 346:       else if (!/^https:\/\/\S+\.\S+/.test(f.url.trim())) e.url = 'الرابط يجب أن يبدأ بـ https:// ويكون صالحًا';
 347:     }
 348:     if (sortStr === '') e.sort = 'أدخل ترتيب الظهور';
 349:     else if (!Number.isInteger(Number(sortStr)) || Number(sortStr) < 0 || Number(sortStr) > 9999) e.sort = 'الترتيب يجب أن يكون رقمًا من 0 إلى 9999';
 350:     if (f.start && f.end && new Date(f.end) <= new Date(f.start)) e.end = 'نهاية العرض يجب أن تكون بعد البداية';
 351:     return e;
 352:   };
 353: 
 354:   const submit = async () => {
 355:     if (busy || upl.state === 'uploading') return;
 356:     const e = validate();
 357:     setErr(e);
 358:     if (Object.keys(e).length) return;
 359:     setBusy(true);
 360:     setUpl(u => ({ ...u, state: 'uploading', pct: 0 }));
 361:     const apiErrs = await onSave({
 362:       ...f,
 363:       sort: Number(sortStr),
 364:       linkId: ['none', 'external'].includes(f.linkType) ? null : f.linkId,
 365:       url: f.linkType === 'external' ? (f.url || '').trim() : '',
 366:     }, (p) => setUpl(u => ({ ...u, state: 'uploading', pct: p })));
 367:     setBusy(false);
 368:     if (apiErrs) {
 369:       setUpl(u => ({ ...u, state: 'idle', pct: 0 }));
 370:       setErr(apiErrs);
 371:     }
 372:   };
 373: 
 374:   const P = BN_PLACEMENTS[f.placement] || BN_PLACEMENTS.slider;
 375: 
 376:   const targetField = () => {
 377:     const opts = f.linkType === 'product'
 378:       ? prodOpts
 379:       : f.linkType === 'category'
 380:       ? catOpts
 381:       : null;
 382: 
 383:     if (f.linkType === 'none') return null;
 384:     if (f.linkType === 'brand') {
 385:       return (
 386:         <div className="space-y-1.5">
 387:           <label className="text-[12.5px] font-semibold" style={{ color: 'var(--text-primary)' }}>البراند</label>
 388:           <div className="inp flex items-center justify-between" style={{ background: 'var(--bg-subcard)' }}>
 389:             <span>{f.linkLabel || f.linkId || '—'}</span>
 390:             <span className="badge b-gray">قديم</span>
 391:           </div>
 392:         </div>
 393:       );
 394:     }
 395:     if (f.linkType === 'external') {
 396:       return (
 397:         <div className="space-y-1.5">
 398:           <label className="text-[12.5px] font-semibold flex items-center justify-between" style={{ color: 'var(--text-primary)' }}>
 399:             <span>الرابط الخارجي <span className="c-orange">*</span></span>
 400:           </label>
 401:           <div className="relative">
 402:             <input
 403:               className={`inp mono text-left pl-9 ${err.url ? 'err' : ''}`}
 404:               dir="ltr"
 405:               value={f.url || ''}
 406:               onChange={e => set('url', e.target.value)}
 407:               placeholder="https://"
 408:             />
 409:             <span className="absolute left-3 top-1/2 -translate-y-1/2 c-muted">
 410:               <Icon name="external" className="w-3.5 h-3.5" />
 411:             </span>
 412:           </div>
 413:           {err.url && <div className="text-[11.5px] font-medium" style={{ color: 'var(--badge-red-text)' }}>{err.url}</div>}
 414:         </div>
 415:       );
 416:     }
 417:     return (
 418:       <div className="space-y-1.5">
 419:         <label className="text-[12.5px] font-semibold" style={{ color: 'var(--text-primary)' }}>
 420:           اختر ال{BN_LINK_TYPES[f.linkType]?.label} <span className="c-orange">*</span>
 421:         </label>
 422:         {f.linkType === 'product' && (
 423:           <input
 424:             className="inp"
 425:             value={prodQuery}
 426:             onChange={e => setProdQuery(e.target.value)}
 427:             placeholder="بحث عن منتج…"
 428:           />
 429:         )}
 430:         <select
 431:           value={f.linkId || ''}
 432:           onChange={e => set('linkId', e.target.value || null)}
 433:           className={`inp ${err.linkId ? 'err' : ''}`}
 434:         >
 435:           <option value="">اختر...</option>
 436:           {opts?.map(o => <option key={o.value} value={o.value}>{o.label}</option>)}
 437:         </select>
 438:         {err.linkId && <div className="text-[11.5px] font-medium" style={{ color: 'var(--badge-red-text)' }}>{err.linkId}</div>}
 439:       </div>
 440:     );
 441:   };
 442: 
 443:   if (!open) return null;
 444: 
 445:   return (
 446:     <div
 447:       className="fixed inset-0 z-[60] flex items-center justify-center p-4 fade-in"
 448:       style={{ background: 'rgba(0,0,0,.45)', backdropFilter: 'blur(4px)' }}
 449:       onMouseDown={e => e.target === e.currentTarget && !busy && closeForm()}
 450:     >
 451:       <div
 452:         className="v-card w-full shadow-2xl flex flex-col max-h-[92vh] v-pop-in"
 453:         style={{ maxWidth: 760 }}
 454:       >
 455:         <div className="flex items-start justify-between gap-4 p-6 pb-4 v-border-b">
 456:           <div>
 457:             <h3 className="font-display text-[19px] font-semibold c-primary">
 458:               {initial ? 'تعديل بانر' : 'إضافة بانر'}
 459:             </h3>
 460:             <p className="text-[12px] c-secondary mt-0.5">
 461:               {initial ? initial.title : `سيُضاف إلى «${P.label}»`}
 462:             </p>
 463:           </div>
 464:           <button
 465:             type="button"
 466:             onClick={closeForm}
 467:             disabled={busy}
 468:             className="w-8 h-8 rounded-full v-subcard flex items-center justify-center c-secondary hover:c-primary shrink-0 transition"
 469:           >
 470:             <Icon name="close" className="w-4 h-4" />
 471:           </button>
 472:         </div>
 473: 
 474:         <div className="px-6 py-5 overflow-y-auto flex-1 space-y-5">
 475:           {/* Title */}
 476:           <div>
 477:             <label className="block text-[12.5px] font-semibold mb-1.5" style={{ color: 'var(--text-primary)' }}>
 478:               العنوان <span className="c-orange">*</span>
 479:               <span className="text-[11px] font-normal c-muted mr-2">· للاستخدام الداخلي ولوصف الصورة</span>
 480:             </label>
 481:             <input
 482:               className={`inp ${err.title ? 'err' : ''}`}
 483:               value={f.title || ''}
 484:               onChange={e => set('title', e.target.value)}
 485:               placeholder="مثال: مجموعة الشتاء — خصم ٤٠٪"
 486:             />
 487:             {err.title && <div className="text-[11.5px] mt-1 font-medium" style={{ color: 'var(--badge-red-text)' }}>{err.title}</div>}
 488:           </div>
 489: 
 490:           {/* Image Upload */}
 491:           <div>
 492:             <div className="text-[12.5px] font-semibold mb-1.5" style={{ color: 'var(--text-primary)' }}>
 493:               الصورة <span className="c-orange">*</span>
 494:               <span className="text-[11px] font-normal c-muted mr-2">· PNG / JPG / WEBP حتى 5MB</span>
 495:             </div>
 496:             <input
 497:               ref={fileRef}
 498:               type="file"
 499:               accept="image/png,image/jpeg,image/webp"
 500:               className="hidden"
 501:               onChange={e => {
 502:                 if (e.target.files?.[0]) startUpload(e.target.files[0]);
 503:                 e.target.value = '';
