 505:             />
 506: 
 507:             {upl.state === 'uploading' ? (
 508:               <div className="v-subcard p-5 flex items-center gap-4" style={{ minHeight: 140 }}>
 509:                 <div className="flex-1">
 510:                   <div className="flex items-center justify-between text-[12.5px] mb-2">
 511:                     <span className="c-primary font-medium truncate">{upl.name}</span>
 512:                     <span className="num c-secondary">{Math.round(upl.pct)}%</span>
 513:                   </div>
 514:                   <div className="h-2 rounded-full hatched overflow-hidden">
 515:                     <div className="h-full rounded-full bar-hatched-orange transition-all" style={{ width: `${upl.pct}%` }} />
 516:                   </div>
 517:                   <div className="text-[11px] c-muted mt-2">جارٍ رفع الصورة…</div>
 518:                 </div>
 519:               </div>
 520:             ) : hasImage ? (
 521:               <div
 522:                 className="relative rounded-2xl overflow-hidden group"
 523:                 style={{ aspectRatio: P.ratio === '4 / 5' ? '16 / 7' : P.ratio, boxShadow: '0 0 0 1px var(--border-subtle)' }}
 524:               >
 525:                 {f.placement === 'popup' ? (
