 527:                     <div className="h-[88%] rounded-lg overflow-hidden" style={{ aspectRatio: '4 / 5' }}>
 528:                       <BannerArt b={f} big />
 529:                     </div>
 530:                   </div>
 531:                 ) : (
 532:                   <BannerArt b={f} big />
 533:                 )}
 534:                 <div className="absolute bottom-3 left-3 flex items-center gap-2">
 535:                   <button
 536:                     type="button"
 537:                     className="btn btn-sm shadow-md"
 538:                     style={{ background: 'rgba(255,255,255,.95)', color: '#18151c' }}
 539:                     onClick={() => fileRef.current?.click()}
 540:                   >
 541:                     <Icon name="refresh" className="w-3.5 h-3.5" /> استبدال الصورة
 542:                   </button>
 543:                 </div>
 544:                 {upl.state === 'done' && (
 545:                   <span className="absolute top-3 right-3 badge b-green">
 546:                     <Icon name="check" className="w-3 h-3" /> تم الرفع
 547:                   </span>
 548:                 )}
 549:               </div>
 550:             ) : (
 551:               <button
 552:                 type="button"
 553:                 onClick={() => fileRef.current?.click()}
 554:                 onDragOver={e => e.preventDefault()}
 555:                 onDrop={e => { e.preventDefault(); if (e.dataTransfer.files?.[0]) startUpload(e.dataTransfer.files[0]); }}
 556:                 className="w-full rounded-2xl flex flex-col items-center justify-center gap-2 transition hover:opacity-90 py-8"
 557:                 style={{
 558:                   border: `1.5px dashed ${err.image ? 'var(--badge-red-text)' : 'var(--border-strong)'}`,
 559:                   background: 'var(--bg-subcard)',
 560:                 }}
 561:               >
 562:                 <span className="w-11 h-11 rounded-full flex items-center justify-center" style={{ background: 'var(--bg-card)', color: 'var(--accent-orange)' }}>
 563:                   <Icon name="upload" className="w-5 h-5" />
 564:                 </span>
 565:                 <span className="text-[13px] font-semibold c-primary">اسحب الصورة هنا أو اضغط للاختيار</span>
 566:                 <span className="text-[11px] c-muted">
 567:                   المقاس المقترح لـ{P.label}: {f.placement === 'slider' ? '1920×720، وخلّي الـ 40% الشمال من الصورة هادية لو هتكتب نص' : f.placement === 'middle' ? '1920×600، وخلّي المحتوى المهم في النص' : '800×1000'}
 568:                 </span>
