 578:           </div>
 579: 
 580:           {/* Storefront display text */}
 581:           <div className="v-subcard p-4 space-y-3.5">
 582:             <div className="text-[12.5px] font-semibold" style={{ color: 'var(--text-primary)' }}>نصوص العرض في المتجر (اختياري)</div>
 583:             <div className="grid grid-cols-1 sm:grid-cols-2 gap-3.5">
