 589:                 <label className="text-[12px] font-semibold c-secondary">العنوان الخفيف</label>
 590:                 <input className="inp" value={f.headline || ''} onChange={e => set('headline', e.target.value)} />
 591:               </div>
 592:               <div className="space-y-1.5">
 593:                 <label className="text-[12px] font-semibold c-secondary">العنوان العريض</label>
 594:                 <input className="inp" value={f.headlineBold || ''} onChange={e => set('headlineBold', e.target.value)} />
 595:               </div>
 596:               <div className="space-y-1.5">
 597:                 <label className="text-[12px] font-semibold c-secondary">نص الزرار</label>
 598:                 <input className="inp" value={f.ctaLabel || ''} onChange={e => set('ctaLabel', e.target.value)} placeholder="SHOP NOW" />
 599:               </div>
 600:             </div>
 601:             <div className="space-y-1.5">
 602:               <label className="text-[12px] font-semibold c-secondary">الوصف</label>
 603:               <textarea className="inp" rows={2} value={f.description || ''} onChange={e => set('description', e.target.value)} />
 604:             </div>
 605:             {f.placement === 'middle' && (
 606:               <div className="space-y-1.5">
 607:                 <label className="text-[12px] font-semibold c-secondary">لون الخلفية</label>
 608:                 <div className="flex items-center gap-2">
 609:                   {['', '#dfe6ec', '#ede3de', '#e7e9e1', '#efe6dc'].map((c) => (
 610:                     <button
 611:                       key={c || 'auto'}
 612:                       type="button"
 613:                       title={c || 'تلقائي'}
 614:                       onClick={() => set('bgColor', c)}
 615:                       className="w-8 h-8 rounded-full flex items-center justify-center text-[10px]"
 616:                       style={{ background: c || 'var(--bg-card)', boxShadow: `0 0 0 2px ${(f.bgColor || '') === c ? 'var(--accent-orange)' : 'var(--border-subtle)'}` }}
 617:                     >
 618:                       {c ? '' : 'تلقائي'}
 619:                     </button>
 620:                   ))}
 621:                 </div>
 622:               </div>
 623:             )}
 624:             <div className="text-[11.5px] c-muted">لو سبتها فاضية، البانر هيظهر كصورة كاملة قابلة للضغط.</div>
 625:           </div>
 626: 
 627:           {/* Placement */}
 628:           <div>
 629:             <div className="text-[12.5px] font-semibold mb-1.5" style={{ color: 'var(--text-primary)' }}>
 630:               مكان العرض <span className="c-orange">*</span>
 631:             </div>
 632:             <div className="grid grid-cols-1 sm:grid-cols-3 gap-2.5">
 633:               {Object.entries(BN_PLACEMENTS).map(([k, p]) => (
 634:                 <button
 635:                   key={k}
 636:                   type="button"
 637:                   onClick={() => set('placement', k)}
 638:                   className={`rounded-2xl p-3 flex items-center gap-2.5 text-right border transition ${
 639:                     f.placement === k ? 'border-[var(--accent-orange)]' : 'border-transparent'
 640:                   }`}
 641:                   style={{ background: f.placement === k ? 'var(--accent-orange-light)' : 'var(--bg-subcard)' }}
 642:                 >
 643:                   <span className={`w-8 h-8 rounded-full flex items-center justify-center shrink-0 ${
 644:                     f.placement === k ? 'bg-[var(--accent-orange)] text-white' : 'v-icon-well'
 645:                   }`}>
 646:                     <Icon name={p.icon} className="w-4 h-4" />
 647:                   </span>
 648:                   <span className="text-[12.5px] font-semibold c-primary">{p.label}</span>
 649:                 </button>
 650:               ))}
 651:             </div>
 652:           </div>
 653: 
 654:           {/* Link Type */}
 655:           <div className="v-subcard p-4 space-y-3.5">
 656:             <div>
 657:               <div className="text-[12.5px] font-semibold mb-2" style={{ color: 'var(--text-primary)' }}>
 658:                 نوع الرابط
 659:               </div>
 660:               <div className="seg flex-wrap !bg-[var(--bg-card)]">
 661:                 {Object.entries(BN_LINK_TYPES).filter(([k]) => k !== 'brand' || f.linkType === 'brand').map(([k, l]) => (
 662:                   <button
 663:                     key={k}
 664:                     type="button"
 665:                     className={f.linkType === k ? 'on !bg-[var(--pill-active-bg)] !text-[var(--pill-active-text)]' : ''}
 666:                     onClick={() => {
 667:                       set('linkType', k);
 668:                       set('linkId', null);
 669:                       setErr(e => ({ ...e, linkId: null, url: null }));
 670:                     }}
 671:                   >
 672:                     <span className="inline-flex items-center gap-1.5">
 673:                       <Icon name={l.icon} className="w-3.5 h-3.5" /> {l.label}
 674:                     </span>
 675:                   </button>
 676:                 ))}
 677:               </div>
 678:             </div>
 679:             {f.linkType === 'none' ? (
 680:               <div className="text-[11.5px] c-muted">الصورة ستظهر بدون إمكانية الضغط عليها.</div>
 681:             ) : (
 682:               <div className="fade-in" key={f.linkType}>
 683:                 {targetField()}
 684:               </div>
 685:             )}
 686:           </div>
 687: 
 688:           {/* Schedule & Sort */}
 689:           <div className="grid grid-cols-1 sm:grid-cols-[120px_1fr_1fr] gap-4">
 690:             <div>
 691:               <label className="block text-[12.5px] font-semibold mb-1.5" style={{ color: 'var(--text-primary)' }}>
 692:                 ترتيب الظهور <span className="c-orange">*</span>
 693:               </label>
 694:               <input
 695:                 inputMode="numeric"
 696:                 className={`inp num text-center ${err.sort ? 'err' : ''}`}
 697:                 value={sortStr}
 698:                 onChange={e => setSortStr(e.target.value.replace(/[^\d]/g, ''))}
 699:                 placeholder="1"
 700:               />
 701:               {err.sort && <div className="text-[11px] mt-1 font-medium" style={{ color: 'var(--badge-red-text)' }}>{err.sort}</div>}
 702:             </div>
 703: 
 704:             <div>
 705:               <label className="block text-[12.5px] font-semibold mb-1.5" style={{ color: 'var(--text-primary)' }}>
 706:                 بداية العرض
 707:                 <span className="text-[11px] font-normal c-muted mr-1.5">{f.start ? '' : '· فارغ = فوراً'}</span>
 708:               </label>
 709:               <div className="flex items-center gap-1.5">
 710:                 <input
 711:                   type="datetime-local"
 712:                   className="inp num text-start text-[12px]"
 713:                   value={f.start || ''}
 714:                   onChange={e => { set('start', e.target.value); setErr(x => ({ ...x, end: null })); }}
 715:                 />
 716:                 {f.start && (
 717:                   <button type="button" className="icon-btn shrink-0" title="مسح" onClick={() => set('start', '')}>
 718:                     <Icon name="close" className="w-3.5 h-3.5" />
 719:                   </button>
 720:                 )}
 721:               </div>
 722:             </div>
 723: 
 724:             <div>
 725:               <label className="block text-[12.5px] font-semibold mb-1.5" style={{ color: 'var(--text-primary)' }}>
 726:                 نهاية العرض
 727:                 <span className="text-[11px] font-normal c-muted mr-1.5">{f.end ? '' : '· فارغ = دائم'}</span>
 728:               </label>
 729:               <div className="flex items-center gap-1.5">
 730:                 <input
 731:                   type="datetime-local"
 732:                   className={`inp num text-start text-[12px] ${err.end ? 'err' : ''}`}
 733:                   value={f.end || ''}
 734:                   onChange={e => set('end', e.target.value)}
 735:                 />
 736:                 {f.end && (
 737:                   <button type="button" className="icon-btn shrink-0" title="مسح" onClick={() => set('end', '')}>
 738:                     <Icon name="close" className="w-3.5 h-3.5" />
 739:                   </button>
 740:                 )}
 741:               </div>
 742:               {err.end && <div className="text-[11px] mt-1 font-medium" style={{ color: 'var(--badge-red-text)' }}>{err.end}</div>}
 743:             </div>
 744:           </div>
 745: 
 746:           {/* Active status */}
 747:           <div className="v-subcard p-3.5 flex items-center justify-between">
 748:             <div>
 749:               <div className="text-[13px] font-semibold c-primary flex items-center gap-2">
 750:                 التفعيل: {f.active ? 'مفعّل' : 'معطّل'}
 751:                 <span className={`badge ${BN_STATUS[bnStatus(f)].cls}`}>
 752:                   {BN_STATUS[bnStatus(f)].label}
 753:                 </span>
 754:               </div>
 755:               <div className="text-[11px] c-secondary mt-0.5">
 756:                 الحالة تُحسب تلقائياً من التفعيل وتواريخ البداية والنهاية.
 757:               </div>
 758:             </div>
 759:             <Toggle on={Boolean(f.active)} onChange={v => set('active', v)} />
 760:           </div>
 761:         </div>
 762: 
 763:         <div className="p-5 pt-3 flex items-center justify-start gap-2.5 flex-row-reverse v-border-t">
 764:           <button
 765:             type="button"
 766:             className="btn btn-dark min-w-[110px]"
 767:             onClick={submit}
 768:             disabled={busy || upl.state === 'uploading'}
 769:           >
 770:             {busy ? (
 771:               <>
 772:                 <span className="w-3.5 h-3.5 rounded-full border-2 border-current border-t-transparent animate-spin" />
 773:                 <span>جارٍ الحفظ…</span>
 774:               </>
 775:             ) : 'حفظ البانر'}
 776:           </button>
 777:           <button type="button" className="btn btn-soft" onClick={closeForm} disabled={busy}>
 778:             إلغاء
 779:           </button>
 780:           <span className="flex-1" />
 781:           {upl.state === 'uploading' && <span className="text-[11.5px] c-muted">انتظر اكتمال رفع الصورة</span>}
 782:         </div>
 783:       </div>
 784:     </div>
 785:   );
 786: }
 787: 
 788: // ============ Main Store Management Screen Component ============
 789: export function StoreManagementTab({ can }: { can?: (perm: string) => boolean }) {
 790:   const toggleInFlight = useRef(false);
 791:   const canEdit = can ? (can('store.manage') || can('*')) : true;
 792: 
 793:   const [tab, setTab] = useState<'slider' | 'middle' | 'popup'>(() => {
 794:     try {
 795:       const saved = localStorage.getItem('vortix-bn-tab');
 796:       if (saved === 'slider' || saved === 'middle' || saved === 'popup') return saved;
 797:     } catch {}
 798:     return 'slider';
 799:   });
 800: 
 801:   useEffect(() => {
 802:     try { localStorage.setItem('vortix-bn-tab', tab); } catch {}
 803:   }, [tab]);
 804: 
 805:   const [phase, setPhase] = useState<'loading' | 'ready' | 'error'>('loading');
 806:   const [items, setItems] = useState<BannerItem[]>([]);
 807: 
 808:   const loadBanners = React.useCallback(() => {
 809:     setPhase('loading');
 810:     adminApi.listBanners()
 811:       .then((list) => { setItems(list.map(fromApi)); setPhase('ready'); })
 812:       .catch(() => setPhase('error'));
 813:   }, []);
 814: 
 815:   useEffect(() => { loadBanners(); }, [loadBanners]);
 816: 
 817:   const [q, setQ] = useState('');
 818:   const [sf, setSf] = useState<string>('all');
 819:   const [form, setForm] = useState<{ open: boolean; initial: BannerItem | null }>({ open: false, initial: null });
 820:   const [del, setDel] = useState<BannerItem | null>(null);
 821:   const [delBusy, setDelBusy] = useState(false);
 822:   const [busyToggle, setBusyToggle] = useState<string | null>(null);
 823: 
 824:   const inTab = items.filter(b => b.placement === tab);
 825:   const rows = inTab
 826:     .filter(b => (!q || b.title.includes(q)) && (sf === 'all' || bnStatus(b) === sf))
 827:     .sort((a, b) => a.sort - b.sort);
 828: 
 829:   const tabCount = (k: string) => items.filter(b => b.placement === k).length;
 830:   const stCount = (k: string) => inTab.filter(b => bnStatus(b) === k).length;
 831: 
 832:   const save = async (f: BannerItem, onProgress: (p: number) => void): Promise<Record<string, string> | null> => {
 833:     const isNew = !f.id || !/^\d+$/.test(f.id);
 834:     try {
 835:       const saved = isNew
 836:         ? await adminApi.createBanner(toFormData(f), onProgress)
 837:         : await adminApi.updateBanner(Number(f.id), toFormData(f), onProgress);
 838:       const mapped = fromApi(saved);
 839:       setItems(xs => isNew ? [...xs, mapped] : xs.map(x => x.id === mapped.id ? mapped : x));
 840:       setForm({ open: false, initial: null });
 841:       if (mapped.placement !== tab) setTab(mapped.placement);
 842:       toast(isNew ? 'تمت إضافة البانر بنجاح' : 'تم حفظ تعديلات البانر');
 843:       return null;
 844:     } catch (e) {
 845:       const err = normalizeError(e);
 846:       if (err.status === 422) {
 847:         const out: Record<string, string> = {};
 848:         let generalError: string | undefined;
 849:         Object.entries(err.fields).forEach(([k, msgs]) => {
 850:           if (k === 'title') out.title = msgs[0];
 851:           else if (k === 'image') out.image = msgs[0];
 852:           else if (k === 'link_value') out[f.linkType === 'external' ? 'url' : 'linkId'] = msgs[0];
 853:           else if (k === 'sort_order') out.sort = msgs[0];
 854:           else if (k === 'ends_at') out.end = msgs[0];
 855:           else generalError ??= msgs[0];
 856:         });
 857:         if (generalError) toast(generalError, 'err');
 858:         return out;
 859:       }
 860:       toast(err.message, 'err');
 861:       return {};
 862:     }
 863:   };
 864: 
 865:   const toggle = (b: BannerItem) => {
 866:     if (toggleInFlight.current) return;
 867:     toggleInFlight.current = true;
 868:     const prev = b.active;
 869:     setItems(xs => xs.map(x => x.id === b.id ? { ...x, active: !x.active, status: undefined } : x));
 870:     setBusyToggle(b.id);
 871:     adminApi.toggleBanner(Number(b.id), !prev)
 872:       .then((saved) => {
 873:         setItems(xs => xs.map(x => x.id === b.id ? fromApi(saved) : x));
 874:         toast(prev ? 'تم تعطيل البانر' : 'تم تفعيل البانر');
 875:       })
 876:       .catch((e) => {
 877:         setItems(xs => xs.map(x => x.id === b.id ? { ...x, active: prev, status: b.status } : x));
 878:         toast(normalizeError(e).message, 'err');
 879:       })
 880:       .finally(() => { toggleInFlight.current = false; setBusyToggle(null); });
 881:   };
 882: 
 883:   const doDelete = () => {
 884:     if (!del) return;
 885:     setDelBusy(true);
 886:     adminApi.deleteBanner(Number(del.id))
 887:       .then(() => {
 888:         setItems(xs => xs.filter(x => x.id !== del.id));
 889:         setDel(null);
 890:         toast('تم حذف البانر بنجاح');
 891:       })
 892:       .catch((e) => toast(normalizeError(e).message, 'err'))
 893:       .finally(() => setDelBusy(false));
 894:   };
 895: 
 896:   const openNew = () => setForm({ open: true, initial: null });
 897: 
 898:   const P = BN_PLACEMENTS[tab] || BN_PLACEMENTS.slider;
 899:   const liveInTab = inTab.filter(b => bnStatus(b) === 'live').sort((a, b) => a.sort - b.sort);
 900: 
 901:   return (
 902:     <section className="space-y-6 fade-in" data-screen-label="Store Management">
 903:       {/* Sub-header info and Add button */}
 904:       <div className="flex flex-wrap items-center justify-between gap-4 p-5 rounded-[22px] v-card">
 905:         <div>
 906:           <h2 className="font-display text-[20px] font-semibold c-primary flex items-center gap-2.5">
 907:             <span className="w-8 h-8 rounded-xl flex items-center justify-center text-white v-accent-btn">
