 10: export function SophieHero({ slides, isLoading = false }: { slides: HeroSlide[]; isLoading?: boolean }) {
 11:   const { branding } = useBranding();
 12:   const [index, setIndex] = useState(0);
 13:   const [failed, setFailed] = useState<Set<string>>(() => new Set());
 14:   const [paused, setPaused] = useState(false);
 15:   const [focused, setFocused] = useState(false);
 16:   const [fallbackFailed, setFallbackFailed] = useState(false);
 17:   const touchStart = useRef<number | null>(null);
 18:   const list = useMemo(() => {
 19:     const healthy = slides.filter((s) => s.kind !== 'banner' || !failed.has(`${s.id}:${s.image}`));
 20:     return healthy.length ? healthy : [FALLBACK_SLIDE];
 21:   }, [slides, failed]);
 22:   const activeIndex = index % list.length;
 23:   const slide = list[activeIndex];
 24:   const advance = (direction: number) => setIndex((current) => (current + direction + list.length) % list.length);
 25: 
 26:   useEffect(() => {
 27:     if (isLoading || paused || focused || list.length < 2 || window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;
 28:     const timer = setInterval(() => setIndex((current) => (current + 1) % list.length), 6000);
 29:     return () => clearInterval(timer);
 30:   }, [isLoading, paused, focused, list.length]);
 31: 
 32:   useEffect(() => {
 33:     if (isLoading) return;
 34:     const next = list[(activeIndex + 1) % list.length];
 35:     if (next.kind === 'banner') { const image = new Image(); image.src = next.image; }
 36:   }, [activeIndex, list, isLoading]);
 37: 
 38:   const fallback = slide.kind === 'fallback';
 39:   const kicker = fallback ? `${branding.name} ${slide.subtitle}` : slide.kicker;
 40:   const headline = fallback ? slide.lightTitle : slide.headline;
 41:   const bold = fallback ? slide.boldTitle : slide.headlineBold;
 42:   const description = fallback ? slide.desc : slide.description;
 43:   const href = fallback ? slide.ctaHref : slide.href;
 44:   const label = fallback ? slide.ctaText : slide.ctaLabel || 'SHOP NOW';
 45:   const hasText = Boolean(kicker || headline || bold || description);
 46:   const external = !fallback && slide.isExternal ? { target: '_blank', rel: 'noopener noreferrer' } : {};
 47: 
 48:   return (
 49:     <div className="hero-wrapper relative overflow-hidden bg-[#dfe5e9]" id="top"
 50:       onMouseEnter={() => setPaused(true)} onMouseLeave={() => setPaused(false)}
 51:       onFocusCapture={() => setFocused(true)} onBlurCapture={(event) => { if (!event.currentTarget.contains(event.relatedTarget)) setFocused(false); }}
 52:       onTouchStart={(event) => { touchStart.current = event.touches.length === 1 ? event.touches[0].clientX : null; }}
 53:       onTouchCancel={() => { touchStart.current = null; }}
 54:       onTouchEnd={(event) => {
 55:         if (touchStart.current !== null && !isLoading && list.length > 1) {
 56:           const delta = touchStart.current - event.changedTouches[0].clientX;
 57:           if (Math.abs(delta) > 50) advance(delta > 0 ? 1 : -1);
 58:         }
 59:         touchStart.current = null;
 60:       }}>
 61:       {!isLoading && fallback && !fallbackFailed && (
 62:         <div className="hero-bg-backdrop" aria-hidden="true">
 63:           <div className="hero-bg-backdrop-img"><img src={slide.imgUrl} className={`${slide.tintClass} w-full h-full object-cover object-center`} alt="" onError={() => setFallbackFailed(true)} /></div>
 64:           <div className="hero-bg-backdrop-overlay" />
 65:         </div>
 66:       )}
 67:       {!isLoading && !fallback && (
 68:         <div className="absolute inset-0" aria-hidden="true">
 69:           <img key={`${slide.id}:${slide.image}`} src={slide.image} alt="" className="hero-banner-img" onError={() => setFailed((current) => new Set(current).add(`${slide.id}:${slide.image}`))} />
 70:           {hasText && <div className="hero-banner-overlay" />}
 71:         </div>
 72:       )}
 73:       <div className="max-w-[1140px] mx-auto px-5 relative z-10">
 74:         <SophieHeader />
 75:         <section className="sophie-hero-content flex flex-col lg:flex-row items-center justify-between min-h-[450px] pt-2 pb-14 relative" aria-label="Featured collection" aria-busy={isLoading}>
 76:           {isLoading ? (
 77:             <>
 78:               <div className="max-w-[430px] w-full space-y-4 mt-6 lg:mt-0" aria-hidden="true">
 79:                 <div className="sophie-skeleton h-3 w-32" /><div className="sophie-skeleton h-12 w-72 max-w-full" /><div className="sophie-skeleton h-12 w-60" />
 80:                 <div className="sophie-skeleton h-3 w-full" /><div className="sophie-skeleton h-3 w-3/4" /><div className="sophie-skeleton h-10 w-36" />
 81:               </div>
 82:               <div className="sophie-skeleton w-[290px] sm:w-[350px] lg:w-[390px] h-[330px] sm:h-[370px] lg:h-[410px] mt-8 lg:mt-0 lg:mr-10 shrink-0" aria-hidden="true" />
 83:             </>
 84:           ) : (
 85:             <>
 86:               {hasText && (
 87:                 <div className="max-w-[430px] z-10 text-center lg:text-left mt-6 lg:mt-0 break-words">
 88:                   {kicker && <p dir="auto" className="font-['Oswald'] text-[13px] font-medium tracking-[0.6px] uppercase text-[#111] mb-2.5">{kicker}</p>}
 89:                   {(headline || bold) && <h1 dir="auto" className="font-['Oswald'] uppercase leading-[1.02] mb-4.5">
 90:                     {headline && <span className="block text-[44px] sm:text-[54px] font-light tracking-[1px] text-[#111]">{headline}</span>}
 91:                     {bold && <span className="block text-[48px] sm:text-[58px] font-bold tracking-[1px] text-[#111]">{bold}</span>}
 92:                   </h1>}
 93:                   {description && <p dir="auto" className="text-[13.5px] leading-[1.6] text-[#333] mb-7 font-['Poppins']">{description}</p>}
 94:                   {href && <a href={href} {...external} className="inline-block bg-black text-white font-['Oswald'] text-[12px] font-medium tracking-[0.8px] uppercase px-9 py-3 hover:bg-[#2c2c2c] transition-colors">{label}</a>}
 95:                 </div>
 96:               )}
 97:               {!hasText && href && !fallback && <a href={href} {...external} aria-label={slide.alt} className="absolute inset-0 z-[5]" />}
 98:               {fallback && <div className="flex-1 flex justify-center lg:justify-end items-center lg:pr-10 relative mt-8 lg:mt-0">
 99:                 <div className="hero-foreground-img w-[290px] sm:w-[350px] lg:w-[390px] h-[330px] sm:h-[370px] lg:h-[410px]">
100:                   {fallbackFailed ? <SophieBagPlaceholder /> : <img src={slide.imgUrl} className={`${slide.tintClass} w-full h-full object-contain block`} alt={`${slide.lightTitle} ${slide.boldTitle}`} onError={() => setFallbackFailed(true)} />}
101:                 </div>
102:               </div>}
103:             </>
104:           )}
105:           {!isLoading && list.length > 1 && <div className="absolute bottom-5 left-1/2 -translate-x-1/2 flex gap-1.5 z-20">
106:             {list.map((item, position) => <button key={item.id} onClick={() => setIndex(position)} aria-label={`Go to slide ${position + 1}`} aria-current={activeIndex === position ? 'true' : undefined} className="py-3 px-1">
107:               <span className={`block h-[2px] transition-all duration-300 ${activeIndex === position ? 'w-7 bg-[#111111]' : 'w-5 bg-white/80 hover:bg-white shadow-sm'}`} />
108:             </button>)}
109:           </div>}
110:         </section>
111:       </div>
112:     </div>
113:   );
114: } 1: 'use client';
