 9: export interface SophieProduct {
10:   id: number;
11:   variantId?: number;
12:   slug?: string;
13:   name: string;
14:   price: number;
15:   oldPrice?: number;
16:   badge?: string;
17:   imgUrl: string | null;
18:   badgeTone?: 'default' | 'sale' | 'muted';
19:   href?: string;
20:   inStock?: boolean;
21:   tintClass?: string;
22:   category?: string;
23: }
