25: export function SophieProductCard({ product }: { product: SophieProduct }) {
26:   const addItem = useCartStore((s) => s.addItem);
27:   const [added, setAdded] = useState(false);
28:   const [adding, setAdding] = useState(false);
29:   const busy = useCartStore((s) => s.busy);
30:   const cartError = useCartStore((s) => s.error);
31:   const [addFailed, setAddFailed] = useState(false);
32:   const [failedImage, setFailedImage] = useState<string | null>(null);
33:   const image = product.imgUrl && failedImage !== product.imgUrl ? (
34:     <img src={product.imgUrl} alt={product.name} onError={() => setFailedImage(product.imgUrl)}
35:       className={`${product.tintClass || ''} max-w-[175px] max-h-[200px] object-contain transition-transform duration-300 group-hover:scale-105 ${product.inStock === false ? 'opacity-60' : ''}`} loading="lazy" />
36:   ) : <SophieBagPlaceholder />;
37: 
38:   const handleAddToCart = async () => {
39:     if (!product.variantId || busy) return;
40:     setAdding(true);
41:     setAddFailed(false);
42:     const saved = await addItem(product.variantId);
43:     setAdding(false);
44:     setAdded(saved);
45:     setAddFailed(!saved);
46:     if (saved) setTimeout(() => setAdded(false), 1600);
47:   };
48: 
49:   return (
50:     <div className="product-card text-center group flex flex-col">
51:       {/* Image Box */}
52:       <div className="bg-[#f3f4f6] relative h-[260px] flex items-center justify-center p-6 mb-3.5 overflow-hidden transition-all duration-300 group-hover:bg-[#ebeef2]">
53:         {/* Badge */}
54:         {product.badge && (
55:           <span className={`absolute top-0 left-0 ${product.badgeTone === 'sale' ? 'bg-[#111]' : product.badgeTone === 'muted' ? 'bg-[#9ca3af]' : 'bg-[#4f7d86]'} text-white font-['Oswald'] text-[10px] font-medium uppercase px-2.5 py-1 tracking-[0.5px] z-10`}>
56:             {product.badge}
57:           </span>
58:         )}
59: 
60:         {/* Product Image */}
61:         {product.href ? <Link href={product.href} aria-label={product.name} className="flex items-center justify-center w-full h-full">{image}</Link> : image}
62: 
63:         {/* Quick Add Overlay on Hover */}
64:         {product.inStock !== false && product.variantId && <div className="absolute inset-x-0 bottom-0 p-3 bg-gradient-to-t from-black/20 to-transparent opacity-100 lg:opacity-0 lg:group-hover:opacity-100 focus-within:opacity-100 transition-opacity flex items-center justify-center">
65:           <button
66:             onClick={handleAddToCart}
67:             disabled={busy}
68:             className={`font-['Oswald'] text-[11px] uppercase tracking-wider py-1.5 px-4 rounded-xs shadow-sm transition-all duration-200 ${
69:               added ? 'bg-emerald-600 text-white' : 'bg-black text-white hover:bg-neutral-800'
70:             }`}
71:           >
72:             {adding ? 'Adding…' : added ? '✓ Added' : '+ Add to Cart'}
73:           </button>
74:         </div>}
75:       </div>
76: 
77:       {/* Product Name */}
78:       <h3 dir="auto" className="font-['Oswald'] text-[13px] font-medium text-[#222] mb-1 tracking-[0.2px] hover:text-[#4f7d88] transition-colors line-clamp-1">
79:         {product.href ? <Link href={product.href}>{product.name}</Link> : product.name}
80:       </h3>
81: 
82:       {/* Product Price */}
83:       <p className="font-['Oswald'] text-[14px] font-semibold text-[#111]">
84:         {product.oldPrice && (
85:           <span className="text-[#b0b0b0] line-through font-normal mr-1 text-[13px]">
86:             {formatStorePrice(product.oldPrice)}
87:           </span>
88:         )}
89:         <span>{formatStorePrice(product.price)}</span>
90:       </p>
91:       {addFailed && cartError && <p role="alert" className="text-xs text-red-700 mt-2">{cartError}</p>}
92:     </div>
93:   );
94: } 1: 'use client';
