14:       {failed ? <p dir="auto" className="w-full px-6 text-center font-['Poppins'] font-bold text-black">{banner.title}</p> : <>
15:         <div className={hasText ? 'w-[48%] h-full shrink-0' : 'absolute inset-0'}>
16:           <img src={banner.image} alt={banner.title} className="w-full h-full object-cover" loading="lazy" onError={() => setFailed(true)} />
17:         </div>
18:         {hasText && <div className="flex-1 min-w-0 px-4 sm:px-5 break-words">
19:           {banner.kicker && <p dir="auto" className="font-['Oswald'] text-[13px] uppercase text-[#222] tracking-[0.5px] mb-0.5">{banner.kicker}</p>}
20:           {(banner.headline_bold || banner.headline) && <h3 dir="auto" className="font-['Poppins'] text-[24px] sm:text-[27px] font-bold text-black leading-[1.15] mb-2.5">{banner.headline_bold || banner.headline}</h3>}
21:           {banner.href && <a href={banner.href} {...external} className="text-[12px] text-[#222] inline-flex items-center gap-1.5 hover:text-[#4f7d88] transition-colors">
22:             <span>{banner.cta_label || 'View collection'}</span>
23:             <svg className="w-2.5 h-2.5 shrink-0" fill="none" viewBox="0 0 24 24" stroke="currentColor" aria-hidden="true"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M9 5l7 7-7 7" /></svg>
24:           </a>}
25:         </div>}
26:       </>}
27:       {(!hasText || failed) && banner.href && <a href={banner.href} {...external} aria-label={banner.title} className="absolute inset-0" />}
