 26:   background-color: #dfe5e9;
 27:   position: relative;
 28:   overflow: hidden;
 29: }
 30: 
 31: .hero-bg-backdrop {
 32:   position: absolute;
 33:   inset: 0;
 34:   pointer-events: none;
 35:   overflow: hidden;
 36:   z-index: 1;
 37: }
 38: 
 39: .hero-bg-backdrop-img {
 40:   position: absolute;
 41:   top: -8%;
 42:   right: 0;
 43:   width: 60%;
 44:   height: 116%;
 45:   filter: blur(14px) brightness(0.96) saturate(1.25);
 46:   opacity: 0.75;
 47:   transform: scale(1.08);
 48:   transition: transform 0.6s ease;
 49: }
 50: 
 51: .hero-bg-backdrop-overlay {
 52:   position: absolute;
 53:   inset: 0;
 54:   background: linear-gradient(
 55:     90deg,
 56:     #dfe5e9 0%,
 57:     rgba(223, 229, 233, 0.95) 38%,
 58:     rgba(223, 229, 233, 0.6) 65%,
 59:     rgba(223, 229, 233, 0.2) 100%
 60:   );
 61: }
 62: 
 63: .hero-foreground-img {
 64:   position: relative;
 65:   display: inline-flex;
 66:   align-items: center;
 67:   justify-content: center;
 68:   filter: drop-shadow(0 20px 26px rgba(0, 0, 0, 0.2));
 69:   transition: transform 0.4s ease;
 70: }
 71: 
 72: .hero-foreground-img:hover {
 73:   transform: translateY(-8px) scale(1.02);
 74: }
 75: 
 76: /* Footer Skyline */
 77: .footer-skyline {
 78:   display: block;
 79:   width: 100%;
 80:   line-height: 0;
 81:   overflow: hidden;
 82:   background-color: #ffffff;
 83: }
 84: 
 85: .footer-skyline svg {
 86:   display: block;
 87:   width: 100%;
 88:   height: 78px;
 89: }
 90: 
 91: @media (max-width: 992px) {
 92:   .hero-bg-backdrop-img {
 93:     width: 100%;
 94:     height: 100%;
 95:     top: 0;
 96:     opacity: 0.55;
 97:   }
 98:   .hero-bg-backdrop-overlay {
 99:     background: linear-gradient(
100:       180deg,
101:       #dfe5e9 0%,
102:       rgba(223, 229, 233, 0.94) 45%,
103:       rgba(223, 229, 233, 0.5) 100%
104:     );
105:   }
106: }
107: 
108: @media (max-width: 576px) {
109:   .footer-skyline svg {
110:     height: 46px;
111:   }
112: }
