114: /* Reserve the same space for loading, banner and fallback modes. */
115: .hero-wrapper .sophie-hero-content { min-height: 740px; }
116: @media (min-width: 640px) { .hero-wrapper .sophie-hero-content { min-height: 780px; } }
117: @media (min-width: 1024px) { .hero-wrapper .sophie-hero-content { min-height: 475px; } }
118: .sophie-skeleton { background: linear-gradient(90deg, #eceef1 0%, #f6f7f8 50%, #eceef1 100%); background-size: 200% 100%; animation: sophieShimmer 1.4s ease-in-out infinite; }
119: @keyframes sophieShimmer { from { background-position: 200% 0; } to { background-position: -200% 0; } }
120: .hero-banner-img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; object-position: right center; animation: heroFade .6s ease; }
121: .hero-banner-overlay { position: absolute; inset: 0; background: linear-gradient(90deg, #dfe5e9 0%, rgba(223,229,233,.88) 32%, rgba(223,229,233,0) 62%); }
122: @media (max-width: 1023px) { .hero-banner-overlay { background: linear-gradient(0deg, #dfe5e9 0%, rgba(223,229,233,.9) 45%, rgba(223,229,233,.15) 100%); } }
123: @keyframes heroFade { from { opacity: 0; } to { opacity: 1; } }
124: .sophie-pop-in { animation: sophiePop .35s cubic-bezier(.2,.8,.2,1); }
125: @keyframes sophiePop { from { opacity: 0; transform: translateY(12px) scale(.97); } to { opacity: 1; transform: none; } }
126: .hero-wrapper :focus-visible, .products-section :focus-visible, .sophie-pop-in :focus-visible { outline: 2px solid #4f7d88; outline-offset: 4px; }
127: @media (prefers-reduced-motion: reduce) { .sophie-skeleton, .hero-banner-img, .sophie-pop-in { animation: none; } }  1: // ============ App shell (Vortix header + floating pill sidebar, RTL) ============
