  7:   { id: 'moves',     label: 'الحركات',         icon: 'history',   match: ['moves'] },
  8:   { id: 'transfers', label: 'التحويلات',       icon: 'swap',      match: ['transfers', 'transfer', 'transfer-edit'] },
  9:   { id: 'counts',    label: 'الجرد',           icon: 'clipboard', match: ['counts', 'count'] },
