 18:         <div className="w-9 h-9 rounded-full flex items-center justify-center shadow-inner" style={{ background: 'radial-gradient(circle at 30% 25%, #ff8a65 0%, #e0491f 75%)' }}>
 19:           <svg className="w-4 h-4 text-white" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"><path d="M5 5l7 14 7-14" /></svg>
 20:         </div>
 21:         <span className="font-display font-bold text-[15px] tracking-tight c-primary" style={{ fontFamily: 'Plus Jakarta Sans' }}>Vortix</span>
