 90: function InvApp() {
 91:   const [t, setTweak] = useTweaks(window.INV_TWEAK_DEFAULTS);
 92:   const [nav, setNav] = useState(() => {
 93:     try { return JSON.parse(localStorage.getItem('vortix-inv-route')) || { route: 'stock', params: {} }; } catch { return { route: 'stock', params: {} }; }
 94:   });
 95:   const [db, setDb] = useState(() => ({ branches: INV_BRANCHES, locations: INV_LOCATIONS, transfers: INV_TRANSFERS, counts: INV_COUNTS, production: INV_PRODUCTION }));
 96:   const [toastMsg, setToastMsg] = useState(null);
 97:   const [reloadKey, setReloadKey] = useState(0);
 98:   const tRef = useRef();
 99: 
100:   const go = (route, params = {}) => { setNav({ route, params }); window.scrollTo({ top: 0, behavior: 'smooth' }); };
101:   useEffect(() => { localStorage.setItem('vortix-inv-route', JSON.stringify(nav)); }, [nav]);
102:   const toast = text => { setToastMsg({ text }); clearTimeout(tRef.current); tRef.current = setTimeout(() => setToastMsg(null), 2400); };
103: 
104:   const ctx = { db, setDb, toast, role: t.role, demoState: t.demoState, reloadKey, reload: () => { setReloadKey(k => k + 1); if (t.demoState === 'error') setTweak('demoState', 'live'); } };
105: 
106:   const screens = {
107:     branches: BranchesScreen, locations: LocationsScreen, stock: StockScreen, adjust: AdjustScreen, moves: MovesScreen,
108:     transfers: TransfersScreen, transfer: TransferDetail, 'transfer-edit': TransferEdit, counts: CountsScreen, count: CountDetail, production: ProductionScreen, banners: BannersScreen,
109:   };
110:   const Screen = screens[nav.route] || StockScreen;
111:   const screenKey = nav.route + JSON.stringify(nav.params);
112:   const label = (INV_NAV.find(n => n.match.includes(nav.route)) || {}).label;
113: 
114:   return (
115:     <InvCtx.Provider value={ctx}>
116:       <div id="app-viewport" className={t.theme === 'dark' ? 'theme-dark' : 'theme-light'}>
117:         <div className="max-w-[1440px] mx-auto px-4 sm:px-7 pt-5 pb-10">
118:           <InvHeader route={nav.route} go={go} theme={t.theme} role={t.role} />
119:           <div className="flex gap-6 items-start">
120:             <InvSidebar route={nav.route} go={go} theme={t.theme} setTheme={v => setTweak('theme', v)} />
121:             <main className="flex-1 min-w-0" data-screen-label={label}>
122:               <Screen key={screenKey} go={go} params={nav.params} />
123:             </main>
124:           </div>
125:         </div>
126:         <Toast toast={toastMsg} />
127:       </div>
128: 
129:       <div dir="ltr">
130:       <TweaksPanel title="Tweaks">
131:         <TweakSection label="الصلاحية">
132:           <TweakRadio label="الدور" value={t.role} onChange={v => setTweak('role', v)}
133:             options={[{ value: 'admin', label: 'مدير' }, { value: 'storekeeper', label: 'أمين مخزن' }, { value: 'viewer', label: 'عرض فقط' }]} />
134:         </TweakSection>
135:         <TweakSection label="حالة البيانات">
136:           <TweakSelect label="محاكاة الاستجابة" value={t.demoState} onChange={v => setTweak('demoState', v)}
137:             options={[{ value: 'live', label: 'بيانات فعلية' }, { value: 'loading', label: 'تحميل' }, { value: 'empty', label: 'فارغ' }, { value: 'error', label: 'خطأ من السيرفر' }]} />
138:         </TweakSection>
139:         <TweakSection label="المظهر">
140:           <TweakRadio label="الوضع" value={t.theme} onChange={v => setTweak('theme', v)} options={[{ value: 'light', label: 'فاتح' }, { value: 'dark', label: 'داكن' }]} />
141:         </TweakSection>
142:       </TweaksPanel>
143:       </div>
144:     </InvCtx.Provider>
145:   );
146: }
