 42: const BN_NOW = new Date('2026-10-25T12:00');
 43: function bnStatus(b) {
 44:   if (!b.active) return 'disabled';
 45:   if (b.start && new Date(b.start) > BN_NOW) return 'scheduled';
 46:   if (b.end && new Date(b.end) < BN_NOW) return 'expired';
 47:   return 'live';
 48: }
 49: const BN_STATUS = {
 50:   live:      { label: 'ساري',  cls: 'b-green' },
 51:   scheduled: { label: 'مجدول', cls: 'b-blue'  },
 52:   expired:   { label: 'منتهي', cls: 'b-amber' },
 53:   disabled:  { label: 'معطّل', cls: 'b-gray'  },
 54: };
 55: const bnDate = s => {
 56:   if (!s) return null;
 57:   const d = new Date(s);
 58:   return { d: d.toLocaleDateString('en-GB', { day: '2-digit', month: '2-digit', year: 'numeric' }), t: d.toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit' }) };
 59: };
 60: function bnTarget(b) {
 61:   switch (b.linkType) {
 62:     case 'product':  return INV_PRODUCTS.find(p => p.id === b.linkId)?.name;
 63:     case 'category': return BN_CATEGORIES.find(c => c.id === b.linkId)?.name;
 64:     case 'brand':    return BN_BRANDS.find(x => x.id === b.linkId)?.name;
 65:     case 'external': return b.url;
 66:     default: return null;
 67:   }
 68: }
