 75:     <div className="w-full h-full relative overflow-hidden flex flex-col justify-center" style={{ background: a.bg, color: a.fg, padding: big ? '6% 7%' : '0 9%' }}>
 76:       <div className="absolute -left-[12%] -bottom-[40%] w-[55%] aspect-square rounded-full" style={{ background: 'rgba(255,255,255,.12)' }} />
 77:       <div className="relative font-semibold opacity-80" style={{ fontSize: big ? 13 : 8 }}>{a.kicker}</div>
 78:       <div className="relative font-display font-bold leading-tight" style={{ fontSize: big ? 26 : 12 }}>{a.line}</div>
 79:     </div>
 80:   );
