 89:   useEffect(() => localStorage.setItem('vortix-bn-tab', tab), [tab]);
 90:   const phase = useLoad('bn' + tab);
 91:   const [items, setItems] = useState(BN_SEED);
 92:   const [q, setQ] = useState('');
 93:   const [sf, setSf] = useState('all');
 94:   const [form, setForm] = useState({ open: false, initial: null });
 95:   const [del, setDel] = useState(null);
 96:   const [delBusy, setDelBusy] = useState(false);
 97:   const [busyToggle, setBusyToggle] = useState(null);
 98: 
 99:   const inTab = items.filter(b => b.placement === tab);
100:   const rows = inTab.filter(b => (!q || b.title.includes(q)) && (sf === 'all' || bnStatus(b) === sf)).sort((a, b) => a.sort - b.sort);
101:   const tabCount = k => items.filter(b => b.placement === k).length;
102:   const stCount = k => inTab.filter(b => bnStatus(b) === k).length;
103: 
104:   const save = f => {
105:     const isNew = !f.id;
106:     setItems(xs => isNew ? [...xs, { ...f, id: 'bn' + Date.now() }] : xs.map(x => x.id === f.id ? f : x));
107:     setForm({ open: false, initial: null });
