109:     toast(isNew ? 'تمت إضافة البانر بنجاح' : 'تم حفظ التعديلات');
110:   };
111:   const toggle = b => {
112:     setBusyToggle(b.id);
113:     setTimeout(() => { setItems(xs => xs.map(x => x.id === b.id ? { ...x, active: !x.active } : x)); setBusyToggle(null); toast(b.active ? 'تم تعطيل البانر' : 'تم تفعيل البانر'); }, 450);
114:   };
115:   const doDelete = () => {
116:     setDelBusy(true);
117:     setTimeout(() => { setItems(xs => xs.filter(x => x.id !== del.id)); setDelBusy(false); setDel(null); toast('تم حذف البانر'); }, 700);
118:   };
119:   const openNew = () => setForm({ open: true, initial: null });
120: 
121:   const P = BN_PLACEMENTS[tab];
122:   const liveInTab = inTab.filter(b => bnStatus(b) === 'live').sort((a, b) => a.sort - b.sort);
123: 
124:   return (
125:     <section className="space-y-5">
126:       <PageHead title="إدارة المتجر" sub="إدارة الصور والإعلانات الظاهرة في المتجر ومواعيد عرضها."
127:         actions={canEdit
128:           ? <button className="btn btn-dark" onClick={openNew}><Icon n="plus" s={14} w={2.2} /> إضافة بانر</button>
129:           : <span className="inline-flex items-center gap-1.5 text-[12px] c-muted px-3.5 py-2 rounded-full v-pill-surface"><Icon n="eye" s={13} /> صلاحية مشاهدة فقط</span>} />
130: 
131:       {/* Placement tabs */}
132:       <div className="grid grid-cols-1 sm:grid-cols-3 gap-3.5 stagger-item stagger-2">
133:         {Object.entries(BN_PLACEMENTS).map(([k, p]) => {
134:           const on = tab === k;
135:           return (
136:             <button key={k} onClick={() => { setTab(k); setSf('all'); setQ(''); }}
137:               className={`text-right rounded-[20px] p-4 flex items-center gap-3.5 transition ${on ? 'shadow-xs' : 'hover:opacity-90'}`}
138:               style={{ background: on ? 'var(--pill-active-bg)' : 'var(--bg-card)', color: on ? 'var(--pill-active-text)' : 'var(--text-primary)', border: '1px solid var(--border-subtle)' }}>
139:               <span className="w-10 h-10 rounded-full flex items-center justify-center shrink-0" style={{ background: on ? 'var(--accent-orange)' : 'var(--icon-well-bg)', color: on ? '#fff' : 'var(--text-secondary)' }}><Icon n={p.icon} s={17} /></span>
140:               <span className="flex-1 min-w-0">
141:                 <span className="block text-[14px] font-semibold">{p.label}</span>
142:                 <span className="block text-[11px] truncate" style={{ opacity: .65 }}>{p.hint}</span>
143:               </span>
144:               <span className="num font-display text-[22px] font-bold">{phase === 'ready' || !on ? tabCount(k) : '—'}</span>
145:             </button>
146:           );
147:         })}
148:       </div>
149: 
150:       <div className="grid grid-cols-1 xl:grid-cols-12 gap-5 items-start">
151:         <Card className="xl:col-span-8" stagger={3}>
152:           <CardHead title={P.label} meta={phase === 'ready' ? `${rows.length} من ${inTab.length}` : null}
153:             right={<>
154:               <div className="seg">
155:                 <button className={sf === 'all' ? 'on' : ''} onClick={() => setSf('all')}>الكل</button>
156:                 {Object.entries(BN_STATUS).map(([k, s]) => <button key={k} className={sf === k ? 'on' : ''} onClick={() => setSf(k)}>{s.label}{phase === 'ready' && <span className="num c-muted mr-1">{stCount(k)}</span>}</button>)}
157:               </div>
158:               <SearchPill value={q} onChange={setQ} placeholder="بحث بالعنوان" w="w-32" />
159:             </>} />
160: 
161:           {!canEdit && phase === 'ready' && <div className="mb-3"><InlineAlert kind="blue" icon="eye" title="وضع المشاهدة">يمكنك استعراض البانرات فقط. الإضافة والتعديل والحذف والتفعيل تتطلب صلاحية إدارة المتجر.</InlineAlert></div>}
162: 
163:           {phase === 'loading' && <BannerSkeleton />}
164:           {phase === 'error' && <ErrorState msg="تعذّر تحميل البانرات من الخادم." code="GET /admin/banners · 500" />}
165:           {(phase === 'empty' || (phase === 'ready' && inTab.length === 0)) && (
166:             <EmptyState icon={P.icon} title={`لا توجد بانرات في «${P.label}»`} sub={P.hint + '. أضف أول صورة لتظهر في المتجر.'}
167:               action={canEdit && <button className="btn btn-dark btn-sm" onClick={openNew}><Icon n="plus" s={13} /> إضافة أول بانر</button>} />
168:           )}
169:           {phase === 'ready' && inTab.length > 0 && rows.length === 0 && <EmptyState icon="filter" title="لا توجد بانرات تطابق البحث أو الفلتر" sub="غيّر كلمة البحث أو اختر حالة أخرى." />}
170: 
171:           {phase === 'ready' && rows.length > 0 && (
172:             <div className="space-y-2.5">
173:               {rows.map(b => {
174:                 const st = bnStatus(b); const tgt = bnTarget(b); const L = BN_LINK_TYPES[b.linkType];
175:                 const s = bnDate(b.start), e = bnDate(b.end);
176:                 return (
177:                   <div key={b.id} className="v-subcard p-3 flex items-center gap-4 fade-in" style={{ opacity: st === 'disabled' ? .72 : 1 }}>
178:                     <div className="num w-7 h-7 rounded-full flex items-center justify-center text-[12px] font-bold shrink-0" title="ترتيب الظهور" style={{ background: 'var(--bg-card)', color: 'var(--text-primary)' }}>{b.sort}</div>
179:                     <div className="rounded-xl overflow-hidden shrink-0" style={{ width: tab === 'popup' ? 72 : 168, aspectRatio: P.ratio, boxShadow: '0 0 0 1px var(--border-subtle)' }}>
180:                       <BannerArt b={b} />
181:                     </div>
182:                     <div className="flex-1 min-w-0">
183:                       <div className="flex items-center gap-2 flex-wrap">
184:                         <span className="font-semibold text-[13.5px] c-primary truncate">{b.title}</span>
185:                         <Badge cls={BN_STATUS[st].cls} dot>{BN_STATUS[st].label}</Badge>
186:                       </div>
187:                       <div className="flex items-center gap-1.5 mt-1.5 text-[12px] min-w-0">
188:                         <span className="c-muted shrink-0"><Icon n={L.icon} s={13} /></span>
189:                         {b.linkType === 'none' ? <span className="c-muted">بدون رابط</span>
190:                           : <><span className="c-secondary shrink-0">{L.label}:</span><span className={`truncate ${b.linkType === 'external' ? 'mono text-[11.5px] c-orange' : 'c-primary font-medium'}`}>{tgt || '—'}</span></>}
191:                       </div>
192:                       <div className="flex items-center gap-2 mt-1.5 text-[11.5px] c-secondary">
193:                         <Icon n="calendar" s={12} className="c-muted" />
194:                         {s ? <span className="num">{s.d} <span className="c-muted">{s.t}</span></span> : <span className="c-muted">بدون موعد بداية</span>}
195:                         <span className="c-muted">←</span>
196:                         {e ? <span className="num">{e.d} <span className="c-muted">{e.t}</span></span> : <span className="c-muted">بدون موعد نهاية</span>}
197:                       </div>
198:                     </div>
199:                     <div className="flex items-center gap-3 shrink-0">
200:                       <div className="flex flex-col items-center gap-1">
201:                         {busyToggle === b.id
202:                           ? <span className="w-9 h-5 flex items-center justify-center"><span className="w-3.5 h-3.5 rounded-full border-2 border-[var(--accent-orange)] border-t-transparent animate-spin" /></span>
203:                           : <Toggle on={b.active} disabled={!canEdit} onChange={() => toggle(b)} />}
204:                         <span className="text-[10px] c-muted">{b.active ? 'مفعّل' : 'معطّل'}</span>
205:                       </div>
206:                       {canEdit ? (
207:                         <div className="flex items-center gap-0.5">
208:                           <button className="icon-btn" title="تعديل" onClick={() => setForm({ open: true, initial: b })}><Icon n="edit" s={15} /></button>
209:                           <button className="icon-btn" title="حذف" onClick={() => setDel(b)}><Icon n="trash" s={15} /></button>
210:                         </div>
211:                       ) : <span className="icon-btn" title="لا تملك الصلاحية"><Icon n="lock" s={14} /></span>}
212:                     </div>
213:                   </div>
214:                 );
215:               })}
216:             </div>
217:           )}
218:         </Card>
219: 
220:         {/* Live preview */}
221:         <Card className="xl:col-span-4 xl:sticky xl:top-5" stagger={4}>
222:           <div className="flex items-center justify-between mb-3">
223:             <h3 className="font-display text-[15px] font-semibold c-primary">معاينة الواجهة</h3>
224:             <span className="text-[11px] c-muted">الساري الآن · <span className="num">{phase === 'ready' ? liveInTab.length : 0}</span></span>
225:           </div>
226:           <StorePreview tab={tab} live={phase === 'ready' ? liveInTab : []} />
227:           <div className="text-[11px] c-muted mt-3 flex items-start gap-1.5"><Icon n="info" s={12} className="mt-0.5 shrink-0" /> تظهر فقط البانرات المفعّلة داخل فترة عرضها، مرتبة حسب «ترتيب الظهور».</div>
228:         </Card>
229:       </div>
230: 
231:       <BannerForm open={form.open} initial={form.initial} defaultPlacement={tab} onClose={() => setForm({ open: false, initial: null })} onSave={save} demoState={demoState} />
232: 
233:       <Modal open={!!del} onClose={() => !delBusy && setDel(null)} title="حذف البانر؟" width="max-w-md"
234:         footer={<>
235:           <button className="btn btn-orange" onClick={doDelete} disabled={delBusy}>{delBusy && <span className="w-3.5 h-3.5 rounded-full border-2 border-current border-t-transparent animate-spin" />} حذف نهائي</button>
236:           <button className="btn btn-soft" onClick={() => setDel(null)} disabled={delBusy}>تراجع</button>
237:         </>}>
238:         {del && <>
239:           <div className="rounded-2xl overflow-hidden mb-3" style={{ aspectRatio: BN_PLACEMENTS[del.placement].ratio === '4 / 5' ? '16 / 7' : BN_PLACEMENTS[del.placement].ratio, boxShadow: '0 0 0 1px var(--border-subtle)' }}><BannerArt b={del} big /></div>
240:           <div className="font-semibold c-primary text-[14px]">{del.title}</div>
241:           <div className="text-[12px] c-secondary mt-0.5">{BN_PLACEMENTS[del.placement].label} · ترتيب <span className="num">{del.sort}</span></div>
242:           <div className="text-[12.5px] c-secondary mt-3">سيختفي البانر من المتجر فورًا ولا يمكن استرجاعه. لإخفائه مؤقتًا استخدم مفتاح التعطيل بدلًا من الحذف.</div>
243:         </>}
244:       </Modal>
245:     </section>
246:   );
247: }
