249: function BannerSkeleton() {
250:   return (
251:     <div className="space-y-2.5">
252:       {[0, 1, 2, 3].map(i => (
253:         <div key={i} className="v-subcard p-3 flex items-center gap-4" style={{ opacity: 1 - i * .15 }}>
254:           <div className="sk w-7 h-7 !rounded-full" />
255:           <div className="sk w-[168px] h-[63px] !rounded-xl" />
256:           <div className="flex-1 space-y-2"><div className="sk h-3.5 w-1/2" /><div className="sk h-3 w-1/3" /><div className="sk h-3 w-2/5" /></div>
257:           <div className="sk w-9 h-5 !rounded-full" />
258:         </div>
259:       ))}
260:     </div>
261:   );
