264: function StorePreview({ tab, live }) {
265:   const [i, setI] = useState(0);
266:   useEffect(() => { setI(0); }, [tab, live.length]);
267:   useEffect(() => {
268:     if (tab !== 'slider' || live.length < 2) return;
269:     const t = setInterval(() => setI(x => (x + 1) % live.length), 2600);
270:     return () => clearInterval(t);
271:   }, [tab, live.length]);
272:   const cur = live[i];
273:   const frame = (children) => (
274:     <div className="v-subcard p-2.5" style={{ borderRadius: 18 }}>
275:       <div className="rounded-[12px] overflow-hidden" style={{ background: 'var(--bg-card)', boxShadow: '0 0 0 1px var(--border-subtle)' }}>
276:         <div className="flex items-center gap-1.5 px-3 py-2 v-border-b">
277:           <span className="w-2 h-2 rounded-full" style={{ background: 'var(--badge-gray-bg)' }} /><span className="w-2 h-2 rounded-full" style={{ background: 'var(--badge-gray-bg)' }} /><span className="w-2 h-2 rounded-full" style={{ background: 'var(--badge-gray-bg)' }} />
278:           <span className="flex-1 mx-2 h-4 rounded-full" style={{ background: 'var(--bg-subcard)' }} />
279:         </div>
280:         {children}
281:       </div>
282:     </div>
283:   );
284:   const none = <div className="rounded-lg flex items-center justify-center text-[11px] c-muted hatched" style={{ aspectRatio: '16 / 6' }}>لا يوجد بانر ساري</div>;
285:   const blocks = n => <div className="grid grid-cols-4 gap-1.5 p-2.5">{Array.from({ length: n }).map((_, k) => <div key={k} className="aspect-square rounded-md" style={{ background: 'var(--bg-subcard)' }} />)}</div>;
286: 
287:   if (tab === 'slider') return frame(<>
288:     <div className="p-2.5 pb-0">
289:       {cur ? <div className="rounded-lg overflow-hidden relative" style={{ aspectRatio: '16 / 6' }}><div key={cur.id} className="absolute inset-0 fade-in"><BannerArt b={cur} /></div></div> : none}
290:       <div className="flex items-center justify-center gap-1 py-2">
291:         {live.map((b, k) => <button key={b.id} onClick={() => setI(k)} className="h-1.5 rounded-full transition-all" style={{ width: k === i ? 16 : 6, background: k === i ? 'var(--accent-orange)' : 'var(--badge-gray-bg)' }} />)}
292:       </div>
293:     </div>
294:     {blocks(4)}
295:   </>);
296:   if (tab === 'middle') return frame(<>
297:     {blocks(4)}
298:     <div className="px-2.5 space-y-1.5">{live.length ? live.map(b => <div key={b.id} className="rounded-lg overflow-hidden" style={{ aspectRatio: '16 / 5' }}><BannerArt b={b} /></div>) : none}</div>
299:     {blocks(4)}
300:   </>);
301:   return frame(
302:     <div className="relative">
303:       {blocks(8)}
304:       <div className="absolute inset-0 flex items-center justify-center" style={{ background: 'rgba(0,0,0,.35)' }}>
305:         {live[0] ? <div className="w-[46%] rounded-lg overflow-hidden relative shadow-2xl" style={{ aspectRatio: '4 / 5' }}>
306:           <BannerArt b={live[0]} />
307:           <span className="absolute top-1.5 left-1.5 w-4 h-4 rounded-full bg-white/90 text-black flex items-center justify-center"><Icon n="x" s={9} w={2.5} /></span>
308:         </div> : <span className="text-[11px] text-white/80">لا توجد نافذة سارية</span>}
309:       </div>
310:     </div>
311:   );
312: }
