314: // ---------- Form ----------
315: function BannerForm({ open, initial, defaultPlacement, onClose, onSave, demoState }) {
316:   const blank = { title: '', image: null, art: null, placement: defaultPlacement, linkType: 'none', linkId: null, url: '', sort: '', start: '', end: '', active: true };
317:   const [f, setF] = useState(blank);
318:   const [err, setErr] = useState({});
319:   const [upl, setUpl] = useState({ state: 'idle', pct: 0, name: '', msg: '' });
320:   const [busy, setBusy] = useState(false);
321:   const [srvErr, setSrvErr] = useState(null);
322:   const fileRef = useRef();
323:   const failNext = useRef(false);
324: 
325:   useEffect(() => {
326:     if (!open) return;
327:     setF(initial ? { ...initial, sort: String(initial.sort) } : blank);
328:     setErr({}); setUpl({ state: 'idle', pct: 0, name: '', msg: '' }); setBusy(false); setSrvErr(null);
329:   }, [open]);
330:   const set = (k, v) => { setF(p => ({ ...p, [k]: v })); if (err[k]) setErr(e => ({ ...e, [k]: null })); };
331: 
332:   const startUpload = file => {
333:     if (!file) return;
334:     if (!/^image\/(png|jpe?g|webp)$/.test(file.type)) { setUpl({ state: 'error', pct: 0, name: file.name, msg: 'صيغة غير مدعومة. استخدم PNG أو JPG أو WEBP.' }); return; }
335:     if (file.size > 5 * 1024 * 1024) { setUpl({ state: 'error', pct: 0, name: file.name, msg: 'حجم الصورة أكبر من 5 ميجابايت.' }); return; }
336:     const willFail = demoState === 'error' || failNext.current; failNext.current = false;
337:     const reader = new FileReader();
338:     reader.onload = () => {
339:       let pct = 0;
340:       setUpl({ state: 'uploading', pct: 0, name: file.name, msg: '' });
341:       const t = setInterval(() => {
342:         pct += 9 + Math.random() * 14;
343:         if (willFail && pct > 62) { clearInterval(t); setUpl({ state: 'error', pct: 62, name: file.name, msg: 'انقطع الاتصال أثناء الرفع. (POST /admin/uploads · 502)' }); return; }
344:         if (pct >= 100) { clearInterval(t); setUpl({ state: 'done', pct: 100, name: file.name, msg: '' }); set('image', reader.result); return; }
345:         setUpl(u => ({ ...u, pct }));
346:       }, 160);
347:     };
348:     reader.readAsDataURL(file);
349:   };
350: 
351:   const hasImage = f.image || f.art;
352:   const validate = () => {
353:     const e = {};
354:     if (!f.title.trim()) e.title = 'العنوان مطلوب';
355:     if (!hasImage) e.image = 'ارفع صورة للبانر';
356:     if (f.linkType === 'product' && !f.linkId) e.linkId = 'اختر المنتج';
357:     if (f.linkType === 'category' && !f.linkId) e.linkId = 'اختر القسم';
358:     if (f.linkType === 'brand' && !f.linkId) e.linkId = 'اختر البراند';
359:     if (f.linkType === 'external') {
360:       if (!f.url.trim()) e.url = 'أدخل الرابط';
361:       else if (!/^https?:\/\/\S+\.\S+/.test(f.url.trim())) e.url = 'الرابط يجب أن يبدأ بـ https:// ويكون صالحًا';
362:     }
363:     if (f.sort === '' ) e.sort = 'أدخل ترتيب الظهور';
364:     if (f.start && f.end && new Date(f.end) <= new Date(f.start)) e.end = 'نهاية العرض يجب أن تكون بعد البداية';
365:     return e;
366:   };
367:   const submit = () => {
368:     if (busy || upl.state === 'uploading') return;
369:     const e = validate(); setErr(e);
370:     if (Object.keys(e).length) return;
371:     setBusy(true); setSrvErr(null);
372:     setTimeout(() => {
373:       if (demoState === 'error' && !initial) { setBusy(false); setSrvErr('تعذّر حفظ البانر. حاول مرة أخرى. (422 · image_id غير صالح)'); return; }
374:       onSave({ ...f, sort: parseInt(f.sort, 10), linkId: ['none', 'external'].includes(f.linkType) ? null : f.linkId, url: f.linkType === 'external' ? f.url.trim() : '' });
375:     }, 900);
376:   };
377: 
378:   const P = BN_PLACEMENTS[f.placement];
379:   const targetField = () => {
380:     const opts = f.linkType === 'product' ? INV_PRODUCTS.map(p => ({ value: p.id, label: p.name }))
381:       : f.linkType === 'category' ? BN_CATEGORIES.map(c => ({ value: c.id, label: c.name }))
382:       : f.linkType === 'brand' ? BN_BRANDS.map(c => ({ value: c.id, label: c.name })) : null;
383:     if (f.linkType === 'none') return null;
384:     if (f.linkType === 'external') return (
385:       <Field label="الرابط الخارجي" req error={err.url}>
386:         <div className="relative">
387:           <input className={`inp mono text-left pl-9 ${err.url ? 'err' : ''}`} dir="ltr" value={f.url} onChange={e => set('url', e.target.value)} placeholder="https://" />
388:           <span className="absolute left-3 top-1/2 -translate-y-1/2 c-muted"><Icon n="external" s={14} /></span>
389:         </div>
390:       </Field>
391:     );
392:     return (
393:       <Field label={'اختر ال' + BN_LINK_TYPES[f.linkType].label} req error={err.linkId}>
394:         <Sel value={f.linkId} onChange={v => set('linkId', v)} placeholder="اختر…" options={opts} className={err.linkId ? 'err' : ''} />
395:       </Field>
396:     );
397:   };
398: 
399:   return (
400:     <Modal open={open} onClose={() => !busy && onClose()} width="max-w-3xl" title={initial ? 'تعديل بانر' : 'إضافة بانر'} sub={initial ? initial.title : `سيُضاف إلى «${P.label}»`}
401:       footer={<>
402:         <button className="btn btn-dark min-w-[110px]" onClick={submit} disabled={busy || upl.state === 'uploading'}>
403:           {busy ? <><span className="w-3.5 h-3.5 rounded-full border-2 border-current border-t-transparent animate-spin" /> جارٍ الحفظ…</> : 'حفظ'}
404:         </button>
405:         <button className="btn btn-soft" onClick={onClose} disabled={busy}>إلغاء</button>
406:         <span className="flex-1" />
407:         {upl.state === 'uploading' && <span className="text-[11.5px] c-muted">انتظر اكتمال رفع الصورة</span>}
408:       </>}>
409:       <div className="space-y-5">
410:         {srvErr && <InlineAlert kind="red" title="لم يتم الحفظ">{srvErr}</InlineAlert>}
411: 
412:         <Field label="العنوان" req error={err.title} hint="للاستخدام الداخلي ولوصف الصورة">
413:           <input className={`inp ${err.title ? 'err' : ''}`} value={f.title} onChange={e => set('title', e.target.value)} placeholder="مثال: مجموعة الشتاء — خصم ٤٠٪" />
414:         </Field>
415: 
416:         {/* Image */}
417:         <div>
418:           <span className="field-label">الصورة <span className="c-orange">*</span><span className="c-muted font-normal">· صورة واحدة · PNG / JPG / WEBP حتى 5MB</span></span>
419:           <input ref={fileRef} type="file" accept="image/png,image/jpeg,image/webp" className="hidden" onChange={e => { startUpload(e.target.files[0]); e.target.value = ''; }} />
420:           {upl.state === 'uploading' ? (
421:             <div className="v-subcard p-5 flex items-center gap-4" style={{ aspectRatio: P.ratio === '4 / 5' ? '16 / 6' : P.ratio, maxHeight: 220 }}>
422:               <div className="flex-1">
423:                 <div className="flex items-center justify-between text-[12.5px] mb-2"><span className="c-primary font-medium truncate">{upl.name}</span><span className="num c-secondary">{Math.round(upl.pct)}%</span></div>
424:                 <div className="h-2 rounded-full hatched overflow-hidden"><div className="h-full rounded-full bar-hatched-orange transition-all" style={{ width: upl.pct + '%' }} /></div>
425:                 <div className="text-[11px] c-muted mt-2">جارٍ رفع الصورة…</div>
426:               </div>
427:             </div>
428:           ) : hasImage ? (
429:             <div className="relative rounded-2xl overflow-hidden group" style={{ aspectRatio: P.ratio === '4 / 5' ? '16 / 7' : P.ratio, boxShadow: '0 0 0 1px var(--border-subtle)' }}>
430:               {f.placement === 'popup'
431:                 ? <div className="w-full h-full flex items-center justify-center hatched"><div className="h-[88%] rounded-lg overflow-hidden" style={{ aspectRatio: '4 / 5' }}><BannerArt b={f} big /></div></div>
432:                 : <BannerArt b={f} big />}
433:               <div className="absolute bottom-3 left-3 flex items-center gap-2">
434:                 <button className="btn btn-sm" style={{ background: 'rgba(255,255,255,.95)', color: '#18151c' }} onClick={() => fileRef.current.click()}><Icon n="refresh" s={13} /> استبدال الصورة</button>
435:               </div>
436:               {upl.state === 'done' && <span className="absolute top-3 right-3 badge b-green"><Icon n="check" s={11} w={2.5} /> تم الرفع</span>}
437:             </div>
438:           ) : (
439:             <button type="button" onClick={() => fileRef.current.click()}
440:               onDragOver={e => e.preventDefault()} onDrop={e => { e.preventDefault(); startUpload(e.dataTransfer.files[0]); }}
441:               className="w-full rounded-2xl flex flex-col items-center justify-center gap-2 transition hover:opacity-90"
442:               style={{ aspectRatio: P.ratio === '4 / 5' ? '16 / 6' : P.ratio, maxHeight: 220, border: `1.5px dashed ${err.image || upl.state === 'error' ? 'var(--badge-red-text)' : 'var(--border-strong)'}`, background: 'var(--bg-subcard)' }}>
443:               <span className="w-11 h-11 rounded-full flex items-center justify-center" style={{ background: 'var(--bg-card)', color: 'var(--accent-orange)' }}><Icon n="upload" s={18} /></span>
444:               <span className="text-[13px] font-semibold c-primary">اسحب الصورة هنا أو اضغط للاختيار</span>
445:               <span className="text-[11px] c-muted">المقاس المقترح لـ{P.label}: {f.placement === 'slider' ? '1920×720' : f.placement === 'middle' ? '1920×600' : '800×1000'}</span>
446:             </button>
447:           )}
448:           {upl.state === 'error' && (
449:             <div className="mt-2"><InlineAlert kind="red" title="فشل رفع الصورة">
450:               <span>{upl.msg}</span>
451:               <button className="font-semibold c-orange mr-2 hover:underline" onClick={() => fileRef.current.click()}>إعادة المحاولة</button>
452:             </InlineAlert></div>
453:           )}
454:           {err.image && upl.state !== 'error' && <span className="block text-[11px] mt-1" style={{ color: 'var(--badge-red-text)' }}>{err.image}</span>}
455:           {!hasImage && upl.state === 'idle' && <button className="text-[11px] c-muted mt-1.5 hover:c-primary underline decoration-dotted" onClick={() => { failNext.current = true; fileRef.current.click(); }}>معاينة حالة فشل الرفع</button>}
456:         </div>
457: 
458:         {/* Placement */}
459:         <div>
460:           <span className="field-label">مكان العرض <span className="c-orange">*</span></span>
461:           <div className="grid grid-cols-3 gap-2.5">
462:             {Object.entries(BN_PLACEMENTS).map(([k, p]) => (
463:               <button key={k} type="button" onClick={() => set('placement', k)}
464:                 className={`rounded-2xl p-3 flex items-center gap-2.5 text-right border transition ${f.placement === k ? 'border-[var(--accent-orange)]' : 'border-transparent'}`}
465:                 style={{ background: f.placement === k ? 'var(--accent-orange-light)' : 'var(--bg-subcard)' }}>
466:                 <span className={`w-8 h-8 rounded-full flex items-center justify-center shrink-0 ${f.placement === k ? 'bg-[var(--accent-orange)] text-white' : 'v-icon-well'}`}><Icon n={p.icon} s={15} /></span>
467:                 <span className="text-[12.5px] font-semibold c-primary">{p.label}</span>
468:               </button>
469:             ))}
470:           </div>
471:         </div>
472: 
473:         {/* Link */}
474:         <div className="v-subcard p-4 space-y-3.5">
475:           <div>
476:             <span className="field-label">نوع الرابط</span>
477:             <div className="seg flex-wrap !bg-[var(--bg-card)]">
478:               {Object.entries(BN_LINK_TYPES).map(([k, l]) => (
479:                 <button key={k} type="button" className={f.linkType === k ? 'on !bg-[var(--pill-active-bg)] !text-[var(--pill-active-text)]' : ''} onClick={() => { set('linkType', k); set('linkId', null); setErr(e => ({ ...e, linkId: null, url: null })); }}>
480:                   <span className="inline-flex items-center gap-1.5"><Icon n={l.icon} s={12} /> {l.label}</span>
481:                 </button>
482:               ))}
483:             </div>
484:           </div>
485:           {f.linkType === 'none'
486:             ? <div className="text-[11.5px] c-muted">الصورة ستظهر بدون إمكانية الضغط عليها.</div>
487:             : <div className="fade-in" key={f.linkType}>{targetField()}</div>}
488:         </div>
489: 
490:         {/* Schedule */}
491:         <div className="grid grid-cols-1 sm:grid-cols-[120px_1fr_1fr] gap-4">
492:           <Field label="ترتيب الظهور" req error={err.sort} hint="الأصغر يظهر أولًا">
493:             <NumInput integer value={f.sort} onChange={v => set('sort', v)} placeholder="1" err={err.sort} />
494:           </Field>
495:           <Field label="بداية العرض" hint={f.start ? null : 'فارغ = يبدأ فورًا'}>
496:             <div className="flex items-center gap-1.5">
497:               <input type="datetime-local" className="inp num" value={f.start} onChange={e => { set('start', e.target.value); setErr(x => ({ ...x, end: null })); }} />
498:               {f.start && <button className="icon-btn shrink-0" title="مسح" onClick={() => set('start', '')}><Icon n="x" s={12} /></button>}
499:             </div>
500:           </Field>
501:           <Field label="نهاية العرض" error={err.end} hint={f.end ? null : 'فارغ = بدون نهاية'}>
502:             <div className="flex items-center gap-1.5">
503:               <input type="datetime-local" className={`inp num ${err.end ? 'err' : ''}`} value={f.end} onChange={e => set('end', e.target.value)} />
504:               {f.end && <button className="icon-btn shrink-0" title="مسح" onClick={() => set('end', '')}><Icon n="x" s={12} /></button>}
505:             </div>
506:           </Field>
507:         </div>
508: 
509:         <div className="v-subcard p-3.5 flex items-center justify-between">
510:           <div>
511:             <div className="text-[13px] font-semibold c-primary flex items-center gap-2">التفعيل: {f.active ? 'مفعّل' : 'معطّل'}
512:               <Badge cls={BN_STATUS[bnStatus({ ...f })].cls} dot>{BN_STATUS[bnStatus({ ...f })].label}</Badge>
513:             </div>
514:             <div className="text-[11px] c-secondary mt-0.5">الحالة تُحسب تلقائيًا من التفعيل وتواريخ العرض.</div>
515:           </div>
516:           <Toggle on={f.active} onChange={v => set('active', v)} />
517:         </div>
518:       </div>
519:     </Modal>
520:   );
521: }
