 508:     .banner-heading {
 509:       font-family: 'Poppins', sans-serif;
 510:       font-size: 27px;
 511:       font-weight: 700;
 512:       color: #000;
 513:       line-height: 1.15;
 514:       margin-bottom: 10px;
