 709: 
 710:     .crest-bag-crown {
 711:       width: 156px;
 712:       height: 62px;
 713:       margin-bottom: 4px;
 714:     }
 715: 
 716:     .crest-title-top {
 717:       font-family: 'Lora', serif;
 718:       font-size: 18px;
 719:       font-weight: 700;
 720:       letter-spacing: 1.8px;
 721:       text-transform: uppercase;
 722:       color: #ffffff;
 723:       line-height: 1.1;
 724:       border-top: 2px solid #ffffff;
