 728: 
 729:     .crest-title-bottom {
 730:       font-family: 'Lora', serif;
 731:       font-size: 22px;
 732:       font-weight: 700;
 733:       letter-spacing: 1.5px;
 734:       text-transform: uppercase;
 735:       color: #ffffff;
 736:       line-height: 1.15;
