 794: 
 795:     /* Engraved Horizontal Divider Line with Subtle Center Shadow */
 796:     .footer-engraved-divider {
 797:       max-width: 980px;
 798:       margin: 0 auto 44px;
 799:       height: 2px;
 800:       background: linear-gradient(
