 802:         rgba(255, 255, 255, 0) 0%,
 803:         rgba(20, 20, 20, 0.65) 20%,
 804:         rgba(15, 15, 15, 0.85) 50%,
 805:         rgba(20, 20, 20, 0.65) 80%,
 806:         rgba(255, 255, 255, 0) 100%
 807:       );
 808:       border-bottom: 1px solid rgba(255, 255, 255, 0.08);
 809:       position: relative;
