 894:       border-radius: 50%;
 895:       background-color: #dcdcdc;
 896:       color: #2f2f2f;
 897:       display: inline-flex;
 898:       align-items: center;
 899:       justify-content: center;
 900:       font-size: 15px;
 901:       font-weight: 700;
 902:       transition: background-color 0.25s ease, transform 0.25s ease, color 0.25s ease;
 903:     }
 904: 
 905:     .social-circle-btn:hover {
 906:       background-color: #ffffff;
 907:       color: #000000;
 908:       transform: translateY(-3px);
 909:     }
 910: 
 911:     /* Subtle Interactive Toast Notification */
 912:     .toast-notification {
 913:       position: fixed;
 914:       bottom: 24px;
 915:       right: 24px;
 916:       background-color: #111111;
 917:       color: #ffffff;
 918:       padding: 12px 20px;
 919:       border-radius: 4px;
 920:       font-size: 12.5px;
 921:       font-family: 'Poppins', sans-serif;
 922:       box-shadow: 0 10px 25px rgba(0, 0, 0, 0.25);
 923:       border-left: 3px solid #b8d432;
 924:       z-index: 999;
 925:       opacity: 0;
 926:       transform: translateY(15px);
 927:       pointer-events: none;
 928:       transition: opacity 0.28s ease, transform 0.28s ease;
 929:     }
 930: 
 931:     .toast-notification.show {
 932:       opacity: 1;
 933:       transform: translateY(0);
 934:     }
 935: 
 936:     /* Responsive adjustments */
 937:     @media (max-width: 992px) {
