 959:       .hero-bg-backdrop-img {
 960:         width: 100%;
 961:         height: 100%;
 962:         top: 0;
 963:         opacity: 0.55;
 964:       }
 965:       .hero-bg-backdrop-overlay {
 966:         background: linear-gradient(
 967:           180deg,
 968:           #dfe5e9 0%,
 969:           rgba(223, 229, 233, 0.94) 45%,
 970:           rgba(223, 229, 233, 0.5) 100%
 971:         );
