 973:       .footer-showcase-carousel {
 974:         gap: 20px;
 975:       }
 976:       .showcase-items-track {
 977:         flex-direction: column;
 978:         gap: 28px;
 979:       }
 980:       .footer-columns-grid {
 981:         grid-template-columns: repeat(2, 1fr);
 982:       }
 983:     }
 984: 
 985:     @media (max-width: 576px) {
 986:       .nav-links {
