  5: namespace App\Http\Controllers\Api\V1\Admin;
  6: 
  7: use App\Http\Controllers\Controller;
  8: use App\Http\Requests\Admin\Category\ReorderCategoriesRequest;
  9: use App\Http\Requests\Admin\Category\StoreCategoryRequest;
 10: use App\Http\Requests\Admin\Category\UpdateCategoryRequest;
 11: use App\Http\Resources\Admin\CategoryResource;
 12: use App\Models\Category;
 13: use App\Services\Catalog\CategoryService;
 14: use App\Services\SearchTerm;
 15: use Illuminate\Http\JsonResponse;
 16: use Illuminate\Http\Request;
 17: use Illuminate\Http\Resources\Json\AnonymousResourceCollection;
 18: use Illuminate\Routing\Controllers\HasMiddleware;
 19: use Illuminate\Routing\Controllers\Middleware;
 20: 
 21: class CategoryController extends Controller implements HasMiddleware
 22: {
 23:     public function __construct(private CategoryService $service) {}
 24: 
 25:     public static function middleware(): array
 26:     {
 27:         return [
 28:             new Middleware('can:categories.view', only: ['index', 'show']),
 29:             new Middleware('can:categories.create', only: ['store']),
 30:             new Middleware('can:categories.update', only: ['update', 'reorder']),
 31:             new Middleware('can:categories.delete', only: ['destroy']),
 32:         ];
 33:     }
 34: 
 35:     public function index(Request $request): AnonymousResourceCollection
 36:     {
 37:         $filters = $request->validate([
 38:             'tree' => ['nullable', 'boolean'],
 39:             'search' => ['nullable', 'string', 'max:100'],
 40:             'parent_id' => ['nullable', 'string', 'regex:/^(root|[0-9]{1,18})$/'],
 41:             'is_active' => ['nullable', 'boolean'],
 42:             'per_page' => ['nullable', 'integer', 'min:1'],
 43:         ]);
 44: 
 45:         if ($request->boolean('tree')) {
 46:             return CategoryResource::collection($this->service->tree());
 47:         }
 48: 
 49:         $perPage = min((int) ($filters['per_page'] ?? 15), 100);
 50: 
 51:         $categories = Category::query()
 52:             ->with(['parent.media', 'media'])
 53:             // F16: products_count excludes soft-deleted rows while delete()
 54:             // checks withTrashed() — also expose the trashed-inclusive count
 55:             // so the UI can explain "0 live, N deleted" instead of confusing 409s.
 56:             ->withCount(['products', 'products as all_products_count' => fn ($q) => $q->withTrashed()])
 57:             ->when(isset($filters['search']) && $filters['search'] !== '', function ($query) use ($filters): void {
 58:                 $pattern = SearchTerm::pattern($filters['search']);
 59:                 $query->where(fn ($q) => $q->whereLike('name_ar', $pattern, caseSensitive: false)
 60:                     ->orWhereLike('name_en', $pattern, caseSensitive: false));
 61:             })
 62:             ->when(isset($filters['parent_id']), function ($query) use ($filters): void {
 63:                 if ($filters['parent_id'] === 'root') {
 64:                     $query->whereNull('parent_id');
 65:                 } else {
 66:                     $query->where('parent_id', (int) $filters['parent_id']);
 67:                 }
 68:             })
 69:             ->when(isset($filters['is_active']), fn ($query) => $query->where('is_active', filter_var($filters['is_active'], FILTER_VALIDATE_BOOLEAN)))
 70:             ->orderBy('sort_order')
 71:             ->orderBy('id')
 72:             ->paginate($perPage)
 73:             ->withQueryString();
 74: 
 75:         return CategoryResource::collection($categories);
 76:     }
 77: 
 78:     public function show(Category $category): CategoryResource
 79:     {
 80:         $category->load('parent.media', 'children.media', 'media')->loadCount(['products', 'products as all_products_count' => fn ($q) => $q->withTrashed()]);
 81: 
 82:         return CategoryResource::make($category);
 83:     }
 84: 
 85:     public function store(StoreCategoryRequest $request): JsonResponse
 86:     {
 87:         $category = $this->service->create($request->validated(), $request->file('image'));
 88:         $category->load('parent.media', 'media')->loadCount(['products', 'products as all_products_count' => fn ($q) => $q->withTrashed()]);
 89: 
 90:         return CategoryResource::make($category)->response()->setStatusCode(201);
 91:     }
 92: 
 93:     // ملحوظة: تحديث قسم مع صورة بيتبعت POST مع _method=PUT، لأن PHP لا يقرأ ملفات multipart مع PUT.
 94:     public function update(UpdateCategoryRequest $request, Category $category): CategoryResource
 95:     {
 96:         $category = $this->service->update($category, $request->validated(), $request->file('image'));
 97:         $category->load('parent.media', 'media')->loadCount(['products', 'products as all_products_count' => fn ($q) => $q->withTrashed()]);
 98: 
 99:         return CategoryResource::make($category);
100:     }
101: 
102:     public function destroy(Category $category): JsonResponse
103:     {
104:         $this->service->delete($category);
105: 
106:         return response()->json(['message' => 'تم الحذف']);
107:     }
108: 
109:     public function reorder(ReorderCategoriesRequest $request): JsonResponse
110:     {
111:         $this->service->reorder($request->validated()['items']);
112: 
113:         return response()->json(['message' => 'تم الترتيب']);
114:     }
115: } 1: <?php
