29:             $expected = $validated['expected'];
30:             unset($validated['expected']);
31:             $this->settings->updateBatch($validated, $expected);
32:         } catch (InvalidArgumentException) {
33:             return response()->json([
34:                 'message' => 'إعداد أو أكثر غير مهيأ في قاعدة البيانات. شغّل Seeder الإعدادات ثم أعد المحاولة.',
