  7: function userParams(p: UserListParams): Record<string, string | number> {
  8:   const out: Record<string, string | number> = { page: p.page ?? 1, per_page: p.per_page ?? 8 };
  9:   if (p.search?.trim()) out.search = p.search.trim();
 10:   if (p.role) out.role = p.role;
 11:   // axios بيشيل أي null، فبنبعت '' عشان Laravel يحوّله null ويفلتر على "من غير فرع"
 12:   if (p.branch_id === 'none') out.branch_id = '';
 13:   else if (typeof p.branch_id === 'number') out.branch_id = p.branch_id;
 14:   if (typeof p.is_active === 'boolean') out.is_active = p.is_active ? 1 : 0;
 15:   return out;
 16: }
