57: export function permLabel(key: string): string {
58:   if (OVERRIDES[key]) return OVERRIDES[key];
59:   const [res, ...rest] = key.split('.');
60:   const act = rest.join('.');
61:   if (ACTION[act] && RESOURCE[res]) return `${ACTION[act]} ${RESOURCE[res]}`;
62:   return key; // fallback: المفتاح نفسه
63: }
64: export const isSensitive = (key: string) => SENSITIVE.has(key) || key.endsWith('.manage');
