69: /** بيحوّل رد GET /permissions لنفس شكل PermissionGroup اللي roles.tsx متعوّد عليه */
70: export function buildPermissionGroups(api: Record<string, { name: string }[]>): UiPermGroup[] {
71:   const byModule = new Map<string, string[]>();
72:   Object.entries(api).forEach(([prefix, list]) => {
73:     const mod = UI_MODULES.find(m => m.prefixes.includes(prefix)) ?? OTHER_MODULE;
74:     byModule.set(mod.module, [...(byModule.get(mod.module) ?? []), ...list.map(p => p.name)]);
75:   });
76:   const seen = new Set<string>();
77:   return [...UI_MODULES, OTHER_MODULE]
78:     .filter(m => byModule.has(m.module))
79:     .map(m => {
80:       const names = [...new Set(byModule.get(m.module)!)].filter(n => !seen.has(n)).sort();
81:       names.forEach(n => seen.add(n));
82:       const prefixes = [...new Set(names.map(n => n.split('.')[0]))];
83:       return { module: m.module, label: m.label, icon: m.icon, keys: prefixes.join(' · '),
84:         perms: names.map(n => [n, permLabel(n), isSensitive(n)] as [string, string, boolean]) };
85:     }).filter(g => g.perms.length > 0);
