 32:   useEffect(() => { ['alfarid_mock_users','alfarid_mock_roles','alfarid_mock_settings'].forEach(key => localStorage.removeItem(key)); }, []);
 33:   // Parse URL query parameters if present (e.g. ?role=3 or ?roleId=2 or ?tab=store)
 34:   const queryParams = useMemo(() => {
 35:     const raw = window.location.hash.includes('?')
 36:       ? window.location.hash.split('?')[1]
 37:       : window.location.search.replace(/^\?/, '');
 38:     const sp = new URLSearchParams(raw);
 39:     const roleParam = sp.get('role') || sp.get('roleId');
 40:     const roleIdParam = sp.get('roleId') || sp.get('role');
 41:     const tabParam = sp.get('tab');
 42:     return {
 43:       role: roleParam ? (isNaN(Number(roleParam)) ? 'all' : Number(roleParam)) : 'all',
 44:       roleId: roleIdParam && !isNaN(Number(roleIdParam)) ? Number(roleIdParam) : undefined,
 45:       tab: tabParam || initialTab || undefined,
 46:     };
 47:   }, [page, window.location.hash, initialTab]);
