 59: export function SettingsScreen({ onNavigate, can, initialTab }: { onNavigate?: (page: 'users' | 'roles' | 'settings') => void; can: (p: string) => boolean; initialTab?: string }) {
 60:   const { refreshBranding } = useBranding();
 61:   const query = useSettingsQuery();
 62:   useQueryError(query.error);
 63:   const [server, setServer] = useState<AdminSettings | null>(null);
 64:   const [s, setS] = useState<AdminSettings | null>(null);
 65:   const [tab, setTab] = useState(() => (initialTab === 'store' || initialTab === 'banners') ? 'store' : (initialTab || 'company'));
 66:   const [saving, setSaving] = useState(false);
 67:   const [conflict, setConflict] = useState<string | false>(false);
 68:   const [fieldErrors, setFieldErrors] = useState<Record<string,string[]>>({});
 69:   const { centralAccess } = useMe();
 70:   const editable = centralAccess && ( can('settings.update') || can('settings.manage'));
 71:   const loading = query.loading && !server;
 72: 
 73:   useEffect(() => {
 74:     if (initialTab) {
 75:       setTab(initialTab === 'banners' ? 'store' : initialTab);
 76:     }
 77:   }, [initialTab]);
 78:   useEffect(() => { if (query.data) { setServer(clone(query.data)); setS(clone(query.data)); setFieldErrors({}); } }, [query.data]);
 79:   const set = (group: keyof AdminSettings, key: string, val: any) =>
 80:     setS(p => p && editable ? ({ ...p, [group]: { ...(p[group] as any), [key]: val } }) : p);
 81: 
 82:   const setNum = (doc: string, key: string, val: any) =>
 83:     setS(p => p && editable ? ({ ...p, numbering: { ...p.numbering, [doc]: { ...p.numbering[doc], [key]: val } } }) : p);
 84: 
 85:   // compute changed fields (flat)
 86:   const diffs = useMemo(() => {
 87:     const out: [string, string][] = [];
 88:     if (!s || !server) return out;
 89:     (Object.keys(s) as (keyof AdminSettings)[]).forEach(g => {
 90:       Object.keys(s[g]).forEach(k => {
 91:         if (JSON.stringify((s[g] as any)[k]) !== JSON.stringify((server[g] as any)[k])) {
 92:           out.push([g, k]);
 93:         }
 94:       });
 95:     });
 96:     return out;
 97:   }, [s, server]);
 98: 
 99:   const dirtyGroups = new Set(diffs.map(d => d[0]));
100:   const isDirty = diffs.length > 0;
101: 
102:   useEffect(() => {
103:     if (!isDirty) return;
104:     const guard = (event: BeforeUnloadEvent) => { event.preventDefault(); event.returnValue = ''; };
105:     window.addEventListener('beforeunload', guard);
106:     return () => window.removeEventListener('beforeunload', guard);
107:   }, [isDirty]);
108:   const save = async () => {
109:     if (!s || !server || !editable || saving) return;
110:     const patch = settingsPatch(s, server);
111:     if (!Object.keys(patch).length) return;
112:     setSaving(true); setFieldErrors({});
113:     const result = await runMutation(() => adminApi.updateSettings({...patch, expected: settingsExpected(patch, server)}));
114:     setSaving(false);
115:     if (!result.ok) {
116:       if (result.error.status === 422) setFieldErrors(result.error.fields);
117:       if (result.error.status === 409) setConflict(result.error.message);
118:       if (result.error.status !== 401) toast(result.error.message, 'err');
119:       return;
120:     }
121:     const fresh = toAdminSettings(result.data.data);
122:     void refreshBranding();
123:     setServer(clone(fresh)); setS(clone(fresh)); setConflict(false);
124:     if (result.data.warnings?.length) result.data.warnings.forEach(message => toast(message, 'warn'));
125:     else toast('تم حفظ الإعدادات بنجاح');
126:   };
127:   const reload = () => { setConflict(false); query.reload(); };
128:   if (query.error && !server && tab !== 'store') return <EmptyState icon="lock" title={query.error.message} action={<GhostButton onClick={query.reload}>إعادة المحاولة</GhostButton>} />;
129:   if ((!s || !server) && tab !== 'store') return <SettingsSkeleton />;
130: 
131:   return (
132:     <section className="space-y-5 pb-20" data-screen-label="03 Settings">
133:       <PageHeader
134:         title="الإعدادات العامة"
135:         subtitle="هوية المؤسسة، الضرائب، الترقيم التلقائي للمستندات، سياسات الإرجاع وسير عمل المشتريات."
136:         action={
137:           <div className="flex items-center gap-3 stagger-item stagger-2">
138:             {onNavigate && (
139:               <GhostButton icon="users" onClick={() => onNavigate('users')}>
140:                 فريق العمل
141:               </GhostButton>
142:             )}
143:           </div>
144:         }
145:       />
146: 
147:       {conflict && (
148:         <div className="v-conflict rounded-[22px] p-4 flex flex-wrap items-center gap-4 v-pop-in">
149:           <span className="w-10 h-10 rounded-full flex items-center justify-center bg-white/15 shrink-0"><Icon name="alert" className="w-5 h-5" strokeWidth={2.2} /></span>
150:           <div className="flex-1 min-w-[240px]">
151:             <div className="font-semibold text-[14px]">تعارض في البيانات (409)</div>
152:             <div className="text-[12.5px] opacity-85 mt-0.5">{conflict}</div>
153:           </div>
154:           <div className="flex items-center gap-2">
155:             <button type="button" onClick={() => setConflict(false)} className="h-9 px-4 rounded-full text-[12.5px] font-semibold hover:bg-white/10">لاحقاً</button>
156:             <button type="button" onClick={reload} className="h-9 px-4 rounded-full text-[12.5px] font-semibold bg-white flex items-center gap-1.5" style={{ color: '#c2410c' }}><Icon name="refresh" className="w-3.5 h-3.5" strokeWidth={2.2} />إعادة التحميل</button>
157:           </div>
158:         </div>
159:       )}
160: 
161:       <div className="grid grid-cols-1 lg:grid-cols-12 gap-5 items-start">
162:         {/* Tabs rail */}
163:         <nav className="lg:col-span-3 v-card p-2 stagger-item stagger-2 lg:sticky lg:top-5">
164:           {SETTINGS_TABS.map((t) => {
165:             const active = tab === t.key;
166:             return (
167:               <button type="button" key={t.key} onClick={() => setTab(t.key)}
168:                 className={`w-full flex items-center gap-3 p-3 rounded-2xl text-start transition ${active ? 'v-tab-active' : 'v-tab'}`}>
169:                 <span className={`w-9 h-9 rounded-xl flex items-center justify-center shrink-0 ${active ? 'text-white v-accent-btn' : 'v-icon-well'}`}><Icon name={t.icon} className="w-4 h-4" /></span>
170:                 <div className="flex-1 min-w-0">
171:                   <div className="text-[13px] font-semibold" style={{ color: 'var(--text-primary)' }}>{t.label}</div>
172:                   <div className="text-[11px] truncate" style={{ color: 'var(--text-muted)' }}>{t.desc}</div>
173:                 </div>
174:                 {dirtyGroups.has(t.key) && <span className="w-2 h-2 rounded-full shrink-0" style={{ background: 'var(--accent-orange)' }} title="تعديلات غير محفوظة" />}
175:               </button>
176:             );
177:           })}
178:         </nav>
179: 
180:         <div className="lg:col-span-9 stagger-item stagger-3" key={tab}>
181:           {tab === 'store' ? (
182:             <StoreManagementTab can={can} />
183:           ) : (!s || !server || loading) ? <SettingsSkeleton /> : (
184:             <fieldset disabled={!editable || saving} className="v-tab-in space-y-5">
185:               {tab === 'company' && <CompanyTab errors={fieldErrors} v={s.company} set={(k, val) => set('company', k, val)} />}
186:               {tab === 'tax' && <TaxTab errors={fieldErrors} v={s.tax} set={(k, val) => set('tax', k, val)} />}
187:               {tab === 'numbering' && <NumberingTab errors={fieldErrors} v={s.numbering} server={server.numbering} setNum={setNum} />}
188:               {tab === 'orders' && <ReturnsTab v={s.orders} set={(k, val) => set('orders', k, val)} />}
189:               {Object.entries(fieldErrors).filter(([key]) => !['company','tax','numbering'].includes(tab) && key in s[tab as 'orders' | 'purchases']).map(([key,messages]) => <div role="alert" key={key}>{messages.join('، ')}</div>)}
190:               {tab === 'purchases' && <PurchasesTab v={s.purchases} set={(k, val) => set('purchases', k, val)} />}
191:             </fieldset>
192:           )}
193:         </div>
194:       </div>
195: 
196:       <StickyBar show={isDirty && editable} onSave={save} onReset={() => setS(clone(server))} saving={saving} count={diffs.length} />
197:     </section>
198:   );
199: }
