204:       <Skeleton className="h-5 w-40 rounded" /><Skeleton className="h-3 w-64 rounded" />
205:       <div className="flex gap-4 pt-2"><Skeleton className="w-24 h-24 rounded-2xl" /><div className="flex-1 space-y-3"><Skeleton className="h-11 rounded-2xl" /><Skeleton className="h-3 w-40 rounded" /></div></div>
