274: /* ---------- Tab 2: Tax ---------- */
275: function TaxTab({ errors, v, set }: { errors: Record<string,string[]>; v: AdminSettings['tax']; set: (k: keyof AdminSettings['tax'], val: any) => void }) {
276:   const [sample, setSample] = useState(1000);
277:   const rate = Number(v.default_tax_rate) || 0;
278:   const on = v.tax_enabled;
279:   let net: number, tax: number, gross: number;
280:   if (!on) { net = sample; tax = 0; gross = sample; }
281:   else if (v.prices_include_tax) { gross = sample; net = sample / (1 + rate / 100); tax = gross - net; }
282:   else { net = sample; tax = (sample * rate) / 100; gross = net + tax; }
283:   const rateErr = rate < 0 || rate > 100;
284: 
285:   return (
286:     <div className="grid grid-cols-1 xl:grid-cols-5 gap-5 items-start">
287:       <SectionCard title="ضريبة القيمة المضافة" subtitle="إعدادات الضريبة المطبّقة على الفواتير الإلكترونية." className="xl:col-span-3">
288:         <div className="v-subcard p-4 flex items-center justify-between gap-4">
289:           <div className="flex items-center gap-3">
290:             <span className={`w-10 h-10 rounded-full flex items-center justify-center ${on ? 'v-badge-green' : 'v-icon-well'}`}><Icon name="percent" className="w-4 h-4" /></span>
291:             <div>
292:               <div className="text-[13.5px] font-semibold" style={{ color: 'var(--text-primary)' }}>تفعيل ضريبة القيمة المضافة</div>
293:               <div className="text-[11.5px]" style={{ color: 'var(--text-muted)' }}>{on ? 'تُحتسب الضريبة على جميع الفواتير' : 'لن تُضاف أي ضريبة على الفواتير'}</div>
294:             </div>
295:           </div>
296:           <Toggle on={on} onChange={x => set('tax_enabled', x)} />
297:         </div>
298: 
299:         <div className={`transition-opacity ${on ? '' : 'opacity-45 pointer-events-none'}`}>
300:           <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mt-5">
301:             <Field error={errors.tax_number?.[0]} label="الرقم الضريبي" hint="يُطبع على الفواتير الإلكترونية.">
302:               <TextInput value={v.tax_number} onChange={x => set('tax_number', x)} icon="hash" dir="ltr" />
303:             </Field>
304:             <Field label="نسبة الضريبة الافتراضية" error={errors.default_tax_rate?.[0] || (rateErr ? 'النسبة يجب أن تكون بين 0 و 100' : null)}>
305:               <TextInput value={v.default_tax_rate} onChange={x => set('default_tax_rate', x === '' ? '' : Number(x))} type="number" dir="ltr" error={rateErr}
306:                 suffix={<span className="text-[13px] font-semibold" style={{ color: 'var(--text-muted)' }}>%</span>} />
307:             </Field>
308:           </div>
309:           <div className="flex flex-wrap gap-1.5 mt-2.5">
310:             {[5, 10, 14, 15].map(r => (
311:               <button type="button" key={r} onClick={() => set('default_tax_rate', r)} className="px-3 h-7 rounded-full text-[11.5px] font-semibold transition"
312:                 style={rate === r ? { background: 'var(--pill-active-bg)', color: 'var(--pill-active-text)' } : { background: 'var(--bg-subcard)', color: 'var(--text-secondary)' }}>{r}%</button>
313:             ))}
314:           </div>
315: 
316:           <div className="mt-6">
317:             <div className="text-[12.5px] font-semibold mb-2.5" style={{ color: 'var(--text-primary)' }}>طريقة احتساب الأسعار</div>
318:             <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
319:               {[
320:                 { val: true, title: 'الأسعار شاملة الضريبة', en: 'Tax-Inclusive', desc: 'السعر المعروض هو ما يدفعه العميل، وتُستخرج الضريبة منه.' },
321:                 { val: false, title: 'الأسعار غير شاملة الضريبة', en: 'Tax-Exclusive', desc: 'تُضاف الضريبة فوق السعر المعروض عند إصدار الفاتورة.' },
322:               ].map(o => {
323:                 const act = v.prices_include_tax === o.val;
324:                 return (
325:                   <button type="button" key={String(o.val)} onClick={() => set('prices_include_tax', o.val)} className={`v-choice rounded-2xl p-4 text-start ${act ? 'is-on' : ''}`}>
326:                     <div className="flex items-center justify-between">
327:                       <span className="text-[13px] font-semibold" style={{ color: 'var(--text-primary)' }}>{o.title}</span>
328:                       <span className="v-radio"><span /></span>
329:                     </div>
330:                     <div className="text-[10.5px] font-mono mt-0.5" style={{ color: 'var(--accent-orange)' }}>{o.en}</div>
331:                     <div className="text-[11.5px] mt-2 leading-relaxed" style={{ color: 'var(--text-muted)' }}>{o.desc}</div>
332:                   </button>
333:                 );
334:               })}
335:             </div>
336:           </div>
337:         </div>
338:       </SectionCard>
339: 
340:       {Object.entries(errors).filter(([key]) => ['tax_number','default_tax_rate','tax_enabled','prices_include_tax'].includes(key)).map(([key, messages]) => <div role="alert" key={key}>{messages.join('، ')}</div>)}
341:       {/* Live calculator */}
342:       <div className="xl:col-span-2 v-card p-5 xl:sticky xl:top-5">
343:         <div className="flex items-center justify-between">
344:           <h3 className="font-display text-[16px] font-semibold" style={{ color: 'var(--text-primary)' }}>محاكاة حية</h3>
345:           <Badge tone={on ? 'green' : 'neutral'} dot>{on ? (v.prices_include_tax ? 'شامل' : 'غير شامل') : 'بدون ضريبة'}</Badge>
346:         </div>
347:         <p className="text-[11.5px] mt-1" style={{ color: 'var(--text-muted)' }}>غيّر سعر المنتج لترى أثر إعداداتك الحالية.</p>
348: 
349:         <div className="v-subcard p-4 mt-4">
350:           <div className="text-[11.5px] font-medium" style={{ color: 'var(--text-secondary)' }}>سعر المنتج المُدخل</div>
351:           <div className="flex items-baseline gap-2 mt-1">
352:             <input type="number" value={sample} onChange={e => setSample(Math.max(0, Number(e.target.value)))} dir="ltr"
353:               className="bg-transparent outline-none font-display text-[30px] font-bold w-full tabular-nums" style={{ color: 'var(--text-primary)' }} />
354:             <span className="text-[13px] font-semibold shrink-0" style={{ color: 'var(--text-muted)' }}>ج.م</span>
355:           </div>
356:           <input type="range" min="0" max="10000" step="50" value={sample} onChange={e => setSample(Number(e.target.value))} className="v-slider mt-2"
357:             style={{ background: `linear-gradient(to left, #e0491f ${(sample / 10000) * 100}%, var(--toggle-off-bg) ${(sample / 10000) * 100}%)` }} />
358:         </div>
359: 
360:         <div className="mt-4 space-y-0 v-divide">
361:           <div className="flex items-center justify-between py-3 text-[13px]"><span style={{ color: 'var(--text-secondary)' }}>الصافي قبل الضريبة</span><span className="font-semibold tabular-nums" style={{ color: 'var(--text-primary)' }}>{fmtMoney(net)}</span></div>
362:           <div className="flex items-center justify-between py-3 text-[13px]"><span style={{ color: 'var(--text-secondary)' }}>قيمة الضريبة ({on ? rate : 0}%)</span><span className="font-semibold tabular-nums" style={{ color: 'var(--accent-orange)' }}>+ {fmtMoney(tax)}</span></div>
363:         </div>
364: 
365:         <div className="v-orange-earnings rounded-[18px] p-4 mt-2">
366:           <div className="text-[12px] text-white/85">الإجمالي المستحق</div>
367:           <div className="font-display text-[28px] font-bold tabular-nums mt-0.5">{fmtMoney(gross)} <span className="text-[14px] font-medium text-white/80">ج.م</span></div>
368:           <div className="mt-3 h-3 w-full rounded-full overflow-hidden flex items-center gap-1 p-0.5 bg-white/10">
369:             <div className="h-full rounded-full bg-white transition-all duration-300" style={{ width: `${gross ? (net / gross) * 100 : 100}%` }} />
370:             <div className="h-full flex-1 rounded-full rewards-hatched-track" />
371:           </div>
372:           <div className="flex justify-between text-[10.5px] text-white/80 mt-1.5"><span>صافي</span><span>ضريبة</span></div>
373:         </div>
374:       </div>
375:     </div>
376:   );
377: }
