379: /* ---------- Tab 3: Numbering ---------- */
380: function NumberingTab({ errors, v, server, setNum }: { errors: Record<string,string[]>; v: AdminSettings['numbering']; server: AdminSettings['numbering']; setNum: (doc: string, key: string, val: any) => void }) {
381:   const [q, setQ] = useState('');
382:   const docs = DOC_TYPES.filter(d => !q || d.label.includes(q) || d.key.includes(q.toLowerCase()) || v[d.key]?.prefix?.toLowerCase().includes(q.toLowerCase()));
383: 
384:   return (
385:     <SectionCard title="ترقيم المستندات" subtitle="حدد البادئة وطول الرقم والرقم التسلسلي التالي لكل نوع من وثائق النظام."
386:       aside={<div className="v-subcard px-3.5 h-9 rounded-full flex items-center gap-2 shrink-0">
387:         <Icon name="search" className="w-3.5 h-3.5" style={{ color: 'var(--text-muted)' }} />
388:         <input value={q} onChange={e => setQ(e.target.value)} placeholder="بحث عن مستند" className="bg-transparent text-[12.5px] outline-none w-32" style={{ color: 'var(--text-primary)' }} />
389:       </div>}>
390:       {docs.length === 0 && <EmptyState title="لا توجد مستندات مطابقة" text="جرّب البحث باسم المستند أو البادئة مثل INV-." />}
391:       <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
392:         {docs.map(d => {
393:           const n = v[d.key];
394:           if (!n) return null;
395:           const s = server[d.key] || n;
396:           const pad = Math.min(20, Math.max(1, Number(n.padding) || 1));
397:           const preview = `${n.prefix}${String(n.next_number || 0).padStart(pad, '0')}`;
398:           const changed = JSON.stringify(n) !== JSON.stringify(s);
399:           const padErr = n.padding < 1 || n.padding > 20;
400:           const lower = Number(n.next_number) < s.next_number;
401:           return (
402:             <div key={d.key} className={`v-subcard p-4 v-doc ${changed ? 'is-changed' : ''}`}>
403:               <div className="flex items-center justify-between gap-2 mb-3.5">
404:                 <div className="flex items-center gap-2.5 min-w-0">
405:                   <span className="w-8 h-8 rounded-[10px] flex items-center justify-center shrink-0" style={{ background: 'var(--bg-card)', color: 'var(--text-secondary)' }}><Icon name="doc" className="w-4 h-4" /></span>
406:                   <div className="min-w-0">
407:                     <div className="text-[13px] font-semibold truncate" style={{ color: 'var(--text-primary)' }}>{d.label}</div>
408:                     <div className="text-[10.5px] font-mono" style={{ color: 'var(--text-muted)' }}>{d.key}</div>
409:                   </div>
410:                 </div>
411:                 <span dir="ltr" className="v-preview-badge font-mono text-[12px] font-bold px-3 py-1.5 rounded-full truncate max-w-[55%]" title="المستند التالي">{preview}</span>
412:               </div>
413:               <div className="grid grid-cols-[1.1fr_.8fr_1.2fr] gap-2">
414:                 <div>
415:                   <div className="text-[10.5px] font-medium mb-1" style={{ color: 'var(--text-muted)' }}>البادئة</div>
416:                   <input dir="ltr" value={n.prefix} onChange={e => setNum(d.key, 'prefix', e.target.value.toUpperCase())} className="v-mini-input w-full font-mono" />
417:                 </div>
418:                 <div>
419:                   <div className="text-[10.5px] font-medium mb-1" style={{ color: 'var(--text-muted)' }}>حشو الأصفار</div>
420:                   <div className={`v-mini-input flex items-center !px-1 ${padErr ? 'is-error' : ''}`}>
421:                     <button type="button" onClick={() => setNum(d.key, 'padding', Math.max(1, pad - 1))} className="w-6 h-6 rounded-md flex items-center justify-center hover:opacity-60 text-[14px] font-bold" style={{ color: 'var(--text-secondary)' }}>−</button>
422:                     <input dir="ltr" type="number" min="1" max="20" value={n.padding} onChange={e => setNum(d.key, 'padding', Number(e.target.value))} className="bg-transparent outline-none w-full text-center tabular-nums" />
423:                     <button type="button" onClick={() => setNum(d.key, 'padding', Math.min(20, pad + 1))} className="w-6 h-6 rounded-md flex items-center justify-center hover:opacity-60 text-[14px] font-bold" style={{ color: 'var(--text-secondary)' }}>+</button>
424:                   </div>
425:                 </div>
426:                 <div>
427:                   <div className="text-[10.5px] font-medium mb-1" style={{ color: 'var(--text-muted)' }}>الرقم التالي</div>
428:                   <input dir="ltr" type="number" min="1" max="999999999" value={n.next_number} onChange={e => setNum(d.key, 'next_number', Number(e.target.value))} className={`v-mini-input w-full tabular-nums ${lower ? 'is-warn' : ''}`} />
429:                 </div>
430:               </div>
431:               {(['prefix','padding','next_number'] as const).map(key => errors[d.key+'_'+key]?.map(message => <div role="alert" key={key+message} className="text-[11px] v-badge-red">{message}</div>))}
432:               {padErr && <div role="alert" className="text-[11px] v-badge-red">حشو الأصفار يجب أن يكون بين 1 و20</div>}
433:               {lower && <div className="text-[10.5px] mt-2 flex items-center gap-1 font-medium" style={{ color: '#b45309' }}><Icon name="alert" className="w-3 h-3" />رقم أقل من الحالي ({s.next_number}) لا يمكن حفظه</div>}
434:             </div>
435:           );
436:         })}
437:       </div>
438:     </SectionCard>
439:   );
440: }
