442: /* ---------- Tab 4: Returns ---------- */
443: function ReturnsTab({ v, set }: { v: AdminSettings['orders']; set: (k: keyof AdminSettings['orders'], val: any) => void }) {
444:   const d = v.return_window_days;
445:   const mode = d === 0 ? 'off' : d === -1 ? 'unlimited' : 'days';
446:   const [lastDays, setLastDays] = useState(d > 0 ? d : 14);
447:   useEffect(() => { if (d > 0) setLastDays(d); }, [d]);
448: 
449:   const cards = [
450:     { key: 'off', title: 'متوقف', desc: 'لا يُسمح بإرجاع المنتجات نهائياً.', icon: 'ban', val: 0, code: '0' },
451:     { key: 'days', title: 'خلال عدد أيام', desc: 'الإرجاع متاح لمدة محددة من تاريخ تسليم الطلب.', icon: 'calendar', val: lastDays, code: 'n' },
452:     { key: 'unlimited', title: 'غير محدود', desc: 'الإرجاع متاح في أي وقت دون قيود زمنية.', icon: 'infinity', val: -1, code: '-1' },
453:   ];
454: 
455:   const delivered = new Date();
456:   const deadline = new Date(delivered.getTime() + lastDays * 864e5);
457: 
458:   return (
459:     <SectionCard title="سياسة المبيعات والمرتجعات" subtitle="حدد المهلة المسموح خلالها للعميل بإرجاع المنتجات بعد التسليم.">
460:       <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
461:         {cards.map(c => {
462:           const act = mode === c.key;
463:           return (
464:             <button type="button" key={c.key} onClick={() => set('return_window_days', c.val)} className={`v-choice rounded-[18px] p-4 text-start ${act ? 'is-on' : ''}`}>
465:               <div className="flex items-center justify-between">
466:                 <span className={`w-10 h-10 rounded-xl flex items-center justify-center ${act ? 'text-white v-accent-btn' : 'v-icon-well'}`}><Icon name={c.icon} className="w-[18px] h-[18px]" /></span>
467:                 <span className="v-radio"><span /></span>
468:               </div>
469:               <div className="text-[14px] font-semibold mt-3" style={{ color: 'var(--text-primary)' }}>{c.title}</div>
470:               <div className="text-[11.5px] mt-1 leading-relaxed" style={{ color: 'var(--text-muted)' }}>{c.desc}</div>
471:               <div className="text-[10.5px] font-mono mt-2" style={{ color: 'var(--text-muted)' }}>return_window_days = {c.key === 'days' ? lastDays : c.code}</div>
472:             </button>
473:           );
474:         })}
475:       </div>
476: 
477:       <div className="v-collapse" style={{ gridTemplateRows: mode === 'days' ? '1fr' : '0fr' }}>
478:         <div className="overflow-hidden">
479:           <div className="v-subcard p-5 mt-4">
480:             <div className="flex flex-wrap items-center justify-between gap-4">
481:               <div>
482:                 <div className="text-[13px] font-semibold" style={{ color: 'var(--text-primary)' }}>عدد الأيام المسموح بها</div>
483:                 <div className="text-[11.5px]" style={{ color: 'var(--text-muted)' }}>تُحتسب من تاريخ تسليم الطلب للعميل</div>
484:               </div>
485:               <div className="flex items-center gap-2">
486:                 {[7, 14, 30, 60].map(n => (
487:                   <button type="button" key={n} onClick={() => set('return_window_days', n)} className="px-3.5 h-8 rounded-full text-[12px] font-semibold transition"
488:                     style={d === n ? { background: 'var(--pill-active-bg)', color: 'var(--pill-active-text)' } : { background: 'var(--bg-card)', color: 'var(--text-secondary)' }}>{n} يوم</button>
489:                 ))}
490:                 <div className="flex items-center gap-1.5 h-8 ps-3 pe-1 rounded-full" style={{ background: 'var(--bg-card)' }}>
491:                   <input type="number" min="1" max="365" value={d > 0 ? d : lastDays} onChange={e => set('return_window_days', Math.max(1, Number(e.target.value)))} dir="ltr"
492:                     className="bg-transparent outline-none w-10 text-center text-[13px] font-bold tabular-nums" style={{ color: 'var(--text-primary)' }} />
493:                   <span className="text-[11.5px] pe-2" style={{ color: 'var(--text-muted)' }}>يوم</span>
494:                 </div>
495:               </div>
496:             </div>
497:             {/* Timeline */}
498:             <div className="mt-6">
499:               <div className="h-3.5 w-full rounded-full overflow-hidden flex items-center gap-1 p-0.5">
500:                 <div className="h-full rounded-full transition-all duration-500" style={{ width: `${Math.min(100, (lastDays / 90) * 100)}%`, background: 'var(--accent-orange)' }} />
501:                 <div className="h-full flex-1 rounded-full spending-hatched-track" />
502:               </div>
503:               <div className="flex justify-between mt-2.5 text-[11.5px]">
504:                 <span style={{ color: 'var(--text-secondary)' }}><b style={{ color: 'var(--text-primary)' }}>التسليم</b> · {fmtDate(delivered)}</span>
505:                 <span style={{ color: 'var(--text-secondary)' }}>آخر موعد للإرجاع · <b style={{ color: 'var(--accent-orange)' }}>{fmtDate(deadline)}</b></span>
506:               </div>
507:             </div>
508:           </div>
509:         </div>
510:       </div>
511: 
512:       {mode === 'off' && <Notice tone="warn" className="mt-4" title="الإرجاع متوقف">لن يتمكن الموظفون من إنشاء مرتجعات مبيعات جديدة من أي فرع.</Notice>}
513:       {mode === 'unlimited' && <Notice tone="info" className="mt-4">يمكن إرجاع أي طلب مُسلّم دون قيود زمنية، مع خضوع المرتجع لدورة الاعتماد المعتادة.</Notice>}
514:     </SectionCard>
515:   );
516: }
