518: /* ---------- Tab 5: Purchases ---------- */
519: function PurchasesTab({ v, set }: { v: AdminSettings['purchases']; set: (k: keyof AdminSettings['purchases'], val: any) => void }) {
520:   const on = v.allow_self_approve_purchases;
521: 
522:   const Step = ({ who, label, active, icon, last }: { who: string; label: string; active?: boolean; icon: string; last?: boolean }) => (
523:     <div className="flex items-center gap-3 flex-1 min-w-[140px]">
524:       <div className="flex flex-col items-center gap-2 flex-1">
525:         <span className={`w-11 h-11 rounded-full flex items-center justify-center ${active ? 'text-white v-accent-btn' : 'v-icon-well'}`}><Icon name={icon} className="w-[18px] h-[18px]" /></span>
526:         <div className="text-center"><div className="text-[12.5px] font-semibold" style={{ color: 'var(--text-primary)' }}>{label}</div><div className="text-[11px]" style={{ color: 'var(--text-muted)' }}>{who}</div></div>
527:       </div>
528:       {!last && <Icon name="chevLeft" className="w-4 h-4 shrink-0 -mt-8" style={{ color: 'var(--text-muted)' }} />}
529:     </div>
530:   );
531: 
532:   return <>
533:     <SectionCard title="دورة المشتريات" subtitle="التحكم في صلاحيات اعتماد طلبات وأوامر الشراء.">
534:       <div className="v-subcard p-5 flex items-start justify-between gap-5">
535:         <div className="flex items-start gap-3.5">
536:           <span className={`w-11 h-11 rounded-full flex items-center justify-center shrink-0 ${on ? 'v-badge-orange' : 'v-badge-green'}`}><Icon name={on ? 'userCheck' : 'dual'} className="w-5 h-5" /></span>
537:           <div>
538:             <div className="text-[14px] font-semibold" style={{ color: 'var(--text-primary)' }}>السماح بالاعتماد الذاتي لأوامر الشراء</div>
539:             <div className="text-[12px] mt-1 leading-relaxed max-w-[560px]" style={{ color: 'var(--text-secondary)' }}>
540:               هل يحق لنفس الموظف الذي أنشأ طلب/أمر الشراء أن يعتمده بنفسه (إذا كان يملك صلاحية <span className="font-mono text-[11px] px-1.5 py-0.5 rounded" style={{ background: 'var(--bg-card)' }} dir="ltr">purchases.approve</span>)، أم يشترط النظام موافقة موظف أو مدير آخر؟
541:             </div>
542:             <div className="text-[10.5px] font-mono mt-2" style={{ color: 'var(--text-muted)' }} dir="ltr">allow_self_approve_purchases = {String(on)}</div>
543:           </div>
544:         </div>
545:         <Toggle on={on} onChange={x => set('allow_self_approve_purchases', x)} />
546:       </div>
547: 
548:       <div className="mt-5">
549:         <div className="text-[12px] font-semibold mb-4" style={{ color: 'var(--text-muted)' }}>سير العمل الحالي</div>
550:         <div className="flex flex-wrap items-start gap-2">
551:           <Step icon="doc" label="إنشاء أمر الشراء" who="الموظف (أ)" active />
552:           <Step icon={on ? 'userCheck' : 'dual'} label="الاعتماد" who={on ? 'الموظف (أ) نفسه' : 'موظف/مدير آخر (ب)'} active />
553:           <Step icon="truck" label="استلام البضاعة" who="أمين المستودع" last />
554:         </div>
555:       </div>
556: 
557:       {on ? (
558:         <Notice tone="warn" className="mt-5" title="الرقابة الثنائية معطّلة">
