 68: export function Icon({ name, className = 'w-4 h-4', strokeWidth = 1.9, style }: { name: string; className?: string; strokeWidth?: number; style?: CSSProperties }) {
 69:   return (
 70:     <svg className={className} style={style} fill="none" stroke="currentColor" strokeWidth={strokeWidth} viewBox="0 0 24 24">
 71:       {ICON_PATHS[name]}
 72:     </svg>
 73:   );
 74: }
