 76: export function Toggle({ on, onChange, disabled, size = 'md' }: { on: boolean; onChange: (val: boolean) => void; disabled?: boolean; size?: 'sm' | 'md' }) {
 77:   const w = size === 'sm' ? 'w-9 h-5' : 'w-11 h-6';
 78:   const k = size === 'sm' ? 'w-4 h-4' : 'w-5 h-5';
 79:   return (
 80:     <button type="button" role="switch" aria-checked={on} disabled={disabled}
 81:       onClick={() => !disabled && onChange(!on)}
 82:       className={`${w} rounded-full p-0.5 transition-colors duration-200 flex items-center shrink-0 ${disabled ? 'opacity-45 cursor-not-allowed' : ''}`}
 83:       style={{ background: on ? 'var(--accent-orange)' : 'var(--toggle-off-bg)', justifyContent: on ? 'flex-start' : 'flex-end' }}>
 84:       <span className={`${k} rounded-full bg-white shadow-sm block`} />
 85:     </button>
 86:   );
 87: }
