 89: export function Badge({ tone = 'neutral', children, className = '', dot }: { tone?: 'green' | 'red' | 'orange' | 'neutral' | 'dark' | 'outline'; children: ReactNode; className?: string; dot?: boolean }) {
 90:   const tones = {
 91:     green: 'v-badge-green', red: 'v-badge-red',
 92:     orange: 'v-badge-orange', neutral: 'v-badge-neutral', dark: 'v-badge-dark', outline: 'v-badge-outline',
 93:   };
 94:   return (
 95:     <span className={`${tones[tone]} inline-flex items-center gap-1.5 px-2.5 py-[3px] rounded-full text-[11px] font-semibold whitespace-nowrap ${className}`}>
 96:       {dot && <span className="w-1.5 h-1.5 rounded-full" style={{ background: 'currentColor' }} />}
 97:       {children}
 98:     </span>
 99:   );
100: }
