102: export const AVATAR_TONES = [
103:   ['#fde8e1', '#c2410c'], ['#e8e4f7', '#5b4bb7'], ['#dcf3ea', '#11795a'], ['#fbeccc', '#a1620a'],
104:   ['#e2eefb', '#2d6aa8'], ['#f7e1ec', '#b03a72'],
105: ];
