107: export function Avatar({ name, id = 0, size = 36, ring }: { name: string; id?: number; size?: number; ring?: boolean }) {
108:   const parts = name.trim().split(/\s+/);
109:   const initials = (parts[0]?.[0] || '') + (parts[1]?.[0] || '');
110:   const [bg, fg] = AVATAR_TONES[Math.abs(id) % AVATAR_TONES.length];
111:   return (
112:     <div className="rounded-full flex items-center justify-center font-semibold shrink-0 avatar-chip"
113:       style={{ width: size, height: size, background: bg, color: fg, fontSize: size * 0.36, boxShadow: ring ? '0 0 0 2px var(--bg-card), 0 0 0 3.5px var(--accent-orange)' : undefined }}>
114:       {initials}
115:     </div>
116:   );
117: }
118: 
119: export function Field({ label, hint, error, required, children, className = '', aside }: { label: string; hint?: string; error?: string | null; required?: boolean; children: ReactNode; className?: string; aside?: ReactNode }) {
120:   return (
121:     <label className={`block ${className}`}>
122:       <div className="flex items-center justify-between mb-1.5">
123:         <span className="text-[12.5px] font-semibold" style={{ color: 'var(--text-primary)' }}>
124:           {label}{required && <span style={{ color: 'var(--accent-orange)' }}> *</span>}
125:         </span>
126:         {aside}
127:       </div>
128:       {children}
129:       {error ? <div className="text-[11.5px] mt-1.5 font-medium" style={{ color: 'var(--badge-red-text)' }}>{error}</div>
130:         : hint ? <div className="text-[11.5px] mt-1.5" style={{ color: 'var(--text-muted)' }}>{hint}</div> : null}
131:     </label>
132:   );
133: }
134: 
135: export function TextInput({ value, onChange, placeholder, icon, dir, type = 'text', disabled, error, suffix, className = '', ...rest }: {
136:   value: string | number | undefined;
137:   onChange: (v: string) => void;
138:   placeholder?: string;
139:   icon?: string;
140:   dir?: string;
141:   type?: string;
142:   disabled?: boolean;
143:   error?: string | boolean | null;
144:   suffix?: ReactNode;
145:   className?: string;
146:   [key: string]: unknown;
147: }) {
148:   return (
149:     <div className={`v-input flex items-center gap-2 px-3.5 h-11 ${error ? 'is-error' : ''} ${disabled ? 'is-disabled' : ''} ${className}`}>
150:       {icon && <Icon name={icon} className="w-4 h-4 shrink-0" style={{ color: 'var(--text-muted)' }} />}
151:       <input type={type} value={value ?? ''} disabled={disabled} dir={dir} placeholder={placeholder}
152:         onChange={e => onChange(e.target.value)}
153:         className="bg-transparent outline-none w-full text-[13px] h-full" style={{ color: 'var(--text-primary)' }} {...rest} />
154:       {suffix}
155:     </div>
156:   );
157: }
