159: export function useOutside(ref: React.RefObject<HTMLElement | null>, cb: () => void, active: boolean) {
160:   useEffect(() => {
161:     if (!active) return;
162:     const h = (e: MouseEvent) => {
163:       // Document listeners see the shadow host as target; inspect the original path.
164:       if (ref.current && !e.composedPath().includes(ref.current)) cb();
165:     };
166:     document.addEventListener('mousedown', h);
167:     return () => document.removeEventListener('mousedown', h);
168:   }, [active, cb, ref]);
169: }
