171: export interface SelectOption {
172:   value: string | number | null;
173:   label: string;
174:   icon?: string;
175:   meta?: string;
176:   disabled?: boolean;
177: }
178: 
179: export function Select({ value, onChange, options, placeholder = 'اختر', searchable, icon, compact, renderValue, width, disabled }: {
180:   value: string | number | null;
181:   onChange: (v: any) => void;
182:   options: SelectOption[];
183:   placeholder?: string;
184:   searchable?: boolean;
185:   icon?: string;
186:   compact?: boolean;
187:   renderValue?: (cur?: SelectOption) => ReactNode;
188:   width?: number | string;
189:   disabled?: boolean;
190: }) {
191:   const [open, setOpen] = useState(false);
192:   const [q, setQ] = useState('');
193:   const ref = useRef<HTMLDivElement>(null);
194:   useOutside(ref, () => setOpen(false), open);
195:   const cur = options.find(o => o.value === value);
196:   const list = options.filter(o => !q || o.label.includes(q));
197:   return (
198:     <div ref={ref} className="relative" style={{ width }}>
199:       <button type="button" disabled={disabled} onClick={() => setOpen(!open)}
200:         className={compact ? 'v-subcard rounded-full px-3.5 h-9 flex items-center gap-2 text-[12.5px] font-medium w-full hover:opacity-90 transition'
201:           : `v-input flex items-center gap-2 px-3.5 h-11 w-full text-[13px] ${open ? 'is-focus' : ''}`}
202:         style={{ color: 'var(--text-primary)' }}>
203:         {icon && <Icon name={icon} className="w-3.5 h-3.5 shrink-0" style={{ color: 'var(--text-muted)' }} />}
204:         <span className="truncate flex-1 text-start" style={{ color: cur ? 'var(--text-primary)' : 'var(--text-muted)' }}>
205:           {renderValue ? renderValue(cur) : cur ? cur.label : placeholder}
206:         </span>
207:         <Icon name="chevDown" className={`w-3.5 h-3.5 shrink-0 transition-transform ${open ? 'rotate-180' : ''}`} style={{ color: 'var(--text-muted)' }} />
208:       </button>
209:       {open && (
210:         <div className="v-pop absolute z-40 mt-1.5 w-full min-w-[220px] p-1.5 start-0">
211:           {searchable && (
212:             <div className="v-subcard rounded-full px-3 h-9 flex items-center gap-2 mb-1.5">
213:               <Icon name="search" className="w-3.5 h-3.5" style={{ color: 'var(--text-muted)' }} />
214:               <input autoFocus value={q} onChange={e => setQ(e.target.value)} placeholder="بحث..." className="bg-transparent outline-none text-[12.5px] w-full" style={{ color: 'var(--text-primary)' }} />
215:             </div>
216:           )}
217:           <div className="max-h-[240px] overflow-y-auto">
218:             {list.length === 0 && <div className="text-[12px] px-3 py-3 text-center" style={{ color: 'var(--text-muted)' }}>لا توجد نتائج</div>}
219:             {list.map(o => (
220:               <button type="button" key={String(o.value)} disabled={o.disabled}
221:                 onClick={() => { onChange(o.value); setOpen(false); setQ(''); }}
222:                 className={`w-full flex items-center gap-2.5 px-3 py-2 rounded-xl text-[12.5px] text-start transition v-option ${o.value === value ? 'is-active' : ''} ${o.disabled ? 'opacity-40 cursor-not-allowed' : ''}`}>
223:                 {o.icon && <Icon name={o.icon} className="w-3.5 h-3.5 shrink-0" style={{ color: 'var(--text-muted)' }} />}
224:                 <span className="flex-1 truncate">{o.label}</span>
225:                 {o.meta && <span className="text-[11px]" style={{ color: 'var(--text-muted)' }}>{o.meta}</span>}
226:                 {o.value === value && <Icon name="check" className="w-3.5 h-3.5" style={{ color: 'var(--accent-orange)' }} strokeWidth={2.4} />}
227:               </button>
228:             ))}
229:           </div>
230:         </div>
231:       )}
232:     </div>
233:   );
