244: export function MultiSelect({ values, onChange, options, placeholder = 'اختر', disabled }: {
245:   values: (number | string)[];
246:   onChange: (v: (number | string)[]) => void;
247:   options: MultiSelectOption[];
248:   placeholder?: string;
249:   disabled?: boolean;
250: }) {
251:   const [open, setOpen] = useState(false);
252:   const [q, setQ] = useState('');
253:   const ref = useRef<HTMLDivElement>(null);
254:   useOutside(ref, () => setOpen(false), open);
255:   const toggle = (v: number | string) => {
256:     if (disabled || options.find(option => option.value === v)?.disabled) return;
257:     onChange(values.includes(v) ? values.filter(x => x !== v) : [...values, v]);
258:   };
259:   const list = options.filter(o => !q || o.label.includes(q));
260:   return (
261:     <div ref={ref} className="relative">
262:       <div onClick={() => !disabled && setOpen(true)}
263:         className={`v-input flex flex-wrap items-center gap-1.5 px-2 py-1.5 min-h-[44px] cursor-text ${open ? 'is-focus' : ''} ${disabled ? 'is-disabled' : ''}`}>
264:         {values.map(v => {
265:           const o = options.find(x => x.value === v); if (!o) return null;
266:           return (
267:             <span key={v} className="v-chip inline-flex items-center gap-1 ps-2.5 pe-1 h-7 rounded-full text-[12px] font-semibold">
268:               {o.system && <Icon name="shieldCheck" className="w-3 h-3" style={{ color: 'var(--accent-orange)' }} />}
269:               {o.label}
270:               {!disabled && !o.disabled && (
271:                 <button type="button" onClick={e => { e.stopPropagation(); toggle(v); }} className="w-5 h-5 rounded-full flex items-center justify-center hover:opacity-70">
272:                   <Icon name="close" className="w-3 h-3" strokeWidth={2.4} />
273:                 </button>
274:               )}
275:             </span>
276:           );
277:         })}
278:         <input value={q} disabled={disabled} onChange={e => { setQ(e.target.value); setOpen(true); }} onFocus={() => setOpen(true)}
279:           placeholder={values.length ? '' : placeholder}
280:           className="bg-transparent outline-none text-[13px] flex-1 min-w-[80px] px-1.5 h-7" style={{ color: 'var(--text-primary)' }} />
281:       </div>
282:       {open && !disabled && (
283:         <div className="v-pop absolute z-40 mt-1.5 w-full p-1.5 max-h-[260px] overflow-y-auto">
284:           {list.map(o => {
285:             const on = values.includes(o.value);
286:             return (
287:               <button type="button" key={o.value} disabled={o.disabled} onClick={() => toggle(o.value)}
288:                 className={`w-full flex items-center gap-2.5 px-3 py-2 rounded-xl text-[12.5px] text-start v-option ${o.disabled ? 'opacity-40 cursor-not-allowed' : ''}`}>
289:                 <Checkbox checked={on} />
290:                 <span className="flex-1">{o.label}</span>
291:                 {o.system && <Badge tone="orange">نظام</Badge>}
292:                 {o.note && <span className="text-[11px]" style={{ color: 'var(--text-muted)' }}>{o.note}</span>}
293:               </button>
294:             );
295:           })}
296:         </div>
297:       )}
298:     </div>
299:   );
300: }
