312:       onClick={e => { if (onChange && !disabled) { e.stopPropagation(); onChange(!checked); } }}
313:       className={`inline-flex items-center justify-center shrink-0 transition-all duration-150 ${disabled ? 'opacity-50' : 'cursor-pointer'}`}
314:       style={{ width: size, height: size, borderRadius: 6, background: on ? 'var(--accent-orange)' : 'transparent', border: on ? '1.5px solid var(--accent-orange)' : '1.5px solid var(--checkbox-border)' }}>
315:       {checked && !indeterminate && <Icon name="check" className="w-3 h-3 text-white" strokeWidth={3} />}
316:       {indeterminate && <span className="w-2 h-[2px] rounded bg-white" />}
317:     </span>
318:   );
319: }
