504:   text: string;
505:   tone: 'ok' | 'warn' | 'err';
506: }
507: 
508: export const toastBus = { fn: null as ((t: ToastItem) => void) | null };
509: 
510: export function toast(text: string, tone: 'ok' | 'warn' | 'err' = 'ok') {
511:   toastBus.fn && toastBus.fn({ text, tone, id: Date.now() });
512: }
