514: export function ToastHost() {
515:   const [t, setT] = useState<ToastItem | null>(null);
516:   useEffect(() => {
517:     toastBus.fn = v => {
518:       setT(v);
519:       setTimeout(() => setT(c => (c && c.id === v.id ? null : c)), 2600);
520:     };
521:   }, []);
522:   return (
523:     <div className={`fixed top-6 inset-x-0 z-[70] flex justify-center pointer-events-none transition-all duration-300 ${t ? 'opacity-100 translate-y-0' : 'opacity-0 -translate-y-2'}`}>
524:       <div className="px-4 py-2.5 rounded-full shadow-lg text-[12.5px] font-medium flex items-center gap-2" style={{ background: 'var(--pill-active-bg)', color: 'var(--pill-active-text)' }}>
525:         <span className="w-2 h-2 rounded-full" style={{ background: t?.tone === 'err' ? '#fb7185' : t?.tone === 'warn' ? '#f59e0b' : '#34d399' }} />
526:         <span>{t?.text}</span>
527:       </div>
528:     </div>
529:   );
530: }
