 16: interface CartState {
 17:   items: CartItem[];
 18:   busy: boolean;
 19:   loading: boolean;
 20:   error: string | null;
 21:   serverTotal: number;
 22:   identity: string;
 23:   loadCart: () => Promise<boolean>;
 24:   addItem: (variantId: number) => Promise<boolean>;
 25:   removeItem: (id: number) => Promise<boolean>;
 26:   updateQuantity: (id: number, quantity: number) => Promise<boolean>;
 27:   clearCart: () => Promise<boolean>;
 28:   total: () => number;
 29: }
