 31: let queue: Promise<unknown> = Promise.resolve();
 32: let volatileSession: string | null = null;
 33: const identity = () => getAuthToken() ?? 'guest';
 34: const session = () => {
 35:   try { return localStorage.getItem('cart_session') ?? volatileSession; } catch { return volatileSession; }
 36: };
 37: 
 38: export const useCartStore = create<CartState>((set, get) => {
 39:   const apply = (cart: StoreCart) => {
 40:     if (cart.customer_id === null && cart.cart_token) {
 41:       volatileSession = cart.cart_token;
 42:       try { localStorage.setItem('cart_session', cart.cart_token); } catch { /* Keep this tab functional without storage. */ }
 43:     } else if (cart.customer_id !== null) {
 44:       volatileSession = null;
 45:     }
 46:     set({
 47:       items: cart.items.map(item => ({ id: item.id, productId: item.product_id, variantId: item.product_variant_id,
 48:         name: item.product_name || item.sku || 'Product', price: item.unit_price,
 49:         quantity: Number(item.qty), available: Number(item.available) })),
 50:       serverTotal: Number(cart.totals.total),
 51:     });
 52:   };
 53:   const run = (operation: () => Promise<StoreCart>, mutation: boolean): Promise<boolean> => {
 54:     const owner = identity();
 55:     if (get().identity !== owner) set({ items: [], serverTotal: 0, identity: owner, error: null });
 56:     const execute = async (): Promise<boolean> => {
 57:       if (owner !== identity()) return false;
 58:       set({ busy: mutation, loading: !mutation, error: null });
 59:       try {
 60:         const cart = await operation();
 61:         if (owner !== identity()) return false;
 62:         apply(cart);
 63:         if (mutation) {
 64:           try { localStorage.setItem('cart_updated_at', `${Date.now()}:${Math.random()}`); } catch { /* Cross-tab sync is optional when storage is blocked. */ }
 65:         }
 66:         return true;
 67:       } catch (error) {
 68:         if (owner === identity()) {
 69:           const message = (error as { response?: { data?: { message?: string } } }).response?.data?.message;
 70:           set({ error: message || 'We could not update your cart. Please try again.' });
 71:         }
 72:         return false;
 73:       } finally {
 74:         set({ busy: false, loading: false });
 75:       }
 76:     };
 77:     const task = queue.then(async (): Promise<boolean> => {
 78:       if (typeof navigator !== 'undefined' && navigator.locks) return Boolean(await navigator.locks.request('alfarid-store-cart', execute));
 79:       return execute();
 80:     });
 81:     queue = task.catch(() => {});
 82:     return task;
 83:   };
 84:   return {
 85:     items: [], busy: false, loading: false, error: null, serverTotal: 0, identity: 'guest',
 86:     loadCart: () => run(() => cartEndpoints.get(session()), false),
 87:     addItem: (variantId) => run(() => cartEndpoints.add(variantId, 1, session()), true),
 88:     removeItem: (id) => run(() => cartEndpoints.remove(id, session()), true),
 89:     updateQuantity: (id, qty) => {
 90:       if (!Number.isInteger(qty) || qty < 0 || qty > 10000) return Promise.resolve(false);
 91:       return run(() => cartEndpoints.update(id, qty, session()), true);
 92:     },
 93:     clearCart: () => run(async () => {
 94:       const owner = identity();
 95:       let cart = await cartEndpoints.get(session());
 96:       for (const item of cart.items) {
 97:         if (owner !== identity()) throw new Error('Cart session changed.');
 98:         cart = await cartEndpoints.remove(item.id, session());
 99:         if (owner === identity()) apply(cart);
100:       }
101:       return cart;
102:     }, true),
103:     total: () => get().serverTotal,
104:   };
