 2: export function resolveServiceUrl(configured: string): string {
 3:   if (typeof window === 'undefined') return configured;
 4:   const hostname = window.location.hostname;
 5:   const parts = hostname?.split('.').map(Number);
 6:   const privateIpv4 = parts?.length === 4 && parts.every(part => Number.isInteger(part) && part >= 0 && part <= 255)
 7:     && (parts[0] === 10 || (parts[0] === 192 && parts[1] === 168) || (parts[0] === 172 && parts[1] >= 16 && parts[1] <= 31));
 8:   if (!privateIpv4) return configured;
 9:   try {
10:     const url = new URL(configured);
11:     if (!['localhost', '127.0.0.1', '[::1]'].includes(url.hostname)) return configured;
12:     url.hostname = hostname;
13:     return url.href.replace(/\/$/, '');
14:   } catch {
15:     return configured;
16:   }
