103: function invGenMoves() {
104:   const out = [];
105:   const types = Object.keys(INV_MOVE_TYPES);
106:   const refs = { adj_in: 'ADJ', adj_out: 'ADJ', dmg_mark: 'ADJ', dmg_writeoff: 'ADJ', dmg_restore: 'ADJ', tr_out: 'TRF', tr_in: 'TRF', count: 'CNT', production: 'PRD', sale: 'INV' };
107:   let seed = 7;
108:   const rnd = () => { seed = (seed * 9301 + 49297) % 233280; return seed / 233280; };
109:   for (let i = 0; i < 64; i++) {
110:     const st = INV_STOCK[Math.floor(rnd() * INV_STOCK.length)];
111:     const t = types[Math.floor(rnd() * types.length)];
112:     const mt = INV_MOVE_TYPES[t];
113:     const qty = st.variantId === 'v9' ? +(rnd() * 40 + 1).toFixed(2) : Math.ceil(rnd() * 24);
114:     const sign = mt.sign === 0 ? (rnd() > .5 ? 1 : -1) : mt.sign;
115:     const before = Math.round(st.onHand + rnd() * 30);
116:     const day = 23 - Math.floor(i / 5);
117:     const h = String(8 + (i * 7) % 12).padStart(2, '0'), m = String((i * 13) % 60).padStart(2, '0');
118:     out.push({
119:       id: 'm' + i, date: `2026-10-${String(day).padStart(2, '0')} ${h}:${m}`,
120:       ref: `${refs[t]}-2026-${String(1480 - i * 3).padStart(5, '0')}`,
121:       variantId: st.variantId, branchId: st.branchId, locId: st.locId, type: t,
122:       qty: sign * qty, before, after: +(before + sign * qty).toFixed(4),
123:       user: INV_USERS[i % 4], unitCost: invVariant(st.variantId).cost,
124:       note: ['', 'كرتونة مفتوحة', 'مطابقة رصيد افتتاحي', '', 'تلف أثناء النقل', '', 'طلب فرع'][i % 7],
125:     });
126:   }
127:   return out;
128: }
