202:   INV_BRANCHES, INV_LOC_TYPES, INV_LOCATIONS, INV_PRODUCTS, INV_VARIANTS, INV_STOCK, INV_MOVE_TYPES, INV_MOVES,
203:   INV_TR_STATUS, INV_TRANSFERS, INV_CNT_STATUS, INV_COUNTS, INV_PRODUCTION, INV_ROLES, INV_USERS,
204:   invVariant, invBranch, invLoc, invFmt, invMoney,
205: });  1: // ============ Shared Vortix UI primitives (RTL) ============
  2: const { useState, useEffect, useRef, useMemo, useContext, createContext, Fragment } = React;
  3: 
  4: const InvCtx = createContext(null);
  5: const useInv = () => useContext(InvCtx);
  6: const useCan = () => { const { role } = useInv(); return p => INV_ROLES[role].perms.includes(p); };
  7: 
  8: // Simulated fetch lifecycle: loading → (live | empty | error) per demo tweak
  9: function useLoad(dep) {
 10:   const { demoState, reloadKey } = useInv();
 11:   const [phase, setPhase] = useState('loading');
 12:   useEffect(() => {
 13:     setPhase('loading');
 14:     if (demoState === 'loading') return;
 15:     const t = setTimeout(() => setPhase(demoState === 'live' ? 'ready' : demoState), 550);
 16:     return () => clearTimeout(t);
 17:   }, [demoState, reloadKey, dep]);
 18:   return phase;
 19: }
