211: // Wrap list content with phase handling
212: function Phase({ phase, cols, rows, empty, children }) {
213:   if (phase === 'loading') return <SkeletonRows cols={cols} rows={rows} />;
214:   if (phase === 'error') return <ErrorState />;
215:   if (phase === 'empty') return empty;
216:   return children;
