233: // ---------- Modal ----------
234: function Modal({ open, onClose, title, sub, children, footer, width = 'max-w-lg' }) {
235:   useEffect(() => {
236:     if (!open) return;
237:     const h = e => e.key === 'Escape' && onClose && onClose();
238:     window.addEventListener('keydown', h); return () => window.removeEventListener('keydown', h);
239:   }, [open]);
240:   if (!open) return null;
241:   return (
242:     <div className="fixed inset-0 z-50 flex items-center justify-center p-4 fade-in" style={{ background: 'rgba(0,0,0,.4)', backdropFilter: 'blur(4px)' }} onMouseDown={e => e.target === e.currentTarget && onClose && onClose()}>
243:       <div className={`v-card ${width} w-full shadow-2xl modal-in flex flex-col max-h-[92vh]`}>
244:         <div className="flex items-start justify-between gap-4 p-6 pb-4">
245:           <div>
246:             <h3 className="font-display text-[18px] font-semibold c-primary">{title}</h3>
247:             {sub && <p className="text-[12px] c-secondary mt-0.5">{sub}</p>}
248:           </div>
249:           <button onClick={onClose} className="w-8 h-8 rounded-full v-subcard flex items-center justify-center c-secondary shrink-0"><Icon n="x" s={14} /></button>
250:         </div>
251:         <div className="px-6 pb-2 overflow-y-auto flex-1">{children}</div>
252:         {footer && <div className="p-6 pt-4 flex items-center justify-start gap-2.5 flex-row-reverse">{footer}</div>}
253:       </div>
254:     </div>
255:   );
256: }
