286: // ---------- Variant picker: product → variant/SKU (never stops at product) ----------
287: function VariantPicker({ value, onChange, placeholder = 'ابحث بالاسم أو SKU أو الباركود', small, exclude = [], allowClear }) {
288:   const [open, setOpen] = useState(false);
289:   const [q, setQ] = useState('');
290:   const ref = useRef();
291:   useEffect(() => {
292:     const h = e => ref.current && !ref.current.contains(e.target) && setOpen(false);
293:     document.addEventListener('mousedown', h); return () => document.removeEventListener('mousedown', h);
294:   }, []);
295:   const v = value ? invVariant(value) : null;
296:   const ql = q.trim().toLowerCase();
297:   const groups = INV_PRODUCTS.map(p => ({
298:     ...p,
299:     variants: p.variants.filter(x => !exclude.includes(x.id) && (!ql || p.name.includes(q) || x.sku.toLowerCase().includes(ql) || x.barcode.includes(ql) || x.attrs.includes(q))),
300:   })).filter(p => p.variants.length);
301: 
302:   return (
303:     <div ref={ref} className="relative">
304:       <button type="button" onClick={() => setOpen(o => !o)} className={`inp ${small ? 'inp-sm' : ''} flex items-center justify-between gap-2 text-right`}>
305:         {v ? (
306:           <span className="flex items-center gap-2 min-w-0">
307:             <span className="truncate c-primary">{v.productName}</span>
308:             <span className="text-[11px] c-muted shrink-0">{v.attrs}</span>
309:             <span className="mono text-[10.5px] px-1.5 py-0.5 rounded-md shrink-0" style={{ background: 'var(--icon-well-bg)' }}>{v.sku}</span>
310:           </span>
311:         ) : <span className="c-muted truncate">{placeholder}</span>}
312:         <span className="flex items-center gap-1 shrink-0">
313:           {allowClear && v && <span onClick={e => { e.stopPropagation(); onChange(null); }} className="c-muted hover:c-primary"><Icon n="x" s={12} /></span>}
314:           <Icon n="chevD" s={13} className="c-muted" />
315:         </span>
316:       </button>
317:       {open && (
318:         <div className="absolute z-40 mt-1.5 w-full min-w-[320px] v-card shadow-2xl p-2 modal-in" style={{ borderRadius: 16 }}>
319:           <div className="v-subcard px-3 py-2 rounded-xl flex items-center gap-2 mb-1.5">
320:             <Icon n="search" s={14} className="c-muted" />
321:             <input autoFocus value={q} onChange={e => setQ(e.target.value)} placeholder="اسم المنتج، SKU، باركود…" className="bg-transparent text-[12.5px] outline-none flex-1 c-primary" />
322:             <Icon n="barcode" s={14} className="c-muted" />
323:           </div>
324:           <div className="max-h-[260px] overflow-y-auto">
325:             {groups.length === 0 && <div className="text-center text-[12px] c-muted py-6">لا توجد نتائج مطابقة</div>}
326:             {groups.map(p => (
327:               <div key={p.id} className="mb-1">
328:                 <div className="text-[11px] font-semibold c-secondary px-2.5 pt-2 pb-1 flex items-center gap-1.5"><Icon n="box" s={12} /> {p.name} <span className="c-muted font-normal">· {p.variants.length} متغير</span></div>
329:                 {p.variants.map(x => (
330:                   <button type="button" key={x.id} onClick={() => { onChange(x.id); setOpen(false); setQ(''); }}
331:                     className={`w-full flex items-center justify-between gap-3 px-2.5 py-2 rounded-xl text-right hover:bg-[var(--bg-subcard)] ${value === x.id ? 'bg-[var(--bg-subcard)]' : ''}`}>
