 98:     public function withValidator(Validator $validator): void
 99:     {
100:         $allowedKeys = array_values(array_filter(array_keys($this->rules()), fn ($key) => ! str_starts_with($key, 'expected.')));
101:         $body = $this->validationData();
102:         $unknownKeys = array_diff(array_keys($body), $allowedKeys, ['_method', '_token']);
103: 
104:         $validator->after(function (Validator $validator) use ($unknownKeys, $body): void {
105:             $changed = array_diff(array_keys($body), ['expected', '_method', '_token']);
106:             $expected = is_array($body['expected'] ?? null) ? $body['expected'] : [];
107:             foreach (array_diff($changed, array_keys($expected)) as $key) {
108:                 $validator->errors()->add('expected.'.$key, 'القيمة الأصلية مطلوبة لهذا الإعداد.');
