110:             foreach (array_diff(array_keys($expected), $changed) as $key) {
111:                 $validator->errors()->add('expected.'.$key, 'قيمة أصلية غير مرتبطة بإعداد معدل.');
112:             }
113:             foreach ($unknownKeys as $unknownKey) {
114:                 $validator->errors()->add($unknownKey, 'إعداد غير معروف.');
115:             }
116:         });
117:     }
