41: } 1: export interface FormatCurrencyOptions {
 2:   locale?: string;
 3:   currency?: string;
 4:   minimumFractionDigits?: number;
 5:   maximumFractionDigits?: number;
 6: }
 7: 
 8: const formatterCache = new Map<string, Intl.NumberFormat>();
 9: 
10: function getFormatter(locale: string, currency: string, minDigits: number, maxDigits: number): Intl.NumberFormat {
11:   const key = `${locale}_${currency}_${minDigits}_${maxDigits}`;
12:   let formatter = formatterCache.get(key);
13:   if (!formatter) {
14:     formatter = new Intl.NumberFormat(locale, {
15:       style: 'currency',
16:       currency,
17:       minimumFractionDigits: minDigits,
18:       maximumFractionDigits: maxDigits,
19:     });
20:     formatterCache.set(key, formatter);
21:   }
22:   return formatter;
23: }
24: 
25: const egp = new Intl.NumberFormat('en-EG', { style: 'currency', currency: 'EGP', minimumFractionDigits: 0, maximumFractionDigits: 2 });
26: export const formatStorePrice = (v: number) => egp.format(v);
27: 
28: export function formatCurrency(
29:   amount: number | string | null | undefined,
30:   options: FormatCurrencyOptions = {}
31: ): string {
32:   const {
33:     locale = 'ar-EG',
34:     currency = 'EGP',
35:     minimumFractionDigits = 2,
36:     maximumFractionDigits = 2,
37:   } = options;
38: 
39:   const raw = typeof amount === 'string' ? parseFloat(amount) : (amount ?? 0);
40:   const numericAmount = isNaN(raw) ? 0 : raw;
41: 
42:   try {
43:     return getFormatter(locale, currency, minimumFractionDigits, maximumFractionDigits).format(numericAmount);
44:   } catch {
45:     return `${numericAmount.toFixed(minimumFractionDigits)} ${currency}`;
46:   }
