 2:  * Check if the staff user has a specific permission.
 3:  * Matches the staff guard's exact permission names (wildcards are disabled).
 4:  */
 5: export function hasPermission(
 6:   userPermissions: string[] | null | undefined,
 7:   requiredPermission: string
 8: ): boolean {
 9:   if (!userPermissions || !Array.isArray(userPermissions)) {
10:     return false;
11:   }
12: 
13:   if (userPermissions.includes(requiredPermission)) {
14:     return true;
15:   }
16: 
17:   return false;
18: }
19: 
20: export function hasAnyPermission(
21:   userPermissions: string[] | null | undefined,
22:   requiredPermissions: string[]
23: ): boolean {
24:   return requiredPermissions.some((perm) => hasPermission(userPermissions, perm));
25: }
26: 
27: export function hasAllPermissions(
28:   userPermissions: string[] | null | undefined,
29:   requiredPermissions: string[]
30: ): boolean {
31:   return requiredPermissions.every((perm) => hasPermission(userPermissions, perm));
