15: /** تصفح منتجات المتجر: قائمة بفلاتر، وصفحة منتج بالـ slug، ومنتجات مشابهة. كله عام. */
16: class ProductController extends Controller
17: {
18:     public function __construct(private readonly StoreCatalogService $catalog) {}
19: 
20:     public function index(ProductFilterRequest $request): AnonymousResourceCollection
21:     {
22:         $filters = $request->validated();
23:         $total = in_array($filters['sort'] ?? null, ['price_asc', 'price_desc'], true)
24:             && ! isset($filters['price_min']) && ! isset($filters['price_max'])
25:             ? fn () => $this->catalog->applyFilters($this->catalog->publishedQuery(), [...$filters, 'sort' => 'newest'])
26:                 ->reorder()->count('products.id') : null;
27:         $products = $this->catalog->applyFilters($this->catalog->publishedQuery(), $request->validated())
28:             ->paginate(20, total: $total)->withQueryString();
29: 
30:         return StoreProductCardResource::collection($products);
31:     }
32: 
33:     public function show(string $slug): StoreProductResource
34:     {
35:         $product = $this->catalog->publishedQuery()
36:             ->where('products.slug', $slug)
37:             ->firstOrFail();
