17: /** قوائم التصفح الثابتة: أقسام (شجرة بعدّادات منتجات منشورة) وعلامات ومدن الشحن. */
18: class CatalogController extends Controller
19: {
20:     public function categories(Request $request): JsonResponse
21:     {
22:         $roots = Category::query()
23:             ->whereNull('parent_id')
24:             ->where('is_active', true)
25:             ->with('media')
26:             ->withCount('activeProducts')
27:             ->with([
28:                 // L6: id tie-break keeps sibling order deterministic across pages.
29:                 'children' => fn ($q) => $q->where('is_active', true)->with('media')->withCount('activeProducts')->orderBy('sort_order')->orderBy('id')
30:                     ->with(['children' => fn ($q2) => $q2->where('is_active', true)->with('media')->withCount('activeProducts')->orderBy('sort_order')->orderBy('id')]),
31:             ])
32:             ->orderBy('sort_order')->orderBy('id')
33:             ->get();
34: 
35:         return response()->json(['data' => StoreCategoryResource::collection($roots)->resolve($request)]);
36:     }
37: 
38:     /**
39:      * F19: brands are a legacy surface — products no longer accept a brand_id
40:      * (prohibited in admin requests, forced to null in the service) and the
41:      * storefront never filters by brand. This endpoint is retained read-only
42:      * for old clients; do not build new features on it.
43:      */
44:     public function brands(Request $request): JsonResponse
45:     {
46:         $brands = Brand::query()
47:             ->with('media')
48:             ->where('is_active', true)
49:             ->orderBy('sort_order')
50:             ->orderBy('name_ar')
51:             ->get();
52: 
53:         return response()->json(['data' => StoreBrandResource::collection($brands)->resolve($request)]);
54:     }
