56:     public function cities(Request $request): JsonResponse
57:     {
58:         $cities = City::query()
59:             ->where('is_active', true)
60:             ->orderBy('name_ar')
61:             ->get();
62: 
63:         return response()->json(['data' => StoreCityResource::collection($cities)->resolve($request)]);
64:     }
