18: /**
19:  * الصفحة الرئيسية للمتجر: رد مجمّع واحد (بانرات + أحدث + أكثر مبيعًا + مخفضات).
20:  * الكاش يخزن معرّفات الأقسام فقط (5 دقائق) — الأسعار تُحسب لكل طلب على حدة
21:  * لأنها شخصية (خصم مجموعة/سعر خاص)، فلا تتسرب أسعار عميل لزائر آخر أبدًا.
22:  */
23: class HomeController extends Controller
24: {
25:     public function __construct(private readonly StoreCatalogService $catalog) {}
26: 
27:     public function index(Request $request): JsonResponse
28:     {
29:         try {
30:             $load = fn () => Cache::flexible('store_home_data', [300, 1800],
31:                 fn () => $this->catalog->homeSectionIds(), ['seconds' => 120]);
32:             $ids = Cache::has('store_home_data') ? $load() : Cache::lock('store_home_data:build', 120)->block(3, $load);
33:         } catch (LockTimeoutException) {
34:             return response()->json(['message' => 'الصفحة قيد التحديث؛ أعد المحاولة بعد لحظات.'], 503, ['Retry-After' => '2']);
35:         }
36:         $allIds = array_unique([...$ids['latest_ids'], ...$ids['best_seller_ids'], ...$ids['discounted_ids']]);
37:         $cards = StoreProductCardResource::collection($this->catalog->publishedQuery()
38:             ->whereIn('products.id', $allIds)->get())->resolve($request);
39:         $cards = collect($cards)->keyBy('id');
40:         $section = fn (array $sectionIds) => collect($sectionIds)->map(fn ($id) => $cards->get($id))->filter()->values();
41: 
42:         $banners = Banner::query()
43:             ->where('is_active', true)
44:             ->where(fn ($q) => $q->whereNull('starts_at')->orWhere('starts_at', '<=', now()))
45:             ->where(fn ($q) => $q->whereNull('ends_at')->orWhere('ends_at', '>=', now()))
46:             ->orderBy('sort_order')->orderBy('id')->get();
47:         $banners = app(BannerLinkResolver::class)->attach($banners);
48:         $bannersPayload = collect(StoreBannerResource::collection($banners)->resolve($request))
49:             ->filter(fn (array $b) => $b['image'] !== null)
50:             ->values();
51: 
52:         return response()->json([
53:             'data' => [
54:                 'banners' => $bannersPayload,
55:                 'latest_products' => $section($ids['latest_ids']),
56:                 'best_sellers' => $section($ids['best_seller_ids']),
57:                 'discounted_products' => $section($ids['discounted_ids'])->filter(fn ($card) => $card['price'] !== null && $card['discount_percentage'] !== null)->values(),
58:             ],
59:         ]);
60:     }
61: } 1: <?php
