 5: namespace App\Models;
 6: 
 7: use App\Enums\ProductStatus;
 8: use App\Enums\SalesChannel;
 9: use App\Models\Concerns\TracksEditVersion;
10: use Database\Factories\ProductFactory;
11: use Illuminate\Database\Eloquent\Factories\HasFactory;
12: use Illuminate\Database\Eloquent\Model;
13: use Illuminate\Database\Eloquent\Relations\BelongsTo;
14: use Illuminate\Database\Eloquent\Relations\HasMany;
15: use Illuminate\Database\Eloquent\SoftDeletes;
16: use Illuminate\Support\Collection;
17: use Spatie\Image\Enums\Fit;
18: use Spatie\MediaLibrary\HasMedia;
19: use Spatie\MediaLibrary\InteractsWithMedia;
20: use Spatie\MediaLibrary\MediaCollections\Models\Media;
21: 
22: class Product extends Model implements HasMedia
23: {
24:     /** @use HasFactory<ProductFactory> */
25:     use HasFactory, InteractsWithMedia, SoftDeletes, TracksEditVersion;
26: 
27:     protected $fillable = [
28:         'code', 'category_id', 'brand_id', 'supplier_id', 'name_ar', 'name_en', 'slug',
29:         'description_ar', 'description_en', 'material_ar', 'material_en',
30:         'length_cm', 'width_cm', 'height_cm', 'weight_kg', 'warranty_months', 'warranty_details',
31:         'country_of_origin', 'status', 'sales_channel', 'is_featured', 'sales_count', 'published_at', 'created_by', 'create_key', 'create_request_hash',
32:     ];
33: 
34:     protected $casts = [
35:         'status' => ProductStatus::class,
36:         'sales_channel' => SalesChannel::class,
37:         'is_featured' => 'boolean',
38:         'is_active' => 'boolean',
39:         'sales_count' => 'integer',
40:         'published_at' => 'datetime',
41:         'length_cm' => 'decimal:2', 'width_cm' => 'decimal:2', 'height_cm' => 'decimal:2',
42:         'weight_kg' => 'decimal:3',
43:     ];
44: 
45:     public function category(): BelongsTo
46:     {
47:         return $this->belongsTo(Category::class);
48:     }
49: 
50:     public function brand(): BelongsTo
51:     {
52:         return $this->belongsTo(Brand::class);
53:     }
54: 
55:     public function variants(): HasMany
56:     {
57:         // chaperone: كل variant متحمل من العلاقة دي بيبقى عارف منتجه من غير lazy load (N+1)
58:         return $this->hasMany(ProductVariant::class)->orderBy('sort_order')->chaperone();
59:     }
60: 
61:     public function registerMediaCollections(): void
62:     {
63:         $this->addMediaCollection('images')->useDisk('r2_public')->storeConversionsOnDisk('r2_public')
64:             ->acceptsMimeTypes(['image/jpeg', 'image/png', 'image/webp']);
65:         $this->addMediaCollection('video')->singleFile()->useDisk('r2_public')->storeConversionsOnDisk('r2_public')
66:             ->acceptsMimeTypes(['video/mp4', 'video/webm', 'video/quicktime']);
67:     }
68: 
69:     public function catalogImages(): Collection
70:     {
71:         $variants = $this->relationLoaded('variants')
72:             ? $this->variants
73:             : $this->variants()->where('is_active', true)->with('media')->get();
74: 
75:         return $this->getMedia('images')->concat($variants
76:             ->filter(fn ($variant) => $variant->is_active && ! $variant->trashed())
77:             ->flatMap(fn ($variant) => $variant->getMedia('images')))->values();
78:     }
79: 
80:     public function registerMediaConversions(?Media $media = null): void
81:     {
82:         // H2 keeps conversions synchronous but lock-free: each upload runs in its
83:         // own short transaction with no product lock held while R2 I/O renders.
84:         // Queuing them would break per-file atomicity (a failed conversion must
85:         // roll back its own file) that the media pipeline and tests rely on.
86:         $this->addMediaConversion('thumb')->fit(Fit::Crop, 300, 300)->format('webp')
87:             ->performOnCollections('images')->nonQueued();
