 19: /**
 20:  * محرك التسعير المركزي — يُستدعى من المتجر والجملة والـ POS ولوحة الإدارة.
 21:  *
 22:  * شجرة الأولويات:
 23:  * 1. سعر خاص بالعميل (customer_specific)
 24:  * 2. سعر مجموعة العميل (customer_group)
 25:  * 3. قائمة النوع (wholesale/distributor للمعتمدين فقط، وإلا retail)؛ وقناة
 26:  *    جملة/موزع بلا عنصر مطابق ترجع لقوائم retail النشطة قبل السعر الأساسي.
 27:  * 4. السعر الأساسي للمتغير (base_price، المتوافق مع retail_price من المرحلة 2).
 28:  *
 29:  * خصم مجموعة العميل (discount_percentage) لا يصنع مستوى مستقلًا: يُطبق فوق ناتج
 30:  * المستويين 3/4 (سعر القناة)، ولا يُخصم من سعر خاص بالعميل أو سعر قائمة المجموعة.
 31:  * متغير بلا retail_price ولا قائمة مطابقة = غير مُسعَّر، ويرمي BusinessException.
 32:  *
 33:  * داخل كل مستوى: القائمة المخصصة للفرع أولًا، ثم أعلى شريحة كمية محققة،
 34:  * ثم أولوية القائمة، ثم السعر الأقل.
 35:  */
 36: class PricingService
 37: {
 38:     /**
 39:      * F17: preload the per-customer pricing context once per listing and pass
 40:      * it down — resolve()/tiersFor() otherwise re-query the customer group on
 41:      * every variant (15 products x variants x calls per page).
 42:      *
 43:      * @return array{channel: PriceListType, eligible: bool, group: object|null}
 44:      */
 45:     public function contextFor(?Customer $customer, ?array $variantIds = null): array
 46:     {
 47:         $eligible = $customer !== null && $customer->status === CustomerStatus::Approved;
 48:         $group = $eligible ? $customer->customerGroup()->where('is_active', true)->first() : null;
 49: 
 50:         $channel = $this->channelFor($customer);
 51:         $context = ['channel' => $channel, 'eligible' => $eligible, 'group' => $group];
 52:         if ($variantIds !== null) {
 53:             $context['items'] = $this->eligibleItems(null, PHP_FLOAT_MAX, null, Carbon::now(), $variantIds)
 54:                 ->where(function ($q) use ($channel, $eligible, $customer, $group): void {
 55:                     $q->whereIn('price_lists.type', array_unique([$channel->value, PriceListType::Retail->value]));
 56:                     if ($eligible) {
 57:                         $q->orWhere(fn ($owner) => $owner->where('price_lists.type', PriceListType::CustomerSpecific)
 58:                             ->where('price_lists.customer_id', $customer->id));
 59:                     }
 60:                     if ($group !== null) {
 61:                         $q->orWhere(fn ($owner) => $owner->where('price_lists.type', PriceListType::CustomerGroup)
 62:                             ->where('price_lists.customer_group_id', $group->id));
 63:                     }
 64:                 })
 65:                 ->addSelect('price_lists.type as pricing_type', 'price_lists.branch_id as pricing_branch_id', 'price_lists.priority as pricing_priority')
 66:                 ->get()->groupBy('product_variant_id');
 67:         }
 68: 
 69:         return $context;
 70:     }
 71: 
 72:     /** Resolve storefront prices in SQL using the same owner, tier and priority rules as resolve(). */
 73:     public function withStorePrice(Builder $variants, ?Customer $customer): Builder
 74:     {
 75:         $eligible = $customer !== null && $customer->status === CustomerStatus::Approved;
 76:         $channel = $this->channelFor($customer);
 77:         $group = $eligible ? $customer->customerGroup : null;
 78:         $group = $group?->is_active ? $group : null;
 79:         $factor = $this->discountFactor($group?->discount_percentage ?? '0');
 80:         $items = $this->eligibleItems(null, 1, null, Carbon::now())
 81:             ->where(function ($q) use ($eligible, $customer, $group, $channel): void {
 82:                 $q->whereIn('price_lists.type', array_unique([$channel->value, PriceListType::Retail->value]));
 83:                 if ($eligible) {
 84:                     $q->orWhere(fn ($q) => $q->where('price_lists.type', PriceListType::CustomerSpecific)
 85:                         ->where('price_lists.customer_id', $customer->id));
 86:                 }
 87:                 if ($group !== null) {
 88:                     $q->orWhere(fn ($q) => $q->where('price_lists.type', PriceListType::CustomerGroup)
 89:                         ->where('price_lists.customer_group_id', $group->id));
 90:                 }
 91:             })
 92:             ->select([])
 93:             ->selectRaw("price_list_items.price * CASE WHEN price_lists.type IN ('customer_specific', 'customer_group') THEN 1::numeric ELSE ?::numeric END", [$factor])
 94:             ->orderByRaw("CASE WHEN price_lists.type = 'customer_specific' THEN 0 WHEN price_lists.type = 'customer_group' THEN 1 WHEN price_lists.type = ? THEN 2 ELSE 3 END", [$channel->value]);
 95:         $items = $this->ordered($items)->limit(1);
 96: 
 97:         return $variants->select('product_variants.*')
 98:             ->selectRaw('ROUND(COALESCE(('.$items->toSql().'), product_variants.retail_price * ?)::numeric, 2) AS store_price', [...$items->getBindings(), $factor]);
 99:     }
