101:     /**
102:      * @return array{unit_price: float, base_price: float, source: string, price_list_id: int|null}
103:      */
104:     public function resolve(
105:         ProductVariant $variant,
106:         ?Customer $customer = null,
107:         float $qty = 1,
108:         ?int $branchId = null,
109:         ?array $ctx = null,
110:     ): array {
111:         if (! is_finite($qty) || $qty <= 0) {
112:             throw new BusinessException('كمية التسعير يجب أن تكون موجبة.');
113:         }
114:         $now = Carbon::now();
115: 
116:         // F17: reuse the preloaded per-customer context when the caller passes
117:         // it (wholesale listing); otherwise load it for this single call.
118:         $ctx ??= $this->contextFor($customer);
119:         $baseQuery = $this->eligibleItems($variant, $qty, $branchId, $now);
120:         $channel = $ctx['channel'];
121:         $eligibleCustomer = $ctx['eligible'];
122:         $pick = function (PriceListType $type, ?string $ownerField = null, ?int $ownerId = null) use ($ctx, $variant, $qty, $baseQuery, $branchId): ?PriceListItem {
123:             if (isset($ctx['items']) && $branchId === null) {
124:                 return ($ctx['items'][$variant->id] ?? collect())
125:                     ->filter(fn ($item) => $item->pricing_type === $type->value && (float) $item->min_qty <= $qty)
126:                     ->sort(function ($a, $b): int {
127:                         return (($a->pricing_branch_id === null) <=> ($b->pricing_branch_id === null))
128:                             ?: ((float) $b->min_qty <=> (float) $a->min_qty)
129:                             ?: ((int) $b->pricing_priority <=> (int) $a->pricing_priority)
130:                             ?: BigDecimal::of($a->price)->compareTo(BigDecimal::of($b->price))
131:                             ?: ((int) $a->id <=> (int) $b->id);
132:                     })->first();
133:             }
134: 
135:             return $this->ordered((clone $baseQuery)->where('price_lists.type', $type)
136:                 ->when($ownerField !== null, fn ($q) => $q->where('price_lists.'.$ownerField, $ownerId)))->first();
137:         };
138: 
139:         // الأولوية 1: سعر خاص بالعميل
140:         if ($eligibleCustomer) {
141:             $item = $pick(PriceListType::CustomerSpecific, 'customer_id', $customer->id);
142: 
143:             if ($item !== null) {
144:                 return $this->formatResponse($item->price, PriceListType::CustomerSpecific->value, (int) $item->price_list_id, $variant, $channel);
145:             }
146:         }
147: 
148:         // الأولوية 2: سعر مجموعة العميل
149:         $group = $ctx['group'];
150:         if ($group !== null) {
151:             $item = $pick(PriceListType::CustomerGroup, 'customer_group_id', $group->id);
152: 
153:             if ($item !== null) {
154:                 return $this->formatResponse($item->price, PriceListType::CustomerGroup->value, (int) $item->price_list_id, $variant, $channel);
155:             }
156:         }
157: 
158:         // الأولوية 3: قائمة نوع العميل (أو القطاعي افتراضيًا)
159:         $item = $pick($channel);
160: 
161:         // قناة جملة/موزع بلا عنصر في قائمتها ترجع لقوائم القطاعي النشطة قبل
162:         // السعر الأساسي — وإلا دفع عميل الجملة أكثر من عميل التجزئة (M-1).
163:         if ($item === null && $channel !== PriceListType::Retail) {
164:             $item = $pick(PriceListType::Retail);
165: 
166:             if ($item !== null) {
167:                 $channel = PriceListType::Retail;
168:             }
169:         }
170: 
171:         if ($item !== null) {
172:             $channelPrice = (string) $item->price;
173:             $channelListId = (int) $item->price_list_id;
174:             $channelSource = $channel->value;
175:         } elseif ($variant->retail_price === null) {
176:             // الأولوية 4 مستحيلة: لا قائمة مطابقة ولا سعر قطاعي — الصنف غير مُسعَّر
177:             // ولا يجوز أن يخرج بسعر صفر ليُباع مجانًا.
178:             throw new BusinessException('الصنف غير مُسعَّر: لا توجد قائمة أسعار مطابقة ولا سعر قطاعي للمتغير.');
179:         } else {
180:             // الأولوية 4: السعر الأساسي الموحد؛ أسعار الجملة والموزعين تأتي من القوائم.
181:             $channelPrice = $this->basePrice($variant, $channel);
182:             $channelListId = null;
183:             $channelSource = 'base_price';
184:         }
185: 
186:         // خصم مجموعة العميل يُطبق "فوق" سعر القناة المحسوب (قائمة القناة أو الأساسي)،
187:         // ولا يتجاوزه أبدًا — فلا يخسر العميل سعر جملة/موزع أفضل بسبب خصم مجموعته.
188:         if ($group !== null && (float) $group->discount_percentage > 0) {
189:             return $this->formatResponse(
190:                 (string) BigDecimal::of($channelPrice)->multipliedBy($this->discountFactor($group->discount_percentage)),
191:                 'customer_group_discount',
192:                 $channelListId,
193:                 $variant,
194:                 $channel,
195:             );
196:         }
197: 
198:         return $this->formatResponse($channelPrice, $channelSource, $channelListId, $variant, $channel);
199:     }
