201:     /**
202:      * سلم شرائح الكميات الساري لهذا العميل على المتغير: نقاط التحول هي كل
203:      * قيم min_qty في القوائم المؤهلة له (خاصة/مجموعة/قناة/قطاعي احتياطي)،
204:      * وسعر كل شريحة هو ناتج resolve نفسه عند حدّها الأدنى — فالسلم مطابق
205:      * دائمًا لما سيُحصَّل فعليًا عند تلك الكمية.
206:      *
207:      * @return list<array{min_qty: float, unit_price: float}>
208:      */
209:     public function tiersFor(ProductVariant $variant, Customer $customer, ?array $ctx = null): array
210:     {
211:         $now = Carbon::now();
212:         // F17: reuse the preloaded per-customer context when available.
213:         $ctx ??= $this->contextFor($customer);
214:         $channel = $ctx['channel'];
215:         $eligible = $ctx['eligible'];
216:         $groupId = $ctx['group']?->id;
217: 
218:         $breakpoints = isset($ctx['items'])
219:             ? ($ctx['items'][$variant->id] ?? collect())->pluck('min_qty')->map(fn ($v) => (float) $v)
220:             : $this->eligibleItems($variant, PHP_FLOAT_MAX, null, $now)
221:                 ->where(function ($q) use ($eligible, $customer, $groupId, $channel): void {
222:                     $q->where('price_lists.type', $channel->value)
223:                         ->orWhere('price_lists.type', PriceListType::Retail->value);
224:                     if ($eligible) {
225:                         $q->orWhere(fn ($q) => $q->where('price_lists.type', PriceListType::CustomerSpecific)
226:                             ->where('price_lists.customer_id', $customer->id));
227:                     }
228:                     if ($groupId !== null) {
229:                         $q->orWhere(fn ($q) => $q->where('price_lists.type', PriceListType::CustomerGroup)
230:                             ->where('price_lists.customer_group_id', $groupId));
231:                     }
232:                 })
233:                 ->pluck('price_list_items.min_qty')
234:                 ->map(fn ($v) => (float) $v)
235:                 ->unique()
236:                 ->sort()
237:                 ->values();
238: 
239:         $points = collect([1.0])->merge($breakpoints)->unique()->sort()->values();
240: 
241:         return $points
242:             ->map(fn (float $minQty) => [
243:                 'min_qty' => $minQty,
244:                 'unit_price' => $this->resolve($variant, $customer, max(1.0, $minQty), null, $ctx)['unit_price'],
245:             ])
246:             ->values()
247:             ->all();
248:     }
