250:     /** قناة التسعير: الجملة/الموزع للحسابات المعتمدة فقط، وغير ذلك قطاعي. */
251:     private function channelFor(?Customer $customer): PriceListType
252:     {
253:         if ($customer !== null
254:             && in_array($customer->type, [CustomerType::Wholesale, CustomerType::Distributor], true)
255:             && $customer->status === CustomerStatus::Approved) {
256:             return PriceListType::from($customer->type->value);
257:         }
258: 
259:         return PriceListType::Retail;
260:     }
261: 
262:     private function basePrice(ProductVariant $variant, PriceListType $channel): ?string
263:     {
264:         return $variant->retail_price === null ? null : $variant->base_price;
265:     }
266: 
267:     private function discountFactor(string $percentage): string
268:     {
269:         return (string) BigDecimal::of('100')->minus($percentage)->dividedBy('100', 8);
270:     }
271: 
272:     /** كل عناصر التسعير السارية لهذا المتغير والكمية والفرع والوقت. */
273:     private function eligibleItems(?ProductVariant $variant, float $qty, ?int $branchId, Carbon $now, ?array $variantIds = null): Builder
274:     {
275:         return PriceListItem::query()
276:             ->select('price_list_items.*')
277:             ->join('price_lists', 'price_lists.id', '=', 'price_list_items.price_list_id')
278:             ->where('price_lists.is_active', true)
279:             ->when($variant !== null,
280:                 fn ($q) => $q->where('price_list_items.product_variant_id', $variant->id),
281:                 fn ($q) => $variantIds !== null
282:                     ? $q->whereIn('price_list_items.product_variant_id', $variantIds)
283:                     : $q->whereColumn('price_list_items.product_variant_id', 'product_variants.id'))
284:             ->where('price_list_items.min_qty', '<=', $qty)
285:             ->where(fn ($q) => $q->whereNull('price_lists.starts_at')->orWhere('price_lists.starts_at', '<=', $now))
286:             ->where(fn ($q) => $q->whereNull('price_lists.ends_at')->orWhere('price_lists.ends_at', '>=', $now))
287:             ->where(fn ($q) => $q->whereNull('price_list_items.starts_at')->orWhere('price_list_items.starts_at', '<=', $now))
288:             ->where(fn ($q) => $q->whereNull('price_list_items.ends_at')->orWhere('price_list_items.ends_at', '>=', $now))
289:             ->where(function ($q) use ($branchId): void {
290:                 $q->whereNull('price_lists.branch_id');
291:                 if ($branchId !== null) {
292:                     $q->orWhere('price_lists.branch_id', $branchId);
293:                 }
294:             });
295:     }
