297:     /** ترتيب داخل المستوى الواحد: فرع مخصص أولًا، أعلى شريحة، أعلى أولوية، أقل سعر. */
298:     private function ordered(Builder $query): Builder
299:     {
300:         return $query
301:             ->orderByRaw('price_lists.branch_id IS NULL ASC')
302:             ->orderByDesc('price_list_items.min_qty')
303:             ->orderByDesc('price_lists.priority')
304:             ->orderBy('price_list_items.price')->orderBy('price_list_items.id');
305:     }
