307:     /**
308:      * @return array{unit_price: float, base_price: float, source: string, price_list_id: int|null}
309:      */
310:     private function formatResponse(string|float $unitPrice, string $source, ?int $priceListId, ProductVariant $variant, PriceListType $channel): array
311:     {
312:         return [
313:             'unit_price' => (float) (string) BigDecimal::of((string) $unitPrice)->toScale(2, RoundingMode::HalfUp),
314:             'base_price' => (float) (string) BigDecimal::of($this->basePrice($variant, $channel) ?? (string) $unitPrice)->toScale(2, RoundingMode::HalfUp),
315:             'source' => $source,
316:             'price_list_id' => $priceListId,
317:         ];
318:     }
