 45: export interface RegistrationInput {
 46:   name: string;
 47:   phone: string;
 48:   email?: string;
 49:   password: string;
 50:   phone_verification_token?: string;
 51:   company_name?: string;
 52:   tax_number?: string;
 53:   commercial_register?: string;
 54: }
 55: 
 56: interface RegistrationResponse {
 57:   token: string;
 58:   data: Record<string, unknown>;
