 61: export async function registerWeb(input: RegistrationInput, wholesale: boolean, documents: File[] = []) {
 62:   let body: RegistrationInput | FormData = input;
 63:   if (wholesale) {
 64:     body = new FormData();
 65:     Object.entries(input).forEach(([key, value]) => {
 66:       if (value !== undefined && value !== '') (body as FormData).append(key, value);
 67:     });
 68:     documents.forEach((file) => (body as FormData).append('documents[]', file));
 69:   }
 70:   const session = localStorage.getItem(CART_KEY);
 71:   const response = await defaultApiClient.post<RegistrationResponse>(
 72:     wholesale ? '/api/v1/wholesale/auth/register' : '/api/v1/store/auth/register', body,
 73:     { headers: {
 74:       ...(wholesale ? { 'Content-Type': 'multipart/form-data' } : {}),
 75:       ...(!wholesale && session ? { 'X-Cart-Session': session } : {}),
 76:     } },
 77:   );
 78:   const home = wholesale ? '/wholesale/application-status' : '/';
 79:   await revokePreviousSession(response.data.token);
 80:   useAuthStore.getState().setSession({
 81:     token: response.data.token, actorType: 'customer',
 82:     destination: wholesale ? 'wholesale_pending' : 'retail', home, user: response.data.data,
 83:   });
 84:   if (!wholesale) localStorage.removeItem(CART_KEY);
 85:   return home;
 86: }
