23: class CartController extends Controller
24: {
25:     public function __construct(
26:         private readonly CartService $carts,
27:         private readonly CouponService $coupons,
28:     ) {}
29: 
30:     public function index(Request $request): JsonResponse
31:     {
32:         // قراءة فقط: لا يُحفظ صف سلة لمجرد العرض (M3)
33:         [$customer, $cart] = $this->currentCart($request, create: false);
34: 
35:         return response()->json(['data' => $this->carts->present($cart, $customer)]);
36:     }
37: 
38:     public function store(AddCartItemRequest $request): JsonResponse
39:     {
40:         [$customer, $cart] = $this->currentCart($request);
41:         $cart = $this->carts->addItem($cart, $customer, (int) $request->validated()['product_variant_id'], (float) $request->validated()['qty']);
42: 
43:         return response()->json(['data' => $this->carts->present($cart, $customer)]);
44:     }
45: 
46:     public function update(UpdateCartItemRequest $request, int $item): JsonResponse
47:     {
48:         [$customer, $cart] = $this->currentCart($request);
49:         $cartItem = $cart->items()->findOrFail($item);
50:         $cart = $this->carts->updateItemQty($cart, $customer, (int) $cartItem->product_variant_id, (float) $request->validated()['qty']);
51: 
52:         return response()->json(['data' => $this->carts->present($cart, $customer)]);
53:     }
54: 
55:     public function destroy(Request $request, int $item): JsonResponse
56:     {
57:         [$customer, $cart] = $this->currentCart($request);
58:         $cartItem = $cart->items()->findOrFail($item);
59:         $cart = $this->carts->removeItem($cart, (int) $cartItem->product_variant_id);
60: 
61:         return response()->json(['data' => $this->carts->present($cart, $customer)]);
62:     }
63: 
64:     public function removeCoupon(Request $request): JsonResponse
65:     {
66:         [$customer, $cart] = $this->currentCart($request);
67:         $cart->update(['coupon_id' => null]);
68: 
69:         return response()->json(['data' => $this->carts->present($cart->refresh(), $customer)]);
70:     }
71: 
72:     public function applyCoupon(ApplyCouponRequest $request): JsonResponse
73:     {
74:         [$customer, $cart] = $this->currentCart($request);
75:         $totals = $this->carts->totals($cart, $customer);
76:         $discount = $this->coupons->validateAndApply($cart, (string) $request->validated()['code'], $totals['items_total'], $customer);
77: 
78:         return response()->json(['data' => [
79:             'cart' => $this->carts->present($cart->fresh(), $customer),
80:             'coupon_discount' => $discount,
81:         ]]);
82:     }
83: 
84:     /** @return array{0: ?Customer, 1: Cart} */
85:     private function currentCart(Request $request, bool $create = true): array
86:     {
87:         $user = auth('sanctum')->user();
88:         // عميل موقوف/مرفوض بتوكن صالح يُعامل كزائر (F-20): لا تُربط سلاته
89:         // وطلباته بحساب غير نشط ولا تُمنح له أسعار/حدود العميل
90:         $customer = $user instanceof Customer
91:             && ! in_array($user->status, [CustomerStatus::Suspended, CustomerStatus::Rejected], true)
92:                 ? $user
93:                 : null;
94:         $cart = $this->carts->resolveCart($customer, $request->header('X-Cart-Session'), $create);
95: 
96:         return [$customer, $cart];
97:     }
