28: export function createApiClient(config: ApiClientConfig = {}): AxiosInstance {
29:   const envBaseUrl = typeof process !== 'undefined' && process.env 
30:     ? (process.env.NEXT_PUBLIC_API_URL || process.env.VITE_API_URL) 
31:     : undefined;
32: 
33:   const instance = axios.create({
34:     baseURL: resolveServiceUrl(config.baseURL || envBaseUrl || 'http://localhost:8000'),
35:     timeout: 30000,
36:     withCredentials: config.withCredentials ?? false,
37:     headers: {
38:       'Content-Type': 'application/json',
39:       Accept: 'application/json',
40:       'X-Requested-With': 'XMLHttpRequest',
41:     },
42:   });
43: 
44:   instance.interceptors.request.use((reqConfig: InternalAxiosRequestConfig) => {
45:     const existingAuth = reqConfig.headers?.Authorization ?? (reqConfig.headers as Record<string, unknown>)?.['authorization'];
46:     if (existingAuth) {
47:       return reqConfig;
48:     }
49:     const token = config.getToken ? config.getToken() : activeToken;
50:     if (token && reqConfig.headers) {
51:       reqConfig.headers.Authorization = `Bearer ${token}`;
52:     }
53:     return reqConfig;
54:   });
55: 
56:   instance.interceptors.response.use(
57:     (response) => response,
58:     (error) => {
59:       const isSignInRequest = ['/api/v1/auth/login', '/api/v1/auth/handoff/exchange']
60:         .some((path) => error.config?.url?.split('?')[0] === path);
61:       const currentToken = config.getToken ? config.getToken() : activeToken;
62:       const requestAuth = error.config?.headers?.Authorization ?? error.config?.headers?.authorization;
63:       const staleSession = typeof requestAuth === 'string' && requestAuth.startsWith('Bearer ')
64:         && requestAuth !== `Bearer ${currentToken}`;
65:       if (error.response?.status === 401 && !isSignInRequest && !staleSession) {
66:         if (config.onUnauthorized) {
67:           config.onUnauthorized();
68:         } else if (unauthorizedHandler) {
69:           unauthorizedHandler();
70:         }
71:       }
72:       return Promise.reject(error);
73:     }
74:   );
75: 
76:   return instance;
77: }
