 10: use App\Http\Requests\Admin\Product\StoreProductRequest;
 11: use App\Http\Requests\Admin\Product\UpdateProductRequest;
 12: use App\Http\Resources\Admin\ProductResource;
 13: use App\Models\Category;
 14: use App\Models\Product;
 15: use App\Models\ProductVariant;
 16: use App\Services\Catalog\ProductService;
 17: use App\Services\CostAccess;
 18: use App\Services\SearchTerm;
 19: use Illuminate\Http\JsonResponse;
 20: use Illuminate\Http\Request;
 21: use Illuminate\Http\Resources\Json\AnonymousResourceCollection;
 22: use Illuminate\Routing\Controllers\HasMiddleware;
 23: use Illuminate\Routing\Controllers\Middleware;
 24: use Illuminate\Validation\Rule;
