 78:     /**
 79:      * Return all settings grouped by their group name, with values cast to their declared types.
 80:      * Numbering counters are read fresh because they change for every generated document number.
 81:      *
 82:      * @return array<string, array<string, mixed>>
 83:      */
 84:     public function getAllGrouped(): array
 85:     {
 86:         $grouped = $this->staticSettings();
 87: 
 88:         $counters = Setting::query()
 89:             ->whereIn('key', self::NUMBERING_COUNTER_KEYS)
 90:             ->orderBy('key')
 91:             ->get()
 92:             ->mapWithKeys(fn (Setting $setting): array => [
 93:                 $setting->key => $this->castValue($setting->value, $setting->type),
 94:             ])
 95:             ->all();
 96: 
 97:         if (isset($counters['movement_next_number'])) {
 98:             $counters['movement_next_number'] = $this->nextMovementNumber();
 99:         }
100:         foreach (self::SEQUENCE_TYPES as $type => $key) {
101:             if (isset($counters[$key])) {
102:                 $counters[$key] = $this->nextDocumentNumber($type);
103:             }
104:         }
105: 
106:         if ($counters !== []) {
107:             $grouped['numbering'] = array_merge($grouped['numbering'] ?? [], $counters);
108:             ksort($grouped['numbering']);
109:         }
110: 
111:         return $grouped;
112:     }
