114:     private function staticSettings(): array
115:     {
116:         $read = function (): array {
117:             return Setting::query()
118:                 ->whereNotIn('key', self::NUMBERING_COUNTER_KEYS)
119:                 ->orderBy('group')
120:                 ->orderBy('key')
121:                 ->get()
122:                 ->groupBy('group')
123:                 ->map(fn ($settings): array => $settings
124:                     ->mapWithKeys(fn (Setting $setting): array => [
125:                         $setting->key => $this->castValue($setting->value, $setting->type),
126:                     ])
127:                     ->all())
128:                 ->all();
129:         };
130: 
131:         $inTransaction = DB::transactionLevel() > 0;
132:         if ($inTransaction && $this->transactionSnapshot !== null) {
133:             return $this->transactionSnapshot;
134:         }
135:         if ($inTransaction && $this->uncommittedSettings) {
136:             return $this->transactionSnapshot = $read();
137:         }
138:         $version = Cache::get(self::CACHE_VERSION_KEY);
139:         if (! is_string($version)) {
140:             Cache::add(self::CACHE_VERSION_KEY, (string) Str::uuid());
141:             $version = Cache::get(self::CACHE_VERSION_KEY);
142:         }
143: 
144:         $key = self::CACHE_KEY.':'.$version;
145:         if ($inTransaction) {
146:             // Reuse committed cache values, but never publish an uncommitted cache miss.
147:             return $this->transactionSnapshot = Cache::get($key) ?? $read();
148:         }
149: 
150:         return Cache::remember($key, self::CACHE_TTL_SECONDS, $read);
151:     }
