153:     public function get(string $key, mixed $default = null): mixed
154:     {
155:         if (in_array($key, self::NUMBERING_COUNTER_KEYS, true)) {
156:             if ($key === 'movement_next_number') {
157:                 return $this->nextMovementNumber();
158:             }
159:             $type = array_search($key, self::SEQUENCE_TYPES, true);
160:             if (is_string($type)) {
161:                 return $this->nextDocumentNumber($type);
162:             }
163:             $setting = Setting::query()->where('key', $key)->first();
164: 
165:             return $setting ? $this->castValue($setting->value, $setting->type) : $default;
166:         }
167:         foreach ($this->staticSettings() as $settings) {
168:             if (array_key_exists($key, $settings)) {
169:                 return $settings[$key];
170:             }
171:         }
172: 
173:         return $default;
174:     }
