192:     /**
193:      * Update a flat key/value map atomically and invalidate the cached settings after commit.
194:      *
195:      * @param  array<string, mixed>  $settings
196:      *
197:      * @throws JsonException
198:      */
199:     public function updateBatch(array $settings, ?array $expected = null): void
200:     {
201:         $this->warnings = [];
202:         DB::transaction(function () use ($settings, $expected): void {
203:             $this->uncommittedSettings = true;
204:             $this->resetReadSnapshot();
205:             $movementSequenceTarget = null;
206:             /** @var array<string, int> $documentSequenceTargets */
207:             $documentSequenceTargets = [];
208:             $lockedSettings = Setting::query()
209:                 ->whereIn('key', array_keys($settings))
210:                 ->orderBy('key')
211:                 ->lockForUpdate()
212:                 ->get()
213:                 ->keyBy('key');
214: 
215:             $missingKeys = array_diff(array_keys($settings), $lockedSettings->keys()->all());
216: 
217:             if ($missingKeys !== []) {
218:                 throw new InvalidArgumentException('Settings are not initialized: '.implode(', ', $missingKeys));
219:             }
220: 
221:             $before = [];
222:             $after = [];
223:             foreach ($settings as $key => $value) {
224:                 /** @var Setting $setting */
225:                 $setting = $lockedSettings->get($key);
226:                 $current = $this->castValue($setting->value, $setting->type);
227:                 if (in_array($key, self::NUMBERING_COUNTER_KEYS, true)) {
228:                     $current = $this->get($key);
229:                 }
230:                 if ($expected !== null && (! array_key_exists($key, $expected)
231:                     || $this->comparisonValue($current, $setting->type) !== $this->comparisonValue($expected[$key], $setting->type))) {
232:                     abort(409, 'تم تغيير إعداد أو عداد منذ فتح الصفحة؛ أعد تحميل الإعدادات قبل الحفظ.');
233:                 }
234:                 $before[$key] = $current;
235: 
236:                 if (in_array($key, self::NUMBERING_COUNTER_KEYS, true)) {
237:                     $requested = $this->counterValue($value);
238:                     if ($requested > 999999999) {
239:                         throw ValidationException::withMessages([$key => 'الحد الأقصى للعداد هو 999999999.']);
240:                     }
241:                     $value = max($this->counterValue($setting->value), $requested);
242:                     if ($key === 'movement_next_number') {
243:                         $value = max($value, $this->nextMovementNumber());
244:                         $movementSequenceTarget = $value;
245:                     }
246:                     $sequenceType = array_search($key, self::SEQUENCE_TYPES, true);
247:                     if (is_string($sequenceType)) {
248:                         $value = max($value, $this->nextDocumentNumber($sequenceType));
249:                         $documentSequenceTargets[$sequenceType] = $value;
250:                     }
251:                     if ($requested < $value) {
252:                         throw ValidationException::withMessages([$key => 'لا يمكن خفض عداد الترقيم عن قيمته الحالية.']);
253:                     }
254:                 }
255: 
256:                 $setting->value = $value === null && str_ends_with($key, '_prefix')
257:                     ? ''
258:                     : $this->serializeValue($value, $setting->type);
259:                 $setting->save();
260:                 $after[$key] = $this->castValue($setting->value, $setting->type);
261:             }
262: 
263:             StaffAdministration::audit(request()->user('staff'), 'settings.updated', 'settings', null, array_keys($settings),
264:                 ['settings' => $this->auditableSettings($before)], ['settings' => $this->auditableSettings($after)]);
265:             DB::afterCommit(fn () => $this->clearCache());
266: 
267:             if ($movementSequenceTarget !== null) {
268:                 // مزامنة التسلسل بعد الاعتماد لا داخله: ALTER SEQUENCE داخل
269:                 // المعاملة كان يحجب كل nextval (أي كل حركات المخزون) حتى نهاية
270:                 // معاملة الإعدادات (L-9). الدالة تقفل الترقيم لمدة الاستعلام
271:                 // نفسه وتنسّق رفع الحد الأدنى مع كل تخصيص جديد لمنع إعادة رقم.
272:                 DB::afterCommit(function () use ($movementSequenceTarget): void {
273:                     $this->synchronizeSequence(fn () => DB::selectOne('SELECT inventory_movement_number(?) AS number', [$movementSequenceTarget]));
274:                 });
275:             }
276:             if ($documentSequenceTargets !== []) {
277:                 DB::afterCommit(function () use ($documentSequenceTargets): void {
278:                     foreach ($documentSequenceTargets as $type => $minimum) {
279:                         $this->synchronizeSequence(fn () => DB::selectOne('SELECT document_next_number(?, ?) AS number', [$type, $minimum]));
280:                     }
281:                 });
282:             }
283:         }, attempts: 3);
284:     }
