286:     /**
287:      * Atomically return and increment the next document number for the requested type.
288:      *
289:      * @throws JsonException
290:      */
291:     public function generateNextNumber(string $type): string
292:     {
293:         if ($type === 'movement') {
294:             [$prefix, $padding] = $this->numberingConfig('movement', 'movement_prefix', 'movement_padding');
295:             $number = DB::selectOne('SELECT inventory_movement_number() AS number')->number;
296: 
297:             return $prefix.str_pad((string) $number, $padding, '0', STR_PAD_LEFT);
298:         }
299:         if (isset(self::SEQUENCE_TYPES[$type])) {
300:             $definitions = $this->numberingDefinitions();
301:             $definition = $definitions[$type];
302:             [$prefix, $padding] = $this->numberingConfig($type, $definition['prefix'], $definition['padding']);
303:             $number = DB::selectOne('SELECT document_next_number(?) AS number', [$type])->number;
304: 
305:             return $prefix.str_pad((string) $number, $padding, '0', STR_PAD_LEFT);
306:         }
307:         $definitions = $this->numberingDefinitions();
308: 
309:         if (! isset($definitions[$type])) {
310:             throw new InvalidArgumentException("Unsupported numbering type [{$type}].");
311:         }
312: 
313:         $definition = $definitions[$type];
314:         [$prefix, $padding] = $this->numberingConfig($type, $definition['prefix'], $definition['padding']);
315: 
316:         return DB::transaction(function () use ($definition, $prefix, $padding): string {
317:             // العداد وحده يُقفل ويُقرأ طازجًا كل مرة؛ البادئة والحشو من ذاكرة الطلب.
318:             $nextSetting = Setting::query()
319:                 ->where('key', $definition['next'])
320:                 ->lockForUpdate()
321:                 ->first();
322: 
323:             if ($nextSetting === null) {
324:                 throw new InvalidArgumentException("Required numbering setting [{$definition['next']}] is missing.");
325:             }
326: 
327:             $nextValue = $this->counterValue($nextSetting->value);
328: 
329:             $formatted = $prefix.str_pad((string) $nextValue, $padding, '0', STR_PAD_LEFT);
330:             $nextSetting->value = (string) ($nextValue + 1);
331:             $nextSetting->save();
332: 
333:             return $formatted;
334:         }, attempts: 3);
335:     }
336: 
337:     /**
338:      * بادئة وحشو نوع ترقيم — قراءة واحدة لكل طلب بدل استعلام مع كل حركة/مستند.
339:      *
340:      * @return array{0: string, 1: int}
341:      */
342:     private function numberingConfig(string $type, string $prefixKey, string $paddingKey): array
343:     {
344:         return $this->numberingConfig[$type] ??= (function () use ($prefixKey, $paddingKey): array {
345:             $settings = Setting::query()->whereIn('key', [$prefixKey, $paddingKey])->pluck('value', 'key');
346: 
347:             foreach ([$prefixKey, $paddingKey] as $key) {
348:                 if (! $settings->has($key)) {
349:                     throw new InvalidArgumentException("Required numbering setting [{$key}] is missing.");
350:                 }
351:             }
352: 
353:             return [(string) $settings[$prefixKey], max(0, (int) $settings[$paddingKey])];
354:         })();
355:     }
356: 
357:     private function synchronizeSequence(callable $sync): void
358:     {
359:         try {
360:             $sync();
361:         } catch (\Throwable $exception) {
362:             report($exception);
363:             $this->warnings[] = 'تم حفظ الإعدادات، لكن تعذرت مزامنة أحد عدادات الترقيم؛ أعد حفظ العداد للمحاولة مرة أخرى.';
364:         }
365:     }
