367:     public function clearCache(): void
368:     {
369:         Cache::forever(self::CACHE_VERSION_KEY, (string) Str::uuid());
370:         Cache::forget(self::CACHE_KEY); // Retire the cache key used before versioning.
371:         $this->numberingConfig = [];
372:         $this->resetReadSnapshot();
373:     }
