380:     private function auditableSettings(array $settings): array
381:     {
382:         // Only the public administrative settings schema is safe to audit as values.
383:         $allowed = array_keys((new UpdateSettingsRequest)->rules());
384: 
385:         return array_intersect_key($settings, array_flip($allowed));
386:     }
