412:     private function nextMovementNumber(): int
413:     {
414:         $sequence = DB::selectOne('SELECT last_value, is_called FROM stock_movement_number_seq');
415: 
416:         return (int) $sequence->last_value + ($sequence->is_called ? 1 : 0);
417:     }
418: 
419:     private function nextDocumentNumber(string $type): int
420:     {
421:         if (! isset(self::SEQUENCE_TYPES[$type])) {
422:             throw new InvalidArgumentException("Unsupported numbering type [{$type}].");
423:         }
424:         $sequence = DB::selectOne("SELECT last_value, is_called FROM document_{$type}_number_seq");
425: 
426:         return (int) $sequence->last_value + ($sequence->is_called ? 1 : 0);
427:     }
