429:     private function counterValue(mixed $value): int
430:     {
431:         $number = (is_int($value) || is_string($value))
432:             ? filter_var($value, FILTER_VALIDATE_INT, ['options' => ['min_range' => 1, 'max_range' => PHP_INT_MAX - 1]])
433:             : false;
434:         if ($number === false) {
435:             throw new BusinessException('قيمة عداد الترقيم يجب أن تكون عددًا صحيحًا موجبًا ضمن النطاق المسموح');
436:         }
437: 
438:         return $number;
439:     }
440: 
441:     private function castValue(?string $value, string $type): mixed
442:     {
443:         if ($value === null) {
444:             return null;
445:         }
446: 
447:         return match ($type) {
448:             'boolean' => filter_var($value, FILTER_VALIDATE_BOOLEAN),
449:             'integer' => (int) $value,
450:             'float' => (float) $value,
451:             'json' => json_decode($value, true, 512, JSON_THROW_ON_ERROR),
452:             default => $value,
453:         };
454:     }
455: 
456:     /** @throws JsonException */
457:     private function serializeValue(mixed $value, string $type): ?string
458:     {
459:         if ($value === null) {
460:             return null;
461:         }
462: 
463:         if ($type === 'json') {
464:             return json_encode($value, JSON_THROW_ON_ERROR);
465:         }
466: 
467:         if ($type === 'boolean') {
468:             return filter_var($value, FILTER_VALIDATE_BOOLEAN) ? '1' : '0';
469:         }
470: 
471:         return (string) $value;
472:     }
