 20: /**
 21:  * كتالوج المتجر للقراءة: استعلامات التصفح والفلترة وحساب المتاح أونلاين.
 22:  * المتاح أونلاين = مجموع available (on_hand − reserved − damaged) في الفروع
 23:  * النشطة فقط، بحساب SQL مجمّع (بلا تحميل صفوف في الذاكرة).
 24:  * «منتج نشط» في المتجر = منشور (published).
 25:  */
 26: class StoreCatalogService
 27: {
 28:     public function __construct(private readonly PricingService $pricing) {}
 29: 
 30:     // ------------------------------------------------------------------ متاح
 31: 
 32:     /** إرفاق store_available بأي استعلام منتجات: مجموع متاح كل متغيراته في الفروع النشطة. */
 33:     public function withStoreAvailability(Builder $query): Builder
 34:     {
 35:         $sub = DB::table('stock_levels')
 36:             ->join('product_variants', 'product_variants.id', '=', 'stock_levels.product_variant_id')
 37:             ->join('branches', 'branches.id', '=', 'stock_levels.branch_id')
 38:             ->where('branches.is_active', true)
 39:             ->where('product_variants.is_active', true)
 40:             ->whereNull('product_variants.deleted_at')
 41:             ->whereColumn('product_variants.product_id', 'products.id')
 42:             ->selectRaw('COALESCE(SUM(stock_levels.available), 0)');
 43: 
 44:         return $query->select('products.*')->selectSub($sub, 'store_available');
 45:     }
 46: 
 47:     /**
 48:      * خريطة متاح لمتغيرات بعينها في استعلام واحد مجمّع.
 49:      *
 50:      * @param  list<int>  $variantIds
 51:      * @return array<int, float>
 52:      */
 53:     public function availabilityMap(array $variantIds): array
 54:     {
 55:         if ($variantIds === []) {
 56:             return [];
 57:         }
 58: 
 59:         return StockLevel::query()
 60:             ->join('branches', 'branches.id', '=', 'stock_levels.branch_id')
 61:             ->where('branches.is_active', true)
 62:             ->whereIn('stock_levels.product_variant_id', $variantIds)
 63:             ->groupBy('stock_levels.product_variant_id')
 64:             ->selectRaw('stock_levels.product_variant_id, COALESCE(SUM(stock_levels.available), 0) as total')
 65:             ->pluck('total', 'product_variant_id')
 66:             ->map(fn ($v) => (float) $v)
 67:             ->all();
 68:     }
 69: 
 70:     // ------------------------------------------------------------------ أساس
 71: 
 72:     /** استعلام المنتجات المنشورة بعلاقات البطاقة والمتاح المجمّع. */
 73:     public function publishedQuery(): Builder
 74:     {
 75:         $query = Product::query()
 76:             ->where('status', ProductStatus::Published)
 77:             ->whereIn('sales_channel', [SalesChannel::Retail, SalesChannel::Both])
 78:             ->whereHas('category', fn ($q) => $q->where('is_active', true)
 79:                 ->whereDoesntHave('parent', fn ($parent) => $parent->where('is_active', false)
 80:                     ->orWhereHas('parent', fn ($ancestor) => $ancestor->where('is_active', false))))
 81:             ->with([
 82:                 'category', 'media',
 83:                 'variants' => fn ($q) => $this->pricing->withStorePrice($q->getQuery(), $this->customer())
 84:                     ->where('is_active', true)->with('media')->orderBy('sort_order')->orderBy('id'),
 85:             ]);
 86: 
 87:         return $this->withStoreAvailability($query);
 88:     }
 89: 
 90:     // ------------------------------------------------------------------ فلاتر
 91: 
 92:     /**
 93:      * تطبيق فلاتر قائمة المنتجات (ProductFilterRequest) على الاستعلام.
 94:      *
 95:      * @param  array<string, mixed>  $filters
 96:      */
 97:     public function applyFilters(Builder $query, array $filters): Builder
 98:     {
 99:         if (! empty($filters['category'])) {
100:             $category = $this->resolveCategory($filters['category']);
101:             if ($category !== null) {
102:                 $query->whereIn('products.category_id', [$category->id, ...$category->descendantIds()]);
103:             } else {
104:                 $query->whereRaw('1 = 0'); // قسم غير موجود = نتيجة فارغة لا خطأ
105:             }
106:         }
107: 
108:         if (! empty($filters['color'])) {
109:             $color = $filters['color'];
110:             $query->whereHas('variants', fn ($q) => $q->where('is_active', true)
111:                 ->where(fn ($inner) => $inner
112:                     ->whereRaw('LOWER(color_name_en) = LOWER(?)', [$color])
113:                     ->orWhere('color_name_ar', $color)));
114:         }
115: 
116:         if (isset($filters['price_min']) || isset($filters['price_max']) || in_array($filters['sort'] ?? null, ['price_asc', 'price_desc'], true)) {
117:             $query->leftJoinLateral($this->minimumPriceQuery(), 'catalog_price');
118:             if (isset($filters['price_min'])) {
119:                 $query->where('catalog_price.minimum_price', '>=', $filters['price_min']);
120:             }
121:             if (isset($filters['price_max'])) {
122:                 $query->where('catalog_price.minimum_price', '<=', $filters['price_max']);
123:             }
124:         }
125: 
126:         // stock_levels_valid_balances enforces available >= 0 in PostgreSQL,
127:         // so a positive row is equivalent to a positive sum on the card.
128:         if (! empty($filters['in_stock'])) {
129:             $query->whereExists(fn ($sub) => $sub
130:                 ->select(DB::raw(1))
131:                 ->from('stock_levels')
132:                 ->join('product_variants', 'product_variants.id', '=', 'stock_levels.product_variant_id')
133:                 ->join('branches', 'branches.id', '=', 'stock_levels.branch_id')
134:                 ->where('branches.is_active', true)
135:                 ->where('product_variants.is_active', true)
136:                 ->whereNull('product_variants.deleted_at')
137:                 ->whereColumn('product_variants.product_id', 'products.id')
138:                 ->where('stock_levels.available', '>', 0));
139:         }
140: 
141:         return $this->applySort($query, $filters['sort'] ?? 'newest');
142:     }
143: 
144:     private function applySort(Builder $query, string $sort): Builder
145:     {
146:         if (in_array($sort, ['price_asc', 'price_desc'], true)) {
147:             return $query->orderByRaw('catalog_price.minimum_price '.($sort === 'price_asc' ? 'ASC' : 'DESC').' NULLS LAST')
148:                 ->orderBy('products.id');
149:         }
150: 
151:         return match ($sort) {
152:             'best_selling' => $query->orderByDesc('products.sales_count')->orderByDesc('products.id'),
153:             default => $query->orderByDesc('products.created_at')->orderByDesc('products.id'),
154:         };
155:     }
156: 
157:     private function resolveCategory(int|string $value): ?Category
158:     {
159:         $category = Category::query()->where('is_active', true)->where('slug', $value)->first();
160: 
161:         return $category ?? (ctype_digit((string) $value) && strlen((string) $value) <= 18
162:             ? Category::query()->where('is_active', true)->find((int) $value) : null);
163:     }
164: 
165:     // ------------------------------------------------------------------ أسعار العرض
166: 
167:     /**
168:      * سعر عرض بطاقة المنتج: أرخص متغير نشط قابل للتسعير عبر PricingService
169:      * (متغير بلا سعر ولا قائمة يُتخطى بدل كسر القائمة كلها).
170:      *
171:      * @return array{price: float, base_price: float, compare_at: float|null, discount_percentage: int|null, variant_id: int}|null
172:      */
173:     public function displayPrice(Product $product, ?Customer $customer): ?array
174:     {
175:         $variants = $product->relationLoaded('variants')
176:             ? $product->variants
177:             : $product->variants()->where('is_active', true)->orderBy('sort_order')->get();
178: 
179:         $best = null;
180:         foreach ($variants as $variant) {
181:             try {
182:                 $resolved = $this->variantPrice($variant, $customer);
183:             } catch (BusinessException) {
184:                 continue;
185:             }
186: 
187:             $price = (float) $resolved['unit_price'];
188:             $compareAt = $variant->compare_at_price !== null ? (float) $variant->compare_at_price : null;
189:             $basis = max((float) $compareAt, (float) $resolved['base_price']);
190: 
191:             $display = [
192:                 'price' => $price,
193:                 'base_price' => (float) $resolved['base_price'],
194:                 'compare_at' => $basis > $price && (int) round((1 - $price / $basis) * 100) >= 1 ? $basis : null,
195:                 'discount_percentage' => $basis > $price && (int) round((1 - $price / $basis) * 100) >= 1
196:                     ? (int) round((1 - $price / $basis) * 100) : null,
197:                 'variant_id' => $variant->id,
198:             ];
199:             if ($best === null || $price < $best['price']) {
200:                 $best = $display;
201:             }
202:         }
203: 
204:         return $best;
205:     }
206: 
207:     public function customer(): ?Customer
208:     {
209:         $user = auth('sanctum')->user();
210: 
211:         return $user instanceof Customer && $user->status === CustomerStatus::Approved ? $user : null;
212:     }
213: 
214:     public function variantPrice(ProductVariant $variant, ?Customer $customer): array
215:     {
216:         if (! array_key_exists('store_price', $variant->getAttributes())) {
217:             return $this->pricing->resolve($variant, $customer, 1);
218:         }
219:         if ($variant->store_price === null) {
220:             throw new BusinessException('الصنف غير مُسعَّر.');
221:         }
222: 
223:         return ['unit_price' => (float) $variant->store_price, 'base_price' => (float) ($variant->retail_price === null ? $variant->store_price : $variant->base_price)];
224:     }
225: 
226:     private function minimumPriceQuery(): \Illuminate\Database\Query\Builder
227:     {
228:         $variants = $this->pricing->withStorePrice(ProductVariant::query(), $this->customer())
229:             ->where('is_active', true);
230: 
231:         return DB::query()->fromSub($variants, 'priced_variants')
232:             ->selectRaw('MIN(priced_variants.store_price) AS minimum_price')
233:             ->whereColumn('priced_variants.product_id', 'products.id');
234:     }
235: 
236:     // ------------------------------------------------------------------ الرئيسية والتشابه
237: 
238:     /** معرّفات أقسام الصفحة الرئيسية (تُخزَّن مؤقتًا في المتحكم — الأسعار لا تُخزَّن أبدًا). */
239:     public function homeSectionIds(): array
240:     {
241:         $latest = $this->publishedQuery()->reorder()->orderByDesc('products.created_at')->orderByDesc('products.id')->limit(12)->pluck('products.id')->all();
242:         $best = $this->publishedQuery()->reorder()->orderByDesc('products.sales_count')->orderByDesc('products.id')->limit(12)->pluck('products.id')->all();
243: 
244:         $discounted = $this->publishedQuery()->reorder()
245:             ->where(fn ($q) => $q
246:                 ->whereHas('variants', fn ($v) => $v->where('is_active', true)
247:                     ->whereNotNull('retail_price')
248:                     ->whereNotNull('compare_at_price')
249:                     ->whereColumn('compare_at_price', '>', 'base_price'))
250:                 ->orWhereHas('variants', fn ($v) => $v->where('is_active', true)
251:                     ->whereExists(fn ($sub) => $sub->select(DB::raw(1))
252:                         ->from('price_list_items')
253:                         ->join('price_lists', 'price_lists.id', '=', 'price_list_items.price_list_id')
254:                         ->whereColumn('price_list_items.product_variant_id', 'product_variants.id')
255:                         ->where('price_lists.is_active', true)
256:                         ->where('price_lists.type', 'retail')
257:                         ->whereNull('price_lists.branch_id')
258:                         ->where('price_list_items.min_qty', '<=', 1)
259:                         ->where(fn ($w) => $w->whereNull('price_lists.starts_at')->orWhere('price_lists.starts_at', '<=', now()))
260:                         ->where(fn ($w) => $w->whereNull('price_lists.ends_at')->orWhere('price_lists.ends_at', '>=', now()))
261:                         ->where(fn ($w) => $w->whereNull('price_list_items.starts_at')->orWhere('price_list_items.starts_at', '<=', now()))
262:                         ->where(fn ($w) => $w->whereNull('price_list_items.ends_at')->orWhere('price_list_items.ends_at', '>=', now()))
263:                         ->whereColumn('price_list_items.price', '<', 'product_variants.base_price'))))
264:             ->orderByDesc('products.sales_count')->orderByDesc('products.id')
265:             ->limit(12)->pluck('products.id')->all();
266: 
267:         return [
268:             'latest_ids' => $latest,
269:             'best_seller_ids' => $best,
270:             'discounted_ids' => $discounted,
271:         ];
272:     }
273: 
274:     /**
275:      * منتجات مشابهة: نفس القسم الفرعي، والمتوفر أولًا.
276:      *
277:      * @return Collection<int, Product>
278:      */
279:     public function similar(Product $product): Collection
280:     {
281:         return $this->publishedQuery()
282:             ->where('products.id', '!=', $product->id)
283:             ->where(function ($q) use ($product): void {
284:                 $q->where('products.category_id', $product->category_id);
285:             })
286:             ->reorder()
287:             ->orderByRaw('CASE WHEN products.category_id = ? THEN 0 ELSE 1 END', [$product->category_id])
288:             ->withExists(['variants as has_store_stock' => fn ($q) => $q->where('is_active', true)
289:                 ->whereHas('stockLevels', fn ($stock) => $stock->where('available', '>', 0)
290:                     ->whereHas('branch', fn ($branch) => $branch->where('is_active', true)))])
291:             ->orderByDesc('has_store_stock')
292:             ->orderByDesc('products.sales_count')
293:             ->orderByDesc('products.id')
294:             ->limit(8)
295:             ->get();
296:     }
