154:     public function addItem(Cart $cart, ?Customer $customer, int $variantId, float $qty): Cart
155:     {
156:         return DB::transaction(function () use ($cart, $customer, $variantId, $qty): Cart {
157:             // قفل صف السلة (F19): إضافتان متزامنتان تتسلسلان فلا تُحسب
158:             // الكمية على قراءة قديمة ولا يُتجاوز سقف البنود
159:             $cart = Cart::query()->lockForUpdate()->findOrFail($cart->id);
160: 
161:             $variant = $this->purchasableVariant($variantId);
162:             $existing = $cart->items()->where('product_variant_id', $variantId)->first();
163: 
164:             // سقف أصناف السلة (F15): سلة بآلاف البنود تُثقل التسعير وكل عرض
165:             if ($existing === null) {
166:                 $maxLines = (int) config('store.max_cart_lines', 50);
167:                 if ($maxLines > 0 && $cart->items()->count() >= $maxLines) {
168:                     throw new BusinessException("بلغت سلة التسوق سقف الأصناف ({$maxLines})؛ احذف صنفًا قبل الإضافة.");
169:                 }
170:             }
171: 
172:             $targetQty = ($existing !== null ? (float) $existing->qty : 0) + $qty;
173:             $this->assertLineQty($customer, $targetQty);
174:             $this->assertAvailable($variantId, $targetQty);
175:             $this->assertPriced($variant, $customer, $targetQty);
176: 
177:             // كتابة ذرّية UPSERT (F-09): نقرتان متزامنتان على «أضف للسلة»
178:             // كانتا تصطدمان بقيد التفرد عند الإدراج الثاني فتخرج 500 —
179:             // ON CONFLICT تجمع الكمية على الصف نفسه. القراءة أعلاه تبقى
180:             // للتحقق من حد التوفر فقط
181:             CartItem::query()->upsert(
182:                 [[
183:                     'cart_id' => $cart->id,
184:                     'product_variant_id' => $variantId,
185:                     'qty' => $qty,
186:                     'created_at' => now(),
187:                     'updated_at' => now(),
188:                 ]],
189:                 ['cart_id', 'product_variant_id'],
190:                 ['qty' => DB::raw('cart_items.qty + EXCLUDED.qty'), 'updated_at' => now()],
191:             );
192: 
193:             return $cart->fresh('items');
194:         });
195:     }
196: 
197:     public function updateItemQty(Cart $cart, ?Customer $customer, int $variantId, float $qty): Cart
198:     {
199:         if ($qty <= 0) {
200:             return $this->removeItem($cart, $variantId);
201:         }
202: 
203:         return DB::transaction(function () use ($cart, $customer, $variantId, $qty): Cart {
204:             // قفل صف السلة (F19) بنفس منطق addItem
205:             $cart = Cart::query()->lockForUpdate()->findOrFail($cart->id);
206:             $variant = $this->purchasableVariant($variantId);
207:             $this->assertLineQty($customer, $qty);
208:             $this->assertAvailable($variantId, $qty);
209:             $this->assertPriced($variant, $customer, $qty);
210: 
211:             // UPSERT ذرّي بنفس منطق addItem — updateOrCreate كان يصطدم
212:             // بقيد التفرد تحت التزامن (F-09)، وهنا القيمة مطلقة لا تراكمية
213:             CartItem::query()->upsert(
214:                 [[
215:                     'cart_id' => $cart->id,
216:                     'product_variant_id' => $variantId,
217:                     'qty' => $qty,
218:                     'created_at' => now(),
219:                     'updated_at' => now(),
220:                 ]],
221:                 ['cart_id', 'product_variant_id'],
222:                 ['qty' => $qty, 'updated_at' => now()],
223:             );
224: 
225:             return $cart->fresh('items');
226:         });
227:     }
228: 
229:     public function removeItem(Cart $cart, int $variantId): Cart
230:     {
231:         $cart->items()->where('product_variant_id', $variantId)->delete();
232: 
233:         return $cart->fresh('items');
234:     }
235: 
236:     /**
237:      * بنود السلة بأسعار لحظية من PricingService.
238:      * بند غير قابل للتسعير يرجع بـ unit_price = null (العرض يتجاوزه،
239:      * وإتمام الشراء يرفضه — يتحقق المستدعي).
240:      *
241:      * @return array<int, array{variant: ProductVariant, qty: float, unit_price: float|null, base_price: float|null, line_discount: float, line_total: float}>
242:      */
243:     public function pricedLines(Cart $cart, ?Customer $customer): array
244:     {
245:         $cart->loadMissing('items.variant.product');
246:         $lines = [];
247:         foreach ($cart->items as $item) {
248:             $variant = $item->variant;
249:             $qty = (float) $item->qty;
250:             try {
251:                 $resolved = $this->pricing->resolve($variant, $customer, $qty);
252:                 $unit = (float) $resolved['unit_price'];
253:                 $base = (float) $resolved['base_price'];
254:                 $lines[] = [
255:                     'item_id' => $item->id,
256:                     'variant' => $variant,
257:                     'qty' => $qty,
258:                     'unit_price' => $unit,
259:                     'base_price' => $base,
260:                     'line_discount' => round(($base - $unit) * $qty, 2),
261:                     'line_total' => round($unit * $qty, 2),
262:                 ];
263:             } catch (BusinessException) {
264:                 $lines[] = [
265:                     'item_id' => $item->id,
266:                     'variant' => $variant,
267:                     'qty' => $qty,
268:                     'unit_price' => null,
269:                     'base_price' => null,
270:                     'line_discount' => 0.0,
271:                     'line_total' => 0.0,
272:                 ];
273:             }
274:         }
275: 
276:         return $lines;
277:     }
278: 
279:     /**
280:      * ملخص السلة المالي بالأسعار اللحظية.
281:      *
282:      * @return array{subtotal: float, pricing_discount: float, items_total: float, coupon_discount: float, total: float, coupon_code: string|null}
283:      */
284:     /**
285:      * @param  array<int, array<string, mixed>>|null  $lines  بنود محسوبة مسبقًا
286:      *                                                        لتجنب إعادة التسعير (M15)
287:      */
288:     public function totals(Cart $cart, ?Customer $customer, ?array $lines = null): array
289:     {
290:         $lines ??= $this->pricedLines($cart, $customer);
291:         $subtotal = 0.0;
292:         $itemsTotal = 0.0;
293:         foreach ($lines as $line) {
294:             if ($line['unit_price'] === null) {
295:                 continue;
296:             }
297:             // كل سطر يُقرَّب أولًا ثم تُجمع القيم المقرّبة (M17)
298:             $subtotal += round((float) $line['base_price'] * $line['qty'], 2);
299:             $itemsTotal += $line['line_total'];
300:         }
301: 
302:         // الخصم السعري = الفرق بين الإجماليين المقرّبين، لا مجموع فروق
303:         // السطور المقرّبة (F-26) حتى لا يظهر فرق قرش بين العرض والمحصّل.
304:         // ‏(L6) سعر مخصص أعلى من الأساسي لا يصنع خصمًا سالبًا: يُرفع المرجع
305:         // لسعر البيع الفعلي، فلا يزيد الخصم السالب الإجمالي المحصّل.
306:         if ($subtotal < $itemsTotal) {
307:             $subtotal = $itemsTotal;
308:             $pricingDiscount = 0.0;
309:         } else {
310:             $pricingDiscount = round($subtotal - $itemsTotal, 2);
311:         }
312: 
313:         $couponDiscount = 0.0;
314:         $couponCode = null;
315:         if ($cart->coupon_id !== null && $itemsTotal > 0) {
316:             try {
317:                 $coupon = $this->coupons->redeemableById((int) $cart->coupon_id, $itemsTotal, $customer);
318:                 $couponDiscount = $this->coupons->discountFor($coupon, $itemsTotal);
319:                 $couponCode = $coupon->code;
320:             } catch (BusinessException) {
321:                 // كوبون لم يعد صالحًا: يُعرض الملخص بدونه (إتمام الشراء سيعيد التحقق)
322:             }
323:         }
324: 
325:         return [
326:             'subtotal' => round($subtotal, 2),
327:             'pricing_discount' => round($pricingDiscount, 2),
328:             'items_total' => round($itemsTotal, 2),
329:             'coupon_discount' => $couponDiscount,
330:             'total' => round($itemsTotal - $couponDiscount, 2),
331:             'coupon_code' => $couponCode,
332:         ];
333:     }
334: 
335:     /**
336:      * إعادة التحقق من قابلية البيع لكل بند لحظة الشراء بشكل مجمّع (M14):
337:      * متغير معطّل أو منتج غير منشور/محذوف ناعمًا بعد الإضافة يوقف الطلب.
338:      *
339:      * @param  array<int, array{variant: ProductVariant, qty: float}>  $lines
340:      */
341:     public function assertLinesPurchasable(array $lines): void
342:     {
343:         $ids = array_map(fn (array $line): int => (int) $line['variant']->id, $lines);
344:         $variants = ProductVariant::query()->with('product')
345:             ->whereIn('id', $ids)->get()->keyBy('id');
346:         foreach ($lines as $line) {
347:             $variant = $variants->get($line['variant']->id) ?? $line['variant'];
348:             if (! $variant->is_active || $variant->product === null
349:                 || $variant->product->status !== ProductStatus::Published || $variant->product->trashed()) {
350:                 throw new BusinessException("الصنف ({$variant->sku}) لم يعد متاحًا للبيع؛ أزله من السلة وأعد المحاولة.");
351:             }
352:         }
353:     }
354: 
355:     /**
356:      * إعادة التحقق من توفر بنود مُسعّرة لحظة الشراء.
357:      *
358:      * @param  array<int, array{variant: ProductVariant, qty: float}>  $lines
359:      */
360:     public function assertLinesAvailable(array $lines): void
361:     {
362:         $ids = array_map(fn (array $line): int => (int) $line['variant']->id, $lines);
363:         $map = $this->catalog->availabilityMap($ids);
364:         foreach ($lines as $line) {
365:             if (($map[$line['variant']->id] ?? 0) < $line['qty']) {
366:                 throw new BusinessException("الكمية المتاحة من الصنف ({$line['variant']->sku}) لم تعد كافية لإتمام الطلب.");
367:             }
368:         }
369:     }
370: 
371:     /**
372:      * تمثيل السلة للعرض: البنود بأسعار ومتاح لحظي + الملخص المالي.
373:      *
374:      * @return array<string, mixed>
375:      */
376:     public function present(Cart $cart, ?Customer $customer): array
377:     {
378:         $lines = $this->pricedLines($cart, $customer);
379:         $ids = array_map(fn (array $line): int => (int) $line['variant']->id, $lines);
380:         $availability = $this->catalog->availabilityMap($ids);
381: 
382:         $items = [];
383:         foreach ($lines as $line) {
384:             $variant = $line['variant'];
385:             $items[] = [
386:                 'id' => $line['item_id'],
387:                 'product_variant_id' => $variant->id,
388:                 'product_id' => $variant->product_id,
389:                 'product_name' => $variant->product?->name_ar,
390:                 'sku' => $variant->sku,
391:                 'qty' => $line['qty'],
392:                 'unit_price' => $line['unit_price'],
393:                 'base_price' => $line['base_price'],
394:                 'line_discount' => $line['line_discount'],
395:                 'line_total' => $line['line_total'],
396:                 'available' => $availability[$variant->id] ?? 0,
397:                 'priced' => $line['unit_price'] !== null,
398:             ];
399:         }
400: 
401:         return [
402:             'id' => $cart->id,
403:             'cart_token' => $cart->cart_token,
404:             'customer_id' => $cart->customer_id,
405:             'items' => $items,
406:             'totals' => $this->totals($cart, $customer, $lines),
407:         ];
408:     }
409: 
410:     private function purchasableVariant(int $variantId): ProductVariant
411:     {
412:         $variant = ProductVariant::query()->with('product')->find($variantId);
413:         if ($variant === null || ! $variant->is_active || $variant->product === null
414:             || $variant->product->status !== ProductStatus::Published || $variant->product->trashed()) {
415:             throw new BusinessException('الصنف غير متاح للشراء.');
416:         }
417: 
418:         return $variant;
419:     }
420: 
421:     /** سقف كمية البند الواحد (H2): للزوار، وللمسجّلين غير الجملة سقف تجزئة. */
422:     private function assertLineQty(?Customer $customer, float $qty): void
423:     {
424:         $cap = $this->lineQtyCap($customer);
425:         if ($cap > 0 && $qty > $cap) {
426:             throw new BusinessException($customer === null
427:                 ? "سقف كمية البند الواحد للزوار ({$cap}) — سجّل الدخول للكميات الأكبر."
428:                 : "سقف كمية البند الواحد ({$cap}) — للكميات الأكبر تواصل مع مسار الجملة.");
429:         }
430:     }
431: 
432:     /** سقف كمية السطر الفعّال للهوية: 0 = بلا سقف (عملاء الجملة المعتمدون). */
433:     private function lineQtyCap(?Customer $customer): float
434:     {
435:         if ($customer === null) {
436:             return (float) config('store.guest_max_line_qty', 10);
437:         }
438:         if ($customer->status === CustomerStatus::Approved
439:             && in_array($customer->type, [CustomerType::Wholesale, CustomerType::Distributor], true)) {
440:             return 0.0;
441:         }
442: 
443:         return (float) config('store.retail_max_line_qty', 50);
444:     }
445: 
446:     private function assertAvailable(int $variantId, float $qty): void
447:     {
448:         $available = $this->catalog->availabilityMap([$variantId])[$variantId] ?? 0;
449:         if ($available < $qty) {
450:             throw new BusinessException('الكمية المطلوبة غير متاحة حاليًا لهذا الصنف.');
451:         }
452:     }
453: 
454:     private function assertPriced(ProductVariant $variant, ?Customer $customer, float $qty): void
455:     {
456:         $this->pricing->resolve($variant, $customer, $qty); // يرمي BusinessException عند غياب السعر
457:     }
