128: const MULTIPART = { headers: { 'Content-Type': 'multipart/form-data' } };
129: 
130: function categoryFormData(p: CategoryPayload, spoofPut = false): FormData {
131:   const fd = new FormData();
132:   if (spoofPut) fd.append('_method', 'PUT');
133:   const put = (key: string, v: unknown) => {
134:     if (v === undefined) return;                       // مش هيتبعت
135:     if (v === null) return fd.append(key, '');         // Laravel يحوّلها null
136:     if (typeof v === 'boolean') return fd.append(key, v ? '1' : '0'); // مهم: مش "true"
137:     if (v instanceof Blob) return fd.append(key, v);
138:     fd.append(key, String(v));
139:   };
140:   put('parent_id', p.parent_id);
141:   put('name_ar', p.name_ar);
142:   put('name_en', p.name_en);
143:   put('slug', p.slug);
144:   put('description_ar', p.description_ar);
145:   put('description_en', p.description_en);
146:   put('sort_order', p.sort_order);
147:   put('is_active', p.is_active);
148:   if (p.image) put('image', p.image);
149:   if (p.remove_image) put('remove_image', true);
150:   return fd;
151: }
